INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(1, 'cretaceo', 'Cretáceo', 'periodo', 145.0000, 66.0000, 24, 'O Cretáceo foi o último período da Era Mesozoica, iniciado há aproximadamente 145 milhões de anos e encerrado há 66 milhões de anos. Foi marcado pela diversificação dos dinossauros, expansão das plantas com flores e fragmentação dos continentes. Terminou com uma extinção em massa que eliminou os dinossauros não avianos.', 'Os continentes continuavam se separando devido à movimentação das placas tectônicas. A América do Sul e a África se afastavam, enquanto o Oceano Atlântico se expandia. A Índia ainda era uma massa continental isolada, deslocando-se em direção ao norte.', 'O clima global era predominantemente quente, sem grandes calotas polares permanentes. Existiam regiões tropicais, subtropicais e temperadas, com variações de umidade entre os continentes.', 'O nível dos mares era elevado, provocando a formação de extensos mares rasos sobre áreas continentais. Os oceanos apresentavam grande diversidade de organismos, incluindo amonites, moluscos, peixes e répteis marinhos.', 'As coníferas, cicadáceas, samambaias e outras plantas sem flores eram comuns. As angiospermas, ou plantas com flores, surgiram e se diversificaram significativamente durante esse período.', 'Os ambientes terrestres incluíam florestas, planícies aluviais, regiões áridas e áreas pantanosas. Os ambientes aquáticos abrangiam rios, lagos, mares rasos e oceanos.', 'Os dinossauros dominaram muitos ecossistemas terrestres, incluindo grandes predadores, herbívoros e pequenos terópodes emplumados. Pterossauros ocupavam os céus, enquanto répteis marinhos, amonites, peixes, aves primitivas e mamíferos também diversificavam os ecossistemas.', 'O Cretáceo terminou há aproximadamente 66 milhões de anos, durante um dos maiores eventos de extinção da história da Terra. O impacto de um asteroide na região da atual Península de Yucatán, associado a intensas mudanças ambientais, contribuiu para o desaparecimento dos dinossauros não avianos. Apesar disso, aves, descendentes de dinossauros terópodes, sobreviveram.'),
(2, 'cretaceo-superior', 'Cretáceo Superior', 'epoca', 100.5000, 66.0000, 1, 'O Cretáceo Superior corresponde à última época do Cretáceo, entre aproximadamente 100,5 e 66 milhões de anos atrás. Foi marcado pela grande diversidade de dinossauros, expansão das plantas com flores e mudanças na configuração dos continentes e dos oceanos.', 'A fragmentação de Gondwana continuava, com a separação progressiva da América do Sul, África, Antártida, Austrália e Índia. A América do Norte apresentava uma extensa via marítima interior que dividia o continente em regiões ocidental e oriental.', 'O clima era predominantemente quente, embora apresentasse variações regionais e oscilações ao longo da época. As regiões polares eram mais amenas que atualmente e não possuíam grandes calotas de gelo permanentes.', 'Os mares apresentavam níveis elevados e extensas áreas continentais estavam inundadas. A vida marinha incluía amonites, rudistas, peixes ósseos, tubarões e grandes répteis marinhos, como mosassauros e plesiossauros.', 'As plantas com flores se diversificaram e passaram a ocupar diferentes ambientes. Coníferas, samambaias e cicadáceas continuavam presentes, formando florestas e outras comunidades vegetais.', 'Existiam florestas, planícies aluviais, pântanos, regiões costeiras e ambientes desérticos. Grandes rios e mares interiores criavam ecossistemas variados em diferentes continentes.', 'Tyrannosaurus rex, Triceratops, Ankylosaurus e diversos outros dinossauros viveram durante essa época. Aves primitivas, pequenos mamíferos, pterossauros, crocodilianos e uma grande variedade de animais marinhos também estavam presentes.', 'Durante o Cretáceo Superior, os dinossauros alcançaram grande diversidade. Tyrannosaurus rex, Triceratops e Ankylosaurus viveram nessa época. Também ocorreu a expansão e diversificação das plantas com flores, que passaram a desempenhar um papel cada vez mais importante nos ecossistemas terrestres.'),
(3, 'permiano', 'Permiano', 'periodo', 298.9000, 251.9020, 23, 'O Permiano foi o último período da Era Paleozoica, iniciado há aproximadamente 298,9 milhões de anos e encerrado há 251,9 milhões de anos. Foi caracterizado pela formação de Pangeia, expansão de ambientes continentais secos e diversificação dos sinapsídeos e répteis. Terminou com a maior extinção em massa conhecida.', 'Quase todas as grandes massas continentais estavam reunidas no supercontinente Pangeia, cercado pelo imenso oceano Panthalassa. O mar de Tétis ocupava uma região entre as porções setentrionais e meridionais do supercontinente.', 'O clima apresentava grandes contrastes regionais. O interior de Pangeia era predominantemente árido e sujeito a temperaturas extremas, enquanto regiões costeiras apresentavam maior umidade. As condições glaciais herdadas do Carbonífero diminuíram progressivamente.', 'O Panthalassa dominava a superfície oceânica, enquanto o mar de Tétis ocupava uma importante região tropical. Os oceanos abrigavam braquiópodes, moluscos, amonites, equinodermos, peixes e diversos organismos recifais.', 'As coníferas, ginkgófitas, cicadáceas primitivas e samambaias com sementes ganharam importância. Em regiões úmidas ainda existiam comunidades de plantas adaptadas a solos alagados.', 'Os ambientes incluíam desertos, planícies áridas, florestas sazonais, regiões costeiras e ambientes aquáticos continentais. Lagos e rios eram importantes em diferentes regiões de Pangeia.', 'Os ecossistemas terrestres apresentavam grande diversidade de sinapsídeos, como pelicossauros e terápsidos, além de répteis, anfíbios e insetos. Nos oceanos existiam peixes, moluscos, braquiópodes e outros invertebrados.', 'O Permiano terminou com a maior extinção em massa conhecida da história da Terra, há aproximadamente 252 milhões de anos. Esse evento provocou o desaparecimento de uma enorme quantidade de espécies marinhas e terrestres. Entre os animais que viveram nesse período estavam os terápsidos, grupo que inclui os ancestrais dos mamíferos.'),
(4, 'pleistoceno', 'Pleistoceno', 'epoca', 2.5800, 0.0117, 5, 'O Pleistoceno foi uma época do Quaternário iniciada há aproximadamente 2,58 milhões de anos e encerrada há cerca de 11.700 anos. Foi marcado por sucessivas glaciações, grandes oscilações climáticas e pela presença de uma megafauna diversificada. Também ocorreu a expansão de diferentes espécies humanas pelo planeta.', 'Os continentes já apresentavam posições próximas das atuais. Entretanto, durante as glaciações, grandes quantidades de água ficavam retidas nas geleiras, provocando a redução do nível dos mares e a exposição de pontes terrestres, como a região de Bering.', 'O clima alternava entre períodos glaciais frios e períodos interglaciais mais quentes. Grandes geleiras avançavam sobre partes da América do Norte, Europa e Ásia, enquanto regiões tropicais também apresentavam mudanças de temperatura e precipitação.', 'O nível dos oceanos oscilava significativamente conforme a quantidade de água armazenada nas geleiras. Durante os períodos glaciais, extensas áreas de plataformas continentais ficavam expostas, modificando os ambientes costeiros e a distribuição dos organismos marinhos.', 'A vegetação variava conforme as mudanças climáticas. Gramíneas e ervas dominavam muitas estepes frias, enquanto tundras, florestas de coníferas e florestas temperadas ocupavam diferentes regiões do planeta.', 'Os ambientes incluíam estepes, tundras, florestas, desertos e regiões cobertas por geleiras. Grandes planícies abertas eram comuns em várias regiões, oferecendo condições favoráveis para grandes herbívoros.', 'A megafauna incluía mamutes, mastodontes, rinocerontes-lanosos, preguiças-gigantes, tigres-dentes-de-sabre e outros grandes mamíferos. Também existiam aves, répteis, pequenos mamíferos e diferentes espécies humanas, incluindo Homo sapiens.', 'O Pleistoceno ficou conhecido pelas diversas glaciações, períodos em que grandes extensões dos continentes foram cobertas por geleiras. Também foi a época de muitos animais da chamada megafauna, como mamutes, tigres-dentes-de-sabre e preguiças-gigantes. A espécie humana também se espalhou por diferentes regiões do planeta.'),
(5, 'quaternario', 'Quaternário', 'periodo', 2.5800, 0.0000, 25, 'O Quaternário é o período geológico mais recente da Era Cenozoica, iniciado há aproximadamente 2,58 milhões de anos e que continua até os dias atuais. É caracterizado por importantes oscilações climáticas, expansão das espécies humanas e transformações nos ecossistemas terrestres e marinhos.', 'Os continentes apresentam configurações próximas das atuais, embora o nível dos oceanos tenha variado bastante ao longo do período. As placas tectônicas continuam se movimentando, modificando lentamente a superfície terrestre.', 'O clima foi marcado por ciclos de glaciações e períodos interglaciais durante o Pleistoceno, seguidos pelo clima relativamente estável do Holoceno. As atividades humanas passaram a exercer influência crescente sobre o clima e os ecossistemas.', 'Os oceanos sofreram oscilações no nível do mar relacionadas às mudanças no volume das geleiras. No Holoceno, o nível marinho tornou-se relativamente estável, permitindo a formação e transformação de diversas regiões costeiras.', 'A vegetação apresenta os principais grupos de plantas atuais, incluindo gramíneas, coníferas, angiospermas e diferentes formações florestais. Sua distribuição foi influenciada pelas mudanças climáticas e, mais recentemente, pelas atividades humanas.', 'Os ambientes incluem florestas tropicais e temperadas, savanas, pradarias, desertos, tundras, regiões polares, rios, lagos e oceanos. Muitos ecossistemas foram modificados pela expansão da agricultura, urbanização e outras atividades humanas.', 'O período apresenta grande diversidade de mamíferos, aves, répteis, anfíbios, peixes e invertebrados. A evolução e dispersão humana transformaram os ecossistemas, enquanto diversas espécies de megafauna foram extintas durante o Pleistoceno e o início do Holoceno.', 'O Quaternário é o período geológico atual. Ele inclui o Pleistoceno e o Holoceno, época em que vivemos. É marcado por importantes oscilações climáticas, pela expansão da humanidade e pelo desenvolvimento das sociedades humanas.'),
(6, 'cretaceo-inferior', 'Cretáceo Inferior', 'epoca', 145.0000, 100.5000, 1, 'O Cretáceo Inferior corresponde à primeira época do Cretáceo, iniciada há aproximadamente 145 milhões de anos e encerrada há 100,5 milhões de anos. Foi marcado pela fragmentação dos continentes, diversificação dos dinossauros e surgimento das primeiras plantas com flores conhecidas.', 'Gondwana e Laurásia continuavam em processo de fragmentação. A América do Sul e a África iniciavam sua separação, enquanto o Oceano Atlântico Sul começava a se desenvolver. Outras massas continentais também apresentavam movimentação progressiva.', 'O clima era geralmente quente, com variações regionais de umidade. Algumas regiões apresentavam condições áridas e semiáridas, enquanto outras possuíam ambientes úmidos e florestais.', 'Os oceanos estavam em expansão devido à separação dos continentes. Mares rasos ocupavam algumas regiões continentais, abrigando amonites, moluscos, peixes, répteis marinhos e diversos organismos planctônicos.', 'Coníferas, cicadáceas, samambaias e outras plantas sem flores eram predominantes. As primeiras angiospermas surgiram durante o Cretáceo Inferior e começaram sua diversificação.', 'Os ambientes terrestres incluíam florestas, planícies fluviais, lagos, pântanos e regiões áridas. Ambientes costeiros e marinhos rasos também estavam presentes em diferentes partes dos continentes.', 'Diversos grupos de dinossauros estavam presentes, incluindo saurópodes, terópodes e ornitópodes. Pterossauros, aves primitivas, pequenos mamíferos, anfíbios, répteis e organismos marinhos também apresentavam grande diversidade.', 'O Cretáceo Inferior foi marcado pela fragmentação gradual dos continentes e pela diversificação de diversos grupos de dinossauros. As primeiras plantas com flores conhecidas também surgiram durante esse intervalo, transformando progressivamente os ambientes terrestres.'),
(7, 'maastrichtiano', 'Maastrichtiano', 'idade', 72.2000, 66.0000, 2, 'O Maastrichtiano foi a última idade do Cretáceo, entre aproximadamente 72,2 e 66 milhões de anos atrás. Representa os últimos milhões de anos da Era dos Dinossauros não avianos e terminou com a extinção em massa do final do Cretáceo.', 'Os continentes estavam relativamente separados, com a América do Sul e a África em processo avançado de afastamento. A América do Norte apresentava uma extensa via marítima interior, enquanto a Índia continuava sua trajetória em direção à Ásia.', 'O clima era predominantemente quente, embora apresentasse mudanças de temperatura e umidade entre as regiões. Próximo ao final da idade, alterações ambientais ocorreram em associação ao evento de extinção em massa.', 'Os mares continuavam elevados em muitas regiões. A vida marinha incluía amonites, mosassauros, plesiossauros, peixes, tubarões e invertebrados. O impacto do asteroide no final do Maastrichtiano provocou alterações profundas nos ecossistemas oceânicos.', 'As angiospermas estavam amplamente diversificadas, formando parte importante da vegetação terrestre. Coníferas, samambaias e outras plantas também compunham as florestas e planícies.', 'Existiam planícies aluviais, florestas, pântanos, ambientes costeiros e regiões semiáridas. Na América do Norte, extensos sistemas fluviais e planícies úmidas sustentavam grandes comunidades de dinossauros.', 'Tyrannosaurus rex, Triceratops, Ankylosaurus e outros dinossauros viveram nesse intervalo. Também existiam aves, mamíferos, pterossauros, crocodilianos, tartarugas, amonites e répteis marinhos. A extinção do final do Maastrichtiano eliminou os dinossauros não avianos.', 'O Maastrichtiano foi a última idade do Cretáceo e terminou com a extinção em massa de aproximadamente 66 milhões de anos atrás. Tyrannosaurus rex, Triceratops e Ankylosaurus estão entre os dinossauros conhecidos desse intervalo.'),
(8, 'campaniano', 'Campaniano', 'idade', 83.6000, 72.2000, 2, 'O Campaniano ocorreu entre aproximadamente 83,6 e 72,2 milhões de anos atrás, durante o Cretáceo Superior. Foi um intervalo de grande diversidade de dinossauros e outros vertebrados, além de importantes transformações nos ambientes marinhos e terrestres.', 'Os continentes continuavam se afastando, com a expansão do Atlântico e a separação progressiva das massas continentais de Gondwana. A América do Norte ainda possuía uma extensa via marítima interior.', 'O clima era predominantemente quente, com diferenças regionais de precipitação. Muitas regiões apresentavam condições úmidas favoráveis ao desenvolvimento de florestas e planícies vegetadas.', 'Os mares apresentavam níveis relativamente elevados e abrigavam amonites, moluscos, peixes, tubarões e répteis marinhos. Depósitos de sedimentos marinhos desse intervalo são encontrados em diferentes continentes.', 'As plantas com flores estavam cada vez mais diversificadas. Coníferas, samambaias e cicadáceas continuavam presentes, compondo diferentes tipos de florestas e formações vegetais.', 'Os ambientes incluíam florestas subtropicais, planícies fluviais, pântanos, regiões costeiras e mares rasos. Grandes sistemas de rios favoreciam a presença de diversos herbívoros e predadores.', 'Dinossauros ceratopsianos, hadrossauros, anquilossauros e terópodes apresentavam grande diversidade. Aves primitivas, mamíferos, pterossauros, tartarugas, crocodilianos e répteis marinhos também habitavam os ecossistemas.', 'Durante o Campaniano, grandes dinossauros herbívoros e carnívoros habitavam diferentes regiões do planeta. Fósseis desse intervalo ajudam a compreender a diversidade dos ecossistemas que existiam pouco antes da extinção do final do Cretáceo.'),
(9, 'santoniano', 'Santoniano', 'idade', 85.7000, 83.6000, 2, 'O Santoniano ocorreu entre aproximadamente 85,7 e 83,6 milhões de anos atrás e corresponde a uma idade do Cretáceo Superior. Seus registros geológicos preservam evidências de ecossistemas terrestres e marinhos diversificados.', 'Gondwana continuava se fragmentando e o Oceano Atlântico se expandia. A América do Norte permanecia parcialmente dividida por uma via marítima interior, enquanto outras massas continentais seguiam em movimento.', 'O clima global era relativamente quente, com diferenças regionais de temperatura e precipitação. Regiões costeiras e tropicais apresentavam condições favoráveis à existência de ambientes úmidos e vegetados.', 'Os mares rasos ocupavam grandes áreas e apresentavam diversidade de amonites, moluscos, peixes, tubarões e répteis marinhos. Os depósitos marinhos são importantes para a identificação desse intervalo geológico.', 'Angiospermas continuavam se diversificando e ocupando diferentes ambientes. Coníferas, samambaias e cicadáceas também permaneciam comuns em diversas regiões.', 'Os ambientes terrestres incluíam florestas, planícies aluviais, pântanos e áreas costeiras. Os mares rasos e ambientes continentais de água doce também sustentavam comunidades diversificadas.', 'A fauna incluía diferentes dinossauros, crocodilianos, tartarugas, aves primitivas, mamíferos e pterossauros. Nos oceanos, amonites, peixes e grandes répteis marinhos estavam entre os principais representantes.', 'O Santoniano faz parte do Cretáceo Superior e foi um intervalo de diversificação de diferentes grupos de animais marinhos e terrestres. Seus registros fósseis ajudam a reconstruir os ambientes e a distribuição dos organismos naquele período.'),
(10, 'coniaciano', 'Coniaciano', 'idade', 89.8000, 85.7000, 2, 'O Coniaciano ocorreu entre aproximadamente 89,8 e 85,7 milhões de anos atrás, durante o Cretáceo Superior. Foi marcado pela continuidade da diversificação dos organismos marinhos e terrestres em um planeta com temperaturas relativamente elevadas.', 'A separação dos continentes continuava, acompanhada pela expansão do Oceano Atlântico. Grandes áreas da América do Norte permaneciam cobertas por mares interiores, enquanto Gondwana avançava em sua fragmentação.', 'As condições climáticas eram geralmente quentes, com variações regionais de umidade. Algumas regiões apresentavam florestas e planícies úmidas, enquanto outras possuíam condições mais secas.', 'Os mares apresentavam grande diversidade de organismos, incluindo amonites, peixes, tubarões e répteis marinhos. A expansão de ambientes marinhos rasos favorecia o desenvolvimento de diferentes comunidades aquáticas.', 'As angiospermas continuavam sua expansão e diversificação, convivendo com coníferas, samambaias e cicadáceas. A composição da vegetação variava conforme as condições climáticas e geográficas.', 'Existiam ambientes fluviais, planícies costeiras, florestas, pântanos e mares rasos. Os ambientes aquáticos continentais também eram importantes para diferentes grupos de vertebrados.', 'Os ecossistemas terrestres eram ocupados por dinossauros, crocodilianos, tartarugas, mamíferos e aves primitivas. Nos ambientes marinhos, amonites, peixes e répteis marinhos apresentavam grande diversidade.', 'O Coniaciano foi um intervalo em que os mares ainda ocupavam grandes áreas continentais em diversas regiões. Fósseis marinhos, como os de amonites e répteis marinhos, são importantes para reconhecer e estudar rochas dessa idade.'),
(11, 'turoniano', 'Turoniano', 'idade', 93.9000, 89.8000, 2, 'O Turoniano ocorreu entre aproximadamente 93,9 e 89,8 milhões de anos atrás. Foi uma idade do Cretáceo Superior caracterizada por temperaturas elevadas, altos níveis dos oceanos e grande diversidade de organismos marinhos.', 'Os continentes continuavam sua separação gradual. O Oceano Atlântico se expandia e extensos mares interiores cobriam regiões da América do Norte, enquanto a África e a América do Sul continuavam se afastando.', 'O Turoniano foi um intervalo de clima globalmente quente, associado ao período de efeito estufa do Cretáceo. Não existiam grandes calotas polares permanentes e as temperaturas oceânicas eram relativamente elevadas.', 'Os níveis dos mares eram muito elevados, formando extensos ambientes marinhos rasos. Amonites, peixes, tubarões, moluscos e grandes répteis marinhos, como mosassauros e plesiossauros, habitavam os oceanos.', 'As plantas com flores estavam em processo de diversificação, enquanto coníferas, samambaias e cicadáceas continuavam compondo a vegetação terrestre.', 'As paisagens incluíam florestas, planícies costeiras, rios, lagos e extensos mares rasos. Grandes áreas continentais apresentavam condições úmidas e ambientes favoráveis à diversidade de vertebrados.', 'Os ecossistemas terrestres abrigavam dinossauros, pterossauros, aves primitivas e pequenos mamíferos. Os ambientes marinhos apresentavam grande diversidade de peixes, amonites e répteis marinhos.', 'O Turoniano ocorreu em um momento de temperaturas globalmente elevadas e de expansão dos mares sobre áreas continentais. Os oceanos abrigavam uma grande diversidade de organismos, incluindo amonites, peixes e grandes répteis marinhos.'),
(12, 'cenomaniano', 'Cenomaniano', 'idade', 100.5000, 93.9000, 2, 'O Cenomaniano ocorreu entre aproximadamente 100,5 e 93,9 milhões de anos atrás e representa a primeira idade do Cretáceo Superior. Foi marcado por temperaturas elevadas, níveis marinhos muito altos e mudanças importantes nos ecossistemas terrestres e marinhos.', 'Gondwana continuava sua fragmentação e o Oceano Atlântico se expandia. A América do Norte e outras regiões continentais apresentavam grandes áreas inundadas por mares interiores.', 'O clima era predominantemente quente, com temperaturas elevadas nos oceanos e ausência de grandes calotas polares permanentes. O intervalo também apresenta evidências de importantes alterações na circulação oceânica e no ciclo do carbono.', 'O nível dos mares atingiu valores muito elevados, criando extensos mares rasos. Amonites, moluscos, peixes, tubarões e répteis marinhos eram abundantes. O Cenomaniano também inclui o início do evento anóxico Cenomaniano-Turoniano, marcado pela redução de oxigênio em importantes regiões oceânicas.', 'As angiospermas apresentavam diversificação crescente, enquanto coníferas, samambaias e cicadáceas continuavam comuns em diferentes regiões.', 'Os ambientes incluíam florestas, planícies fluviais, regiões costeiras, lagos e mares interiores. As áreas inundadas pelos oceanos criavam extensos ecossistemas marinhos rasos.', 'Dinossauros, pterossauros, aves primitivas e mamíferos ocupavam os ambientes terrestres. Nos oceanos, amonites, peixes ósseos, tubarões, tartarugas e répteis marinhos apresentavam grande diversidade.', 'O Cenomaniano foi marcado por níveis elevados do mar e pela existência de extensos ambientes marinhos rasos. Também corresponde ao início do Cretáceo Superior e apresenta importantes registros fósseis de organismos marinhos e terrestres.'),
(13, 'albiano', 'Albiano', 'idade', 113.2000, 100.5000, 6, 'O Albiano ocorreu entre aproximadamente 113,2 e 100,5 milhões de anos atrás, durante o Cretáceo Inferior. Foi um intervalo de expansão dos ambientes marinhos, mudanças na configuração continental e diversificação das plantas com flores.', 'Os continentes continuavam se separando, especialmente as massas continentais que formavam Gondwana. O Oceano Atlântico Sul começava a se expandir, enquanto a Índia ainda permanecia separada de outras massas continentais.', 'O clima era geralmente quente, com variações regionais de temperatura e precipitação. Algumas regiões apresentavam ambientes áridos e semiáridos, enquanto outras possuíam florestas e planícies úmidas.', 'Os mares estavam em expansão e apresentavam grande diversidade de amonites, moluscos, peixes e répteis marinhos. Os sedimentos oceânicos registram importantes mudanças na circulação e na oxigenação das águas.', 'As primeiras angiospermas já estavam presentes e se diversificavam progressivamente. Coníferas, samambaias e cicadáceas continuavam predominantes em muitas comunidades vegetais.', 'Existiam florestas, planícies fluviais, lagos, pântanos, regiões áridas e ambientes costeiros. Os mares rasos ocupavam áreas continentais em diferentes regiões.', 'Dinossauros saurópodes, terópodes e ornitópodes estavam presentes em diferentes continentes. Pterossauros, aves primitivas, mamíferos, anfíbios e organismos marinhos também compunham os ecossistemas.', 'O Albiano foi um intervalo de grande importância para a diversificação das plantas com flores. Nos ambientes marinhos, amonites e outros organismos deixaram fósseis que atualmente auxiliam na identificação e datação de rochas.'),
(14, 'aptiano', 'Aptiano', 'idade', 121.4000, 113.2000, 6, 'O Aptiano ocorreu entre aproximadamente 121,4 e 113,2 milhões de anos atrás e corresponde a uma idade do Cretáceo Inferior. Foi marcado por importantes mudanças ambientais, episódios de atividade vulcânica e alterações na oxigenação dos oceanos.', 'A fragmentação de Gondwana avançava e a separação entre a África e a América do Sul se tornava mais evidente. O Oceano Atlântico Sul continuava seu desenvolvimento, enquanto outras massas continentais também se afastavam.', 'O clima era geralmente quente, com episódios de alterações na temperatura e na umidade. Durante o Aptiano ocorreram importantes perturbações ambientais relacionadas a eventos de vulcanismo e mudanças no ciclo do carbono.', 'Os oceanos passaram por episódios de redução da oxigenação em determinadas regiões, incluindo o evento anóxico do Aptiano. Os mares abrigavam amonites, moluscos, peixes e diferentes répteis marinhos.', 'Coníferas, samambaias e cicadáceas compunham grande parte da vegetação. As angiospermas começaram a apresentar maior diversificação, ocupando progressivamente novos ambientes.', 'Os ambientes terrestres incluíam florestas, planícies aluviais, lagos e regiões semiáridas. Sistemas fluviais e áreas costeiras também eram importantes para a fauna da época.', 'Diversos dinossauros, incluindo grandes saurópodes e terópodes, habitavam os continentes. Pterossauros, aves primitivas, mamíferos, anfíbios e uma grande variedade de organismos marinhos também estavam presentes.', 'Durante o Aptiano, ocorreram importantes mudanças nos ecossistemas terrestres e marinhos. Alguns grupos de dinossauros apresentaram grande diversificação, enquanto os registros geológicos indicam episódios de alterações na oxigenação dos oceanos.'),
(15, 'barremiano', 'Barremiano', 'idade', 125.7700, 121.4000, 6, 'O Barremiano ocorreu entre aproximadamente 125,77 e 121,4 milhões de anos atrás, durante o Cretáceo Inferior. Seus depósitos fossilíferos preservam importantes registros de dinossauros, répteis voadores, plantas e organismos marinhos.', 'Gondwana continuava se fragmentando, com a separação progressiva das massas continentais que futuramente formariam a América do Sul, África, Antártida e Austrália. A Laurásia também apresentava mudanças geográficas.', 'O clima era relativamente quente, embora apresentasse diferenças regionais de precipitação. Ambientes úmidos e florestais coexistiam com regiões mais secas e sazonais.', 'Os oceanos apresentavam amonites, moluscos, peixes, tubarões e répteis marinhos. A expansão gradual das bacias oceânicas modificava a distribuição dos mares e dos ambientes costeiros.', 'A vegetação era composta principalmente por coníferas, samambaias, cicadáceas e outras plantas sem flores. As primeiras angiospermas já estavam presentes em algumas regiões.', 'Os ambientes incluíam florestas, planícies aluviais, rios, lagos, pântanos e regiões costeiras. Alguns depósitos sedimentares preservam evidências de ecossistemas continentais bastante diversificados.', 'Dinossauros terópodes, saurópodes e ornitópodes estavam presentes. Pterossauros, aves primitivas, pequenos mamíferos, crocodilianos e organismos marinhos também compunham a biodiversidade.', 'O Barremiano preserva registros de diversos dinossauros e outros animais do Cretáceo Inferior. Fósseis encontrados em diferentes continentes ajudam a compreender como os organismos se distribuíam em um planeta que passava por mudanças geográficas.'),
(16, 'hauteriviano', 'Hauteriviano', 'idade', 132.6000, 125.7700, 6, 'O Hauteriviano ocorreu entre aproximadamente 132,6 e 125,77 milhões de anos atrás, durante o Cretáceo Inferior. Foi um intervalo de transformações geográficas e diversificação de diferentes grupos de animais terrestres e marinhos.', 'Os continentes continuavam se afastando lentamente. A fragmentação de Gondwana avançava e as bacias oceânicas se expandiam, modificando a distribuição das regiões costeiras.', 'O clima apresentava condições geralmente quentes, com variações regionais de umidade. Regiões florestais e planícies úmidas coexistiam com áreas de clima mais seco.', 'Os mares apresentavam amonites, moluscos, peixes, tubarões e répteis marinhos. A movimentação das placas tectônicas favorecia a expansão de diferentes bacias oceânicas.', 'Coníferas, samambaias e cicadáceas eram comuns, formando florestas e outras comunidades vegetais. As angiospermas ainda estavam em suas primeiras etapas de evolução e diversificação.', 'Os ambientes terrestres incluíam florestas, planícies fluviais, lagos e áreas pantanosas. Regiões costeiras e ambientes marinhos rasos também estavam presentes.', 'A fauna incluía diversos dinossauros, pterossauros, crocodilianos, tartarugas, pequenos mamíferos e aves primitivas. Os ambientes marinhos eram habitados por peixes, amonites e répteis aquáticos.', 'O Hauteriviano integra o Cretáceo Inferior e apresenta registros fósseis de dinossauros, répteis voadores e organismos marinhos. Os depósitos sedimentares dessa idade são importantes para o estudo dos antigos ambientes terrestres e oceânicos.'),
(17, 'valanginiano', 'Valanginiano', 'idade', 137.0500, 132.6000, 6, 'O Valanginiano ocorreu entre aproximadamente 137,05 e 132,6 milhões de anos atrás, durante o Cretáceo Inferior. Foi marcado pela continuidade da fragmentação continental e pela presença de diversos grupos de dinossauros e organismos marinhos.', 'Gondwana continuava em processo de fragmentação e o Oceano Atlântico começava a se desenvolver entre as massas continentais. Laurásia também apresentava mudanças relacionadas à movimentação tectônica.', 'O clima era relativamente quente, com variações regionais de temperatura e precipitação. Algumas regiões apresentavam florestas úmidas, enquanto outras possuíam condições sazonais mais secas.', 'Os oceanos abrigavam amonites, moluscos, peixes e répteis marinhos. Os mares rasos e as regiões costeiras ofereciam diferentes habitats para organismos aquáticos.', 'Coníferas, samambaias e cicadáceas dominavam a vegetação em muitas regiões. Plantas com sementes eram importantes componentes das comunidades vegetais.', 'Os ambientes incluíam florestas, planícies, sistemas fluviais, lagos e regiões costeiras. Também existiam ambientes marinhos rasos e bacias sedimentares em expansão.', 'Dinossauros saurópodes, terópodes e ornitópodes habitavam diferentes continentes. Pterossauros, crocodilianos, tartarugas, mamíferos primitivos e organismos marinhos também estavam presentes.', 'Durante o Valanginiano, os continentes continuavam se afastando gradualmente devido à movimentação das placas tectônicas. Os fósseis desse intervalo registram diferentes grupos de organismos que habitavam os ambientes terrestres e marinhos.'),
(18, 'berriasiano', 'Berriasiano', 'idade', 143.1000, 137.0500, 6, 'O Berriasiano representa a primeira idade do Cretáceo, iniciada há aproximadamente 143,1 milhões de anos e encerrada há 137,05 milhões de anos. Começou após o final do Jurássico e preserva registros importantes da continuidade e diversificação dos ecossistemas mesozoicos.', 'Os continentes ainda estavam relativamente próximos em comparação com suas posições atuais, mas a fragmentação da Pangeia avançava. Laurásia e Gondwana já representavam grandes conjuntos continentais separados por bacias oceânicas em desenvolvimento.', 'O clima era geralmente quente, com variações regionais de temperatura e umidade. Ambientes úmidos e florestais coexistiam com regiões mais secas e sazonais.', 'Os mares abrigavam amonites, moluscos, peixes, tubarões e répteis marinhos. A movimentação tectônica continuava modificando as bacias oceânicas e as regiões costeiras.', 'Coníferas, cicadáceas, samambaias e outras plantas sem flores eram predominantes. As plantas com flores ainda não apresentavam a grande diversificação que ocorreria posteriormente no Cretáceo.', 'Existiam florestas, planícies fluviais, lagos, pântanos, regiões costeiras e ambientes marinhos rasos. A diversidade de paisagens favorecia diferentes comunidades de vertebrados.', 'Dinossauros, pterossauros, crocodilianos, tartarugas, aves primitivas e pequenos mamíferos estavam presentes. Muitos grupos de animais já estabelecidos no Jurássico continuaram a se diversificar.', 'O Berriasiano representa a primeira idade do Cretáceo. Ele começou após o final do Jurássico, período em que muitos grupos de dinossauros já estavam estabelecidos. Seus registros ajudam a compreender as primeiras etapas da história cretácea.'),
(19, 'cisuraliano', 'Cisuraliano', 'epoca', 298.9000, 274.4000, 3, 'O Cisuraliano foi a primeira época do Permiano, iniciada há aproximadamente 298,9 milhões de anos e encerrada há 273,01 milhões de anos. Durante esse intervalo, os ambientes terrestres passaram por transformações após as glaciações do Carbonífero e os vertebrados terrestres apresentaram grande diversificação.', 'As grandes massas continentais estavam reunidas no supercontinente Pangeia. O oceano Panthalassa ocupava a maior parte da superfície oceânica, enquanto o mar de Tétis começava a se desenvolver em regiões tropicais.', 'O clima apresentava grande diversidade regional. O interior de Pangeia começava a desenvolver condições mais secas, enquanto algumas regiões ainda preservavam ambientes úmidos e evidências de condições glaciais herdadas do período anterior.', 'O Panthalassa e os mares associados abrigavam braquiópodes, moluscos, equinodermos, peixes e outros organismos marinhos. Os recifes e comunidades marinhas apresentavam mudanças em relação ao Carbonífero.', 'Florestas de coníferas e outras gimnospermas começaram a se expandir em regiões mais secas. Samambaias e plantas com sementes também eram importantes, especialmente em ambientes úmidos.', 'Os ambientes incluíam florestas, planícies, pântanos, rios, lagos e regiões progressivamente mais áridas. A expansão de ambientes continentais secos influenciou a distribuição dos organismos.', 'Os vertebrados terrestres apresentavam sinapsídeos, incluindo pelicossauros, além de répteis e anfíbios. Insetos e diferentes invertebrados também eram abundantes, enquanto os oceanos abrigavam peixes e diversos organismos marinhos.', 'O Cisuraliano corresponde à primeira época do Permiano. Durante esse intervalo, os ambientes terrestres apresentavam extensas áreas continentais e uma fauna diversificada, incluindo sinapsídeos e outros grupos de vertebrados que antecederam os mamíferos.'),
(20, 'guadalupiano', 'Guadalupiano', 'epoca', 274.4000, 259.8570, 3, 'O Guadalupiano foi a segunda época do Permiano, ocorrida entre aproximadamente 273,01 e 259,51 milhões de anos atrás. Foi marcada por mudanças climáticas e ambientais, além da diversificação dos terápsidos, grupo importante na evolução dos mamíferos.', 'Pangeia permanecia como o principal supercontinente da Terra, cercado pelo oceano Panthalassa. O mar de Tétis ocupava regiões tropicais e as áreas interiores continentais apresentavam condições geográficas bastante distintas das regiões costeiras.', 'O clima era predominantemente quente e seco no interior de Pangeia, com grandes diferenças regionais de precipitação. A aridez de algumas regiões aumentava e mudanças ambientais afetavam diferentes ecossistemas.', 'Os oceanos abrigavam amonites, braquiópodes, moluscos, peixes e outros invertebrados. O final dessa época foi marcado por importantes crises ambientais, incluindo a extinção do Capitaniano.', 'As coníferas e outras gimnospermas estavam bem estabelecidas em regiões mais secas. Samambaias e outras plantas continuavam presentes em ambientes úmidos e próximos a rios e lagos.', 'Os ambientes incluíam extensos desertos, planícies áridas, florestas sazonais, rios e lagos. Regiões costeiras apresentavam condições mais úmidas e diferentes comunidades vegetais.', 'Os terápsidos começaram a apresentar maior diversificação, enquanto outros sinapsídeos e répteis continuavam presentes. Os ambientes aquáticos abrigavam peixes e diversos invertebrados marinhos.', 'O Guadalupiano foi marcado por mudanças ambientais e climáticas que afetaram diferentes ecossistemas. Nesse intervalo, os terápsidos começaram a ganhar importância entre os vertebrados terrestres, enquanto diversos grupos de animais marinhos continuavam presentes nos oceanos.'),
(21, 'lopingiano', 'Lopingiano', 'epoca', 259.8570, 251.9020, 3, 'O Lopingiano foi a última época do Permiano, iniciada há aproximadamente 259,51 milhões de anos e encerrada há 251,9 milhões de anos. Foi marcado pela diversificação de diferentes grupos de terápsidos e terminou com a maior extinção em massa conhecida da história da Terra.', 'Pangeia permanecia reunida como um único supercontinente, cercado pelo oceano Panthalassa. O mar de Tétis ocupava regiões entre as porções setentrionais e meridionais do supercontinente.', 'O clima era predominantemente quente e muitas regiões interiores de Pangeia apresentavam condições áridas. No final da época, mudanças ambientais intensas, associadas à atividade vulcânica, provocaram alterações climáticas globais.', 'Os oceanos abrigavam amonites, braquiópodes, moluscos, peixes e diversos invertebrados. No final do Permiano, alterações na temperatura, acidificação e redução da oxigenação das águas contribuíram para uma extinção marinha em grande escala.', 'Coníferas, samambaias com sementes e outras gimnospermas compunham a vegetação. As comunidades vegetais sofreram grandes alterações durante a crise ambiental do final do Permiano.', 'Os ambientes incluíam desertos, planícies áridas, florestas sazonais, rios, lagos e regiões costeiras. A crise ambiental do final da época transformou profundamente os ecossistemas terrestres e aquáticos.', 'Os terápsidos, incluindo formas herbívoras e predadoras, eram importantes componentes da fauna terrestre. Anfíbios, répteis, insetos e diversos organismos marinhos também estavam presentes. A extinção do final do Permiano eliminou grande parte das espécies existentes.', 'O Lopingiano foi a última época do Permiano e terminou com a maior extinção em massa da história da Terra. Mudanças climáticas intensas, atividade vulcânica em grande escala e alterações nos oceanos estão entre os fatores associados a esse evento.'),
(22, 'holoceno', 'Holoceno', 'epoca', 0.0117, 0.0000, 5, 'O Holoceno é a época geológica atual, iniciada há aproximadamente 11.700 anos, após o final da última grande glaciação. É caracterizado pela relativa estabilidade climática, expansão das sociedades humanas, desenvolvimento da agricultura e profundas transformações nos ecossistemas.', 'Os continentes apresentam configurações muito próximas das atuais. O nível dos oceanos aumentou após o derretimento das grandes geleiras do Pleistoceno, modificando linhas costeiras e formando diferentes paisagens.', 'O clima tornou-se relativamente mais quente e estável em comparação com os períodos glaciais anteriores. Entretanto, apresenta variações naturais e, mais recentemente, um aquecimento global intensificado pelas atividades humanas.', 'O nível dos oceanos aumentou significativamente após o final da última glaciação e posteriormente apresentou relativa estabilidade. Os ecossistemas marinhos e costeiros desenvolveram-se em condições próximas das atuais.', 'As angiospermas, gramíneas, coníferas e outras plantas atuais ocupam diferentes regiões do planeta. Florestas, savanas, pradarias e outras formações vegetais apresentam distribuição influenciada pelo clima e pelas atividades humanas.', 'Os ambientes incluem florestas tropicais e temperadas, savanas, pradarias, desertos, tundras, rios, lagos, oceanos e regiões costeiras. A agricultura, a urbanização e o desmatamento transformaram significativamente muitas paisagens.', 'A biodiversidade apresenta os principais grupos de organismos atuais, incluindo mamíferos, aves, répteis, anfíbios, peixes, insetos e plantas. A atividade humana provocou extinções, alterações na distribuição das espécies e mudanças nos ecossistemas.', 'O Holoceno é a época em que surgiram e se desenvolveram as primeiras grandes civilizações humanas. A agricultura, a domesticação de animais e a formação das cidades transformaram profundamente a relação entre os seres humanos e o ambiente.'),
(23, 'paleozoico', 'Paleozoica', 'era', 538.8000, 251.9020, 29, 'A Era Paleozoica foi um importante intervalo da história da Terra, marcado pela grande diversificação da vida marinha, pela colonização dos ambientes terrestres e pelo surgimento de ecossistemas continentais complexos. Durante essa era, surgiram os primeiros peixes com mandíbulas, anfíbios e répteis. Seu encerramento foi marcado pela maior extinção em massa conhecida da história do planeta.', 'Durante a Paleozoica, as massas continentais passaram por grandes transformações. No início da era, existiam diversos continentes separados, incluindo Laurentia, Báltica, Sibéria e Gondwana. Ao longo de milhões de anos, essas massas se aproximaram e colidiram, contribuindo para a formação do supercontinente Pangeia no final da era.', 'O clima apresentou grandes variações ao longo da era. No início, predominavam condições relativamente quentes, seguidas por importantes episódios de glaciação, especialmente durante o Ordoviciano e o Carbonífero. No final do Paleozoico, extensas regiões do interior de Pangeia apresentavam condições áridas e temperaturas sazonais extremas.', 'Os oceanos paleozoicos abrigavam uma enorme diversidade de organismos. Durante o início da era, os mares eram dominados por trilobitas, braquiópodes, moluscos e outros invertebrados. Posteriormente, houve grande diversificação dos peixes e de outros vertebrados marinhos. Entre os principais ambientes oceânicos estavam os mares rasos, recifes e bacias marinhas profundas.', 'A vegetação passou por transformações fundamentais. Inicialmente, os ambientes terrestres praticamente não possuíam plantas complexas. Posteriormente, surgiram as primeiras plantas terrestres, seguidas por plantas vasculares, licófitas, samambaias e gimnospermas. Durante o Carbonífero, extensas florestas pantanosas se desenvolveram e contribuíram para a formação de grandes depósitos de carvão.', 'Os ambientes incluíam mares rasos, recifes, regiões costeiras, rios, lagos, pântanos e extensas florestas. Ao longo da era, os ecossistemas terrestres se tornaram progressivamente mais complexos, passando a abrigar artrópodes, anfíbios, répteis e diferentes grupos de plantas.', 'A biodiversidade apresentou uma expansão extraordinária. Os oceanos testemunharam a diversificação de trilobitas, moluscos, braquiópodes, equinodermos e peixes. Nos ambientes terrestres surgiram artrópodes, anfíbios e os primeiros répteis. Também ocorreu a diversificação dos insetos e o desenvolvimento de grandes ecossistemas florestais.', 'A Era Paleozoica é frequentemente associada à explosão de diversidade do Cambriano, à colonização dos continentes pelos primeiros organismos terrestres, às grandes florestas do Carbonífero e à formação de Pangeia. Seu final foi marcado pela extinção Permiano-Triássico, que eliminou uma enorme parcela da biodiversidade marinha e terrestre.'),
(24, 'mesozoico', 'Mesozoica', 'era', 251.9000, 66.0000, 29, 'A Era Mesozoica foi marcada pelo domínio dos dinossauros em muitos ecossistemas terrestres, pela diversificação dos répteis e pelo surgimento dos primeiros mamíferos e aves. Durante esse intervalo, o supercontinente Pangeia começou a se fragmentar, modificando progressivamente a configuração dos continentes e dos oceanos. A era terminou há aproximadamente 66 milhões de anos, durante a extinção em massa do final do Cretáceo.', 'No início da Mesozoica, praticamente todas as grandes massas continentais estavam reunidas no supercontinente Pangeia. Durante o Triássico e o Jurássico, esse supercontinente começou a se fragmentar, originando gradualmente a Laurásia e Gondwana. Ao longo do Cretáceo, a separação entre a América do Sul e a África avançou, o Oceano Atlântico se expandiu e os continentes se aproximaram progressivamente de suas configurações atuais.', 'O clima foi predominantemente quente durante grande parte da era, com ausência de grandes calotas polares permanentes. No início, muitas regiões interiores de Pangeia apresentavam condições áridas e sazonais. Posteriormente, as mudanças na configuração continental e na circulação oceânica contribuíram para diferentes padrões climáticos. No Cretáceo, ocorreram períodos de temperaturas elevadas e níveis marinhos bastante altos.', 'Os oceanos passaram por importantes transformações devido à fragmentação de Pangeia e à abertura de novas bacias oceânicas. Mares rasos ocuparam extensas regiões continentais, especialmente durante o Cretáceo. Os ecossistemas marinhos abrigavam amonites, peixes, tubarões, moluscos e grandes répteis marinhos, como ictiossauros, plesiossauros e mosassauros.', 'As gimnospermas, incluindo coníferas, cicadáceas e ginkgófitas, foram importantes componentes da vegetação durante grande parte da era. Samambaias também eram comuns em diferentes ambientes. Durante o Cretáceo surgiram e se diversificaram as angiospermas, ou plantas com flores, que passaram a ocupar uma variedade crescente de ecossistemas terrestres.', 'Os ambientes incluíam florestas, planícies aluviais, desertos, regiões costeiras, pântanos, lagos, rios e mares rasos. A fragmentação continental contribuiu para a formação de novas barreiras geográficas e diferentes condições ambientais. Os ecossistemas terrestres abrigavam dinossauros, pterossauros, pequenos mamíferos e aves primitivas.', 'A biodiversidade mesozoica foi marcada pela grande diversificação dos dinossauros, que ocuparam diferentes nichos ecológicos nos continentes. Pterossauros dominaram diversos ambientes aéreos, enquanto répteis marinhos ocupavam os oceanos. Também surgiram os primeiros mamíferos e aves. No final da era, as angiospermas já apresentavam grande diversificação.', 'A Mesozoica é popularmente conhecida como Era dos Dinossauros, embora diversos outros grupos tenham desempenhado papéis importantes nos ecossistemas. Durante esse intervalo surgiram as primeiras aves, os primeiros mamíferos e as plantas com flores. Seu encerramento foi marcado pelo impacto do asteroide associado à cratera de Chicxulub, no atual México, e por uma extinção em massa que eliminou os dinossauros não avianos.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(25, 'cenozoico', 'Cenozoica', 'era', 66.0000, 0.0000, 29, 'A Era Cenozoica começou há aproximadamente 66 milhões de anos, após a extinção em massa do final do Cretáceo. É caracterizada pela diversificação dos mamíferos e das aves, pelo desenvolvimento de ecossistemas modernos e por importantes transformações climáticas e geográficas. Durante essa era, os continentes adquiriram posições próximas das atuais e ocorreu a evolução e expansão da humanidade.', 'Os continentes continuaram se movimentando e assumiram gradualmente suas posições atuais. A Índia colidiu com a Ásia, contribuindo para a formação da Cordilheira do Himalaia, enquanto a África se aproximou da Eurásia. A América do Norte e a América do Sul estabeleceram uma conexão terrestre através do istmo do Panamá, modificando a distribuição de animais entre os continentes.', 'O início da era apresentou condições relativamente quentes, mas o clima passou por uma tendência de resfriamento ao longo de milhões de anos. Durante o Eoceno ocorreram episódios de aquecimento intenso, enquanto o Oligoceno foi marcado pela formação de grandes geleiras na Antártida. Posteriormente, as temperaturas continuaram oscilando, culminando nos ciclos glaciais do Quaternário e no clima relativamente mais quente do Holoceno.', 'Os oceanos passaram por transformações relacionadas à movimentação dos continentes e às mudanças na circulação marinha. A formação e o aprofundamento de conexões oceânicas influenciaram as correntes marítimas e a distribuição dos organismos. Os ambientes marinhos testemunharam a diversificação de baleias, golfinhos, focas, tubarões, peixes e diferentes grupos de invertebrados.', 'A vegetação passou a apresentar muitos dos principais grupos encontrados atualmente. Florestas tropicais e temperadas se desenvolveram em diferentes regiões, enquanto gramíneas e outras plantas herbáceas se expandiram, especialmente durante o Mioceno. As angiospermas se tornaram predominantes em muitos ecossistemas terrestres, contribuindo para a formação de savanas e pradarias.', 'Os ambientes incluíam florestas tropicais, florestas temperadas, savanas, pradarias, desertos, tundras, regiões polares, rios, lagos e oceanos. As mudanças climáticas e geográficas influenciaram a distribuição desses ambientes. No Quaternário, os ciclos glaciais transformaram extensas regiões continentais, enquanto no Holoceno as atividades humanas modificaram profundamente diversas paisagens.', 'Após a extinção do final do Cretáceo, mamíferos e aves passaram por uma grande diversificação e ocuparam diferentes nichos ecológicos. Surgiram e se diversificaram grupos como primatas, cetáceos, cavalos, elefantes e felinos. Também ocorreu a expansão das gramíneas e de diversos ecossistemas modernos. Durante o Quaternário, diferentes espécies humanas se desenvolveram e se espalharam pelo planeta.', 'A Cenozoica é frequentemente chamada de Era dos Mamíferos devido à grande diversificação desse grupo após a extinção dos dinossauros não avianos. Durante essa era surgiram os grandes mamíferos conhecidos como megafauna, incluindo mamutes e preguiças-gigantes. Também ocorreu a evolução do gênero Homo e, posteriormente, a expansão de Homo sapiens pelo planeta.'),
(26, 'hadeano', 'Hadeano', 'eon', 4567.0000, 4031.0000, NULL, 'O Hadeano representa a primeira divisão do tempo geológico, iniciado há aproximadamente 4,567 bilhões de anos, durante a formação da Terra. Foi marcado por intensos impactos de corpos celestes, atividade vulcânica e pelo resfriamento gradual da superfície terrestre.', 'A Terra ainda estava em processo de formação e diferenciação interna. Não existiam continentes estáveis como os atuais, embora materiais da crosta primitiva tenham começado a se formar.', 'As condições climáticas eram extremamente hostis, com temperaturas elevadas, intenso vulcanismo e frequentes impactos de meteoritos. Com o resfriamento gradual do planeta, as condições começaram a permitir a formação de água líquida na superfície.', 'A formação dos primeiros oceanos ocorreu provavelmente durante o Hadeano, à medida que a superfície terrestre esfriava e o vapor de água presente na atmosfera se condensava.', 'Não existia vegetação. A vida ainda não possui registros fósseis confirmados para esse intervalo.', 'O ambiente terrestre era dominado por intensa atividade vulcânica, impactos de asteroides, formação da crosta e processos de diferenciação entre núcleo, manto e superfície.', 'Não existem evidências fósseis confirmadas de organismos desse período. A origem da vida permanece uma questão científica em investigação, possivelmente relacionada a ambientes aquáticos que se desenvolveram posteriormente.', 'O nome Hadeano deriva de Hades, figura da mitologia grega associada ao mundo subterrâneo. A denominação faz referência às condições extremas e aparentemente infernais da Terra primitiva.'),
(27, 'arqueano', 'Arqueano', 'eon', 4031.0000, 2500.0000, NULL, 'O Arqueano foi um importante intervalo da história terrestre, marcado pela formação e estabilização das primeiras porções da crosta continental, pelo desenvolvimento dos oceanos e pelo surgimento das primeiras formas de vida conhecidas.', 'Os primeiros núcleos continentais começaram a se desenvolver e crescer, formando terrenos geológicos primitivos que posteriormente contribuíram para a formação dos continentes atuais. A configuração das massas continentais era muito diferente da atual.', 'O clima provavelmente era mais quente do que o atual, influenciado por uma atmosfera com composição diferente da moderna. Apesar da menor luminosidade solar, o efeito estufa ajudava a manter temperaturas compatíveis com a presença de água líquida.', 'Os oceanos já estavam estabelecidos e ocupavam grandes áreas da superfície terrestre. Suas águas apresentavam composição química diferente da atual e continham ambientes favoráveis a reações químicas importantes para a evolução da vida.', 'Não existiam plantas terrestres. A produção primária era realizada por microrganismos, incluindo organismos fotossintetizantes que contribuíram para as transformações químicas dos oceanos e da atmosfera.', 'Os ambientes incluíam oceanos, regiões vulcânicas, fontes hidrotermais e áreas costeiras primitivas. A atividade geológica era intensa, com formação de crosta e frequentes processos tectônicos.', 'A vida era predominantemente microscópica, representada por organismos procariontes. Existem evidências de comunidades microbianas e de estruturas sedimentares associadas à atividade de microrganismos, como os estromatólitos.', 'O Arqueano abriga algumas das evidências mais antigas de vida na Terra. Os estromatólitos, estruturas formadas pela atividade de comunidades microbianas, são importantes registros desse passado.'),
(28, 'proterozoico', 'Proterozoico', 'eon', 2500.0000, 538.8000, NULL, 'O Proterozoico foi um longo intervalo da história terrestre caracterizado por profundas transformações ambientais e biológicas. Durante esse éon, ocorreu o aumento significativo da concentração de oxigênio na atmosfera, a evolução dos organismos eucariontes e o surgimento de formas de vida multicelulares.', 'As massas continentais cresceram e passaram por diversos processos de união e fragmentação. Grandes supercontinentes, como Columbia, Rodínia e Pannotia, estiveram associados a diferentes momentos desse éon.', 'O clima passou por grandes mudanças. Um dos acontecimentos mais marcantes foi a ocorrência de intensas glaciações, incluindo episódios associados à hipótese da Terra Bola de Neve, quando grandes áreas do planeta podem ter ficado cobertas por gelo.', 'Os oceanos passaram por transformações químicas importantes, especialmente relacionadas ao aumento da disponibilidade de oxigênio. Durante grande parte do Proterozoico, extensas regiões oceânicas ainda apresentavam condições pobres em oxigênio.', 'Não existiam florestas ou plantas terrestres. A vida fotossintetizante era representada principalmente por cianobactérias e algas, que tiveram papel importante na produção de oxigênio e na transformação dos ecossistemas aquáticos.', 'Os ambientes incluíam oceanos, mares rasos, plataformas continentais e regiões glaciais. No final do éon, surgiram ambientes marinhos que abrigaram organismos multicelulares de maior complexidade.', 'O Proterozoico testemunhou a diversificação dos organismos eucariontes, o aparecimento de algas e o desenvolvimento de formas multicelulares. No final do éon, surgiram organismos da biota ediacarana, incluindo algumas das primeiras formas macroscópicas de vida complexa.', 'O aumento do oxigênio atmosférico durante o Proterozoico está associado ao Grande Evento de Oxigenação. Esse processo transformou profundamente a química dos oceanos e da atmosfera, criando condições importantes para a evolução de formas de vida mais complexas.'),
(29, 'fanerozoico', 'Fanerozoico', 'eon', 538.8000, 0.0000, NULL, 'O Fanerozoico é o éon atual e representa o intervalo da história terrestre caracterizado pela grande diversificação da vida e pelo abundante registro fóssil. Abrange as eras Paleozoica, Mesozoica e Cenozoica, durante as quais ocorreram importantes transformações geológicas, climáticas e biológicas.', 'A configuração continental passou por grandes transformações, incluindo a formação e fragmentação de supercontinentes como Pangeia. Os continentes adquiriram gradualmente suas posições atuais por meio do movimento das placas tectônicas.', 'O clima apresentou grandes variações ao longo do éon, incluindo períodos de aquecimento global, glaciações extensas e mudanças no nível dos oceanos. Essas transformações influenciaram diretamente a distribuição e a evolução dos seres vivos.', 'Os oceanos passaram por mudanças na composição química, temperatura e nível do mar. Também foram palco de importantes processos evolutivos, incluindo a diversificação de invertebrados marinhos, peixes, répteis marinhos e mamíferos marinhos.', 'A vegetação passou por grandes transformações, desde a diversificação de algas e plantas primitivas até o surgimento de florestas, gimnospermas e angiospermas. As plantas terrestres passaram a ocupar ambientes cada vez mais variados.', 'Os ambientes terrestres e aquáticos se diversificaram amplamente, incluindo florestas, desertos, pradarias, pântanos, recifes, mares rasos e oceanos profundos. A distribuição desses ambientes variou conforme as mudanças climáticas e tectônicas.', 'O Fanerozoico foi marcado pela diversificação de praticamente todos os grandes grupos de organismos conhecidos atualmente. Surgiram e se diversificaram peixes, anfíbios, répteis, dinossauros, aves, mamíferos e plantas com flores. Também ocorreram cinco grandes eventos de extinção em massa.', 'O Fanerozoico é dividido em três eras: Paleozoica, Mesozoica e Cenozoica. Entre seus acontecimentos mais conhecidos estão a expansão da vida nos continentes, o domínio dos dinossauros e a evolução dos seres humanos.'),
(35, 'cambriano', 'Cambriano', 'periodo', 538.8000, 486.8500, 23, 'O Cambriano foi o primeiro período da Era Paleozoica e marcou uma das transformações mais importantes da história da vida na Terra. Durante esse intervalo, ocorreu uma grande diversificação dos organismos marinhos, conhecida como Explosão Cambriana. Nesse processo, diversos grupos de animais desenvolveram estruturas corporais mais complexas, incluindo esqueletos mineralizados, conchas e diferentes formas de locomoção. A vida ainda estava concentrada principalmente nos oceanos, mas a diversidade dos ecossistemas marinhos aumentou significativamente.', 'A configuração dos continentes era bastante diferente da atual. Grandes massas continentais estavam distribuídas em diferentes regiões do planeta. Gondwana era o maior continente, enquanto Laurentia, Báltica e Sibéria encontravam-se separadas. Também existiam extensas áreas continentais próximas ao equador, muitas delas cercadas por mares rasos. A movimentação das placas tectônicas e a fragmentação de antigas massas continentais influenciavam a distribuição dos ambientes marinhos.', 'O clima do Cambriano era predominantemente quente, sem evidências de grandes calotas polares permanentes como as atuais. As temperaturas globais eram relativamente elevadas, e o nível dos mares encontrava-se alto, favorecendo a formação de extensos mares rasos sobre as plataformas continentais. Essas condições contribuíram para a expansão dos ambientes marinhos e para a diversificação da vida aquática.', 'Os oceanos ocupavam grandes áreas do planeta e apresentavam extensas regiões de águas rasas, especialmente sobre as plataformas continentais. Esses ambientes ofereciam condições favoráveis ao desenvolvimento de comunidades marinhas diversificadas. A composição química da água do mar também teve importância na evolução de organismos capazes de produzir estruturas mineralizadas, como conchas e esqueletos.', 'Não existiam florestas, gramíneas ou plantas terrestres durante o Cambriano. A vegetação terrestre ainda não havia surgido, e a produção primária era realizada principalmente por organismos microscópicos, como cianobactérias e algas. Esses organismos habitavam os oceanos e também formavam comunidades sobre os fundos marinhos, contribuindo para a produção de matéria orgânica nos ecossistemas.', 'Os principais ambientes eram marinhos, incluindo fundos oceânicos, recifes primitivos, plataformas continentais e mares rasos. Os fundos marinhos abrigavam organismos que viviam sobre o sedimento ou enterrados nele, enquanto outros nadavam livremente na coluna de água. Algumas regiões apresentavam condições específicas de preservação de fósseis, permitindo que partes delicadas de organismos fossem conservadas ao longo de milhões de anos.', 'A biodiversidade marinha aumentou expressivamente durante o Cambriano. Trilobitas tornaram-se alguns dos animais mais característicos do período, convivendo com braquiópodes, moluscos, equinodermos primitivos, esponjas e diversos organismos de corpo mole. Também surgiram animais predadores, como os radiodontes, grupo que inclui o conhecido Anomalocaris. Entre os organismos mais importantes para a história evolutiva dos vertebrados estavam formas primitivas de cordados, como Pikaia e Haikouichthys. Apesar da grande diversificação, os ecossistemas terrestres ainda não possuíam animais ou plantas estabelecidos.', 'O Cambriano é conhecido pela chamada Explosão Cambriana, um período de intensa diversificação evolutiva que ocorreu ao longo de milhões de anos, e não de maneira instantânea. Muitos grupos animais desenvolveram características corporais que se tornariam fundamentais para a evolução da vida. Fósseis encontrados em locais como o Folhelho Burgess, no Canadá, e o depósito de Chengjiang, na China, preservam organismos com detalhes excepcionais, incluindo estruturas delicadas que normalmente não seriam fossilizadas.'),
(36, 'ordoviciano', 'Ordoviciano', 'periodo', 486.8500, 443.1000, 23, 'O Ordoviciano foi o segundo período da Era Paleozoica e ficou marcado por uma expressiva diversificação da vida marinha, conhecida como Grande Evento de Biodiversificação Ordoviciana. Durante esse intervalo, os oceanos passaram a abrigar uma variedade ainda maior de organismos, incluindo trilobitas, braquiópodes, moluscos, equinodermos e graptólitos. Também ocorreu uma importante diversificação dos primeiros vertebrados. Embora a vida ainda fosse predominantemente aquática, surgiram algumas das primeiras evidências de plantas terrestres simples. O período terminou com uma grande extinção em massa, associada principalmente ao resfriamento global e às mudanças no nível dos oceanos.', 'A configuração continental continuava bastante diferente da atual. Gondwana era a maior massa continental e começou a se deslocar em direção às regiões polares do sul, enquanto Laurentia, Báltica e Sibéria permaneciam como continentes separados. Entre essas massas continentais existiam extensos oceanos, como o oceano Iapetus. O movimento das placas tectônicas provocava mudanças na distribuição dos continentes e contribuía para a formação de diferentes ambientes marinhos.', 'Durante boa parte do Ordoviciano, o clima foi relativamente quente, com temperaturas globais elevadas e ausência de grandes calotas polares permanentes. O nível do mar permaneceu alto, favorecendo a expansão de mares rasos sobre os continentes. Entretanto, no final do período, ocorreu um intenso resfriamento climático, associado à formação de extensas geleiras sobre Gondwana. Essa glaciação provocou uma queda significativa do nível do mar e contribuiu para a extinção em massa do final do Ordoviciano.', 'Os oceanos ocupavam grandes extensões do planeta e apresentavam extensos mares rasos, que proporcionavam ambientes favoráveis à diversificação da vida marinha. Diferentes regiões oceânicas abrigavam comunidades de organismos que viviam sobre o fundo, enterrados nos sedimentos ou nadando na coluna de água. A circulação oceânica e as condições químicas da água influenciavam a distribuição dos organismos. No final do período, as alterações climáticas e a redução do nível dos oceanos modificaram significativamente esses ecossistemas.', 'A vegetação terrestre ainda era bastante simples e não existiam florestas, árvores ou plantas com sistemas vasculares desenvolvidos. Evidências fósseis, como esporos, indicam a presença de organismos semelhantes a plantas terrestres primitivas, possivelmente relacionados a ancestrais das plantas atuais. Nos ambientes aquáticos, algas continuavam desempenhando um papel importante na produção de matéria orgânica e na manutenção das cadeias alimentares.', 'Os ambientes marinhos eram predominantes e incluíam plataformas continentais, mares rasos, recifes e fundos oceânicos. Os fundos marinhos apresentavam grande diversidade de organismos, muitos deles vivendo sobre os sedimentos ou escavando o substrato. Recifes formados por organismos como esponjas, corais primitivos e outros invertebrados também estavam presentes. As regiões costeiras e os ambientes de águas rasas ofereciam condições favoráveis à alimentação, reprodução e diversificação de diversas espécies.', 'A biodiversidade marinha atingiu níveis muito elevados durante o Ordoviciano. Trilobitas, braquiópodes, moluscos, briozoários, equinodermos, esponjas e graptólitos eram comuns em diferentes ambientes. Os cefalópodes, incluindo formas com conchas alongadas, tornaram-se importantes predadores marinhos. Também houve diversificação dos primeiros vertebrados, principalmente peixes sem mandíbulas, como os ostracodermos. Alguns organismos desenvolveram relações ecológicas mais complexas, contribuindo para a formação de comunidades marinhas diversificadas.', 'O Ordoviciano é conhecido pelo Grande Evento de Biodiversificação Ordoviciana, durante o qual a diversidade de organismos marinhos aumentou consideravelmente. Esse processo transformou os ecossistemas oceânicos e estabeleceu muitas das comunidades características dos mares paleozoicos. Outro acontecimento marcante foi a extinção em massa do final do período, uma das cinco maiores extinções da história da Terra. Ela ocorreu em duas fases principais e esteve relacionada ao resfriamento global, à glaciação de Gondwana e às alterações no nível do mar.'),
(37, 'siluriano', 'Siluriano', 'periodo', 443.1000, 419.6200, 23, 'O Siluriano foi o terceiro período da Era Paleozoica e sucedeu a grande extinção em massa que encerrou o Ordoviciano. Durante esse intervalo, os ecossistemas marinhos se recuperaram e passaram por uma nova diversificação. Os recifes se desenvolveram amplamente, enquanto peixes sem mandíbulas e os primeiros peixes com mandíbulas se diversificaram. Nas regiões terrestres, plantas vasculares primitivas começaram a se estabelecer, acompanhadas por alguns dos primeiros artrópodes terrestres conhecidos. Essas transformações representaram etapas importantes na ocupação do ambiente continental pelos seres vivos.', 'Os continentes continuavam distribuídos de maneira muito diferente da atual. Gondwana permanecia como uma grande massa continental, localizada principalmente no hemisfério sul. Laurentia e Báltica se aproximavam progressivamente, enquanto outras massas continentais, como a Sibéria, mantinham posições relativamente isoladas. A aproximação entre Laurentia e Báltica culminaria na formação do continente Laurússia, também conhecido como Euramérica. Entre essas massas continentais existiam oceanos e mares que influenciavam a circulação das águas e a distribuição dos organismos.', 'Após o resfriamento intenso do final do Ordoviciano, o clima tornou-se progressivamente mais quente durante o Siluriano. As geleiras que haviam se desenvolvido sobre Gondwana recuaram, provocando a elevação do nível do mar. Em grande parte do período, as condições climáticas foram relativamente estáveis e favoreceram a expansão dos ambientes marinhos rasos. Entretanto, ocorreram variações climáticas e oscilações no nível dos oceanos ao longo de diferentes etapas do período.', 'Os oceanos desempenhavam um papel fundamental na manutenção da biodiversidade. A elevação do nível do mar favoreceu a expansão de mares rasos sobre as plataformas continentais, criando ambientes propícios ao desenvolvimento de recifes e comunidades marinhas. Os mares abrigavam organismos que viviam no fundo, nadavam livremente ou ocupavam diferentes níveis da coluna de água. Os recifes formados por corais e estromatoporoides tornaram-se ecossistemas importantes, oferecendo abrigo e recursos alimentares para numerosas espécies.', 'O Siluriano marcou uma etapa importante na evolução das plantas terrestres. Plantas vasculares primitivas, como Cooksonia, apresentavam estruturas simples, com pequenos caules ramificados e sistemas condutores rudimentares. Essas plantas ainda não possuíam folhas e raízes verdadeiras como as das espécies atuais. Desenvolviam-se principalmente em ambientes úmidos, próximos a áreas costeiras e margens de corpos de água. Sua expansão contribuiu para o início da transformação dos ecossistemas continentais.', 'Os ambientes marinhos continuavam predominantes e incluíam mares rasos, plataformas continentais e extensos recifes. Os fundos marinhos abrigavam trilobitas, braquiópodes, moluscos, crinoides e diversos outros invertebrados. Nas águas abertas, peixes primitivos ocupavam diferentes posições nas cadeias alimentares. Em terra firme, ambientes úmidos e costeiros começaram a receber plantas vasculares e artrópodes, representando os primeiros passos para o estabelecimento de ecossistemas terrestres mais complexos.', 'A vida marinha apresentou grande diversidade, incluindo trilobitas, braquiópodes, moluscos, briozoários, crinoides, corais e graptólitos. Os peixes sem mandíbulas continuaram importantes, enquanto os primeiros peixes com mandíbulas, conhecidos como gnatostomados, começaram a se diversificar. Entre eles estavam formas primitivas de placodermos e acantódios. Nos ambientes terrestres, plantas vasculares como Cooksonia e artrópodes primitivos, incluindo formas semelhantes a miriápodes, representam alguns dos primeiros registros de vida em terra firme.', 'O Siluriano recebeu esse nome em homenagem aos Silures, um antigo povo que habitava regiões do atual País de Gales, onde foram estudadas importantes sequências de rochas desse período. Uma de suas principais características foi a recuperação dos ecossistemas após a extinção do final do Ordoviciano. Também foi um intervalo fundamental para a evolução das plantas vasculares e dos vertebrados com mandíbulas, dois grupos que teriam grande importância nos ecossistemas terrestres e aquáticos posteriores.'),
(38, 'devoniano', 'Devoniano', 'periodo', 419.6200, 358.8600, 23, 'O Devoniano foi o quarto período da Era Paleozoica e ficou conhecido como a Era dos Peixes devido à grande diversificação dos vertebrados aquáticos. Durante esse intervalo, diferentes grupos de peixes desenvolveram características importantes, incluindo mandíbulas, nadadeiras mais complexas e esqueletos internos diversificados. Também ocorreram transformações significativas nos ambientes terrestres: as plantas vasculares se expandiram, surgiram as primeiras florestas e os primeiros tetrápodes começaram a ocupar ambientes próximos à água. O período terminou com uma série de eventos de extinção que afetaram principalmente os ecossistemas marinhos.', 'A configuração continental era dominada por Gondwana, uma extensa massa continental localizada principalmente no hemisfério sul, e por Laurússia, formada pela aproximação de Laurentia e Báltica. Entre essas massas continentais encontrava-se o oceano Rheico. A região próxima ao equador apresentava condições favoráveis ao desenvolvimento de ambientes tropicais, enquanto outras regiões possuíam características climáticas distintas. A movimentação das placas tectônicas também contribuiu para a formação de cadeias montanhosas e para mudanças na distribuição dos mares.', 'O clima do Devoniano foi predominantemente quente durante boa parte do período, especialmente nas regiões equatoriais. As temperaturas favoreceram a expansão de florestas primitivas e a formação de ambientes úmidos em diversas áreas continentais. Entretanto, as condições climáticas não eram uniformes em todo o planeta. No final do Devoniano, ocorreram mudanças ambientais importantes, incluindo episódios de resfriamento, alterações na circulação oceânica e redução dos níveis de oxigênio em determinadas regiões marinhas.', 'Os oceanos abrigavam uma grande diversidade de peixes e invertebrados. Recifes extensos, construídos principalmente por corais e estromatoporoides, formavam ambientes complexos que ofereciam abrigo e alimento para numerosas espécies. Peixes placodermos, como Dunkleosteus, ocupavam posições importantes entre os grandes predadores marinhos. Também eram comuns trilobitas, braquiópodes, moluscos e equinodermos. Em algumas regiões, alterações na circulação das águas contribuíram para a formação de ambientes com baixos níveis de oxigênio, especialmente durante os eventos de extinção do final do período.', 'A vegetação terrestre passou por uma grande transformação durante o Devoniano. Plantas vasculares se diversificaram e desenvolveram estruturas cada vez mais complexas, incluindo raízes, folhas e tecidos condutores mais eficientes. Surgiram as primeiras florestas, formadas por plantas como Archaeopteris, que apresentava características semelhantes às de árvores modernas. Também se desenvolveram grupos de licófitas, esfenófitas primitivas e samambaias ancestrais. A expansão da vegetação modificou os solos, aumentou a retenção de sedimentos e influenciou os ciclos de carbono e oxigênio.', 'Os ambientes marinhos incluíam recifes, plataformas continentais, mares rasos e regiões oceânicas mais profundas. Nos continentes, rios, lagos, planícies aluviais e áreas alagadas tornaram-se ambientes importantes para a evolução da vida terrestre. As primeiras florestas modificaram as paisagens e criaram novos habitats para artrópodes e outros organismos. Em regiões próximas à água, peixes de nadadeiras lobadas passaram a explorar ambientes rasos, contribuindo para o surgimento dos primeiros vertebrados capazes de se deslocar também sobre superfícies terrestres.', 'A biodiversidade do Devoniano foi marcada pela diversidade dos peixes, incluindo placodermos, peixes cartilaginosos, peixes ósseos e formas de nadadeiras lobadas. Entre os animais conhecidos estavam Dunkleosteus, um grande predador marinho, e Bothriolepis, um placodermo que habitava ambientes aquáticos. Os tetrápodes mais antigos conhecidos, como Acanthostega e Ichthyostega, surgiram no final do período e apresentavam adaptações para a locomoção em ambientes rasos, embora ainda dependessem fortemente da água. Nos ambientes terrestres, artrópodes e uma grande variedade de plantas também se diversificaram.', 'O Devoniano é conhecido como a Era dos Peixes devido à extraordinária diversificação dos vertebrados aquáticos. Também foi o período em que surgiram algumas das primeiras florestas da história da Terra, transformando profundamente os ambientes continentais. Outro acontecimento importante foi o surgimento dos primeiros tetrápodes, que representam uma etapa fundamental na evolução dos vertebrados terrestres. O final do período foi marcado pela extinção do Devoniano Superior, uma série de eventos que afetou especialmente os recifes e diversas comunidades marinhas, provocando a redução ou desaparecimento de muitos grupos de organismos.'),
(39, 'carbonifero', 'Carbonífero', 'periodo', 358.8600, 298.9000, 23, 'O Carbonífero foi o quinto período da Era Paleozoica e ficou conhecido pela expansão de extensas florestas pantanosas, que deram origem a importantes depósitos de carvão mineral. Durante esse intervalo, a vegetação terrestre se desenvolveu intensamente, formando ecossistemas densos e diversificados. Os artrópodes atingiram tamanhos impressionantes, enquanto os anfíbios se diversificaram e os primeiros amniotas surgiram, representando uma importante etapa na evolução dos vertebrados terrestres. O período também foi marcado por mudanças climáticas e pela formação de grandes massas continentais.', 'Durante o Carbonífero, os continentes começaram a se aproximar progressivamente, em um processo que culminaria na formação do supercontinente Pangeia. Gondwana ocupava grande parte do hemisfério sul, enquanto Laurússia estava localizada em regiões mais próximas ao equador. A colisão entre essas massas continentais contribuiu para a formação de cadeias montanhosas, especialmente durante a Orogenia Varisca e outros eventos tectônicos. A configuração continental influenciou diretamente o clima, a distribuição dos ambientes terrestres e a formação de extensas regiões pantanosas.', 'O clima variou consideravelmente ao longo do período. Durante boa parte do Carbonífero, regiões equatoriais apresentavam condições quentes e úmidas, favorecendo o desenvolvimento de extensas florestas pantanosas. Enquanto isso, Gondwana passou por episódios de glaciação, com a formação de grandes geleiras em regiões austrais. Essas condições contribuíram para oscilações no nível dos oceanos e alterações na distribuição dos ambientes costeiros. No final do período, o clima tornou-se progressivamente mais seco em diversas regiões, provocando transformações importantes nos ecossistemas vegetais.', 'Os oceanos continuavam abrigando uma grande diversidade de organismos, incluindo braquiópodes, moluscos, crinoides, corais e diferentes grupos de peixes. Mares rasos cobriam extensas áreas continentais, especialmente em regiões tropicais. Também existiam ambientes marinhos associados a recifes e plataformas continentais. As oscilações climáticas e as variações no nível do mar modificavam a extensão desses ambientes, influenciando a distribuição das espécies marinhas.', 'A vegetação atingiu grande desenvolvimento durante o Carbonífero. Extensas florestas pantanosas eram dominadas por licófitas arborescentes, como Lepidodendron e Sigillaria, além de cavalinhas gigantes, como Calamites, e diferentes grupos de samambaias. Também existiam plantas com sementes primitivas, como as pteridospermas. A grande quantidade de matéria vegetal acumulada em ambientes alagados, onde a decomposição era limitada, contribuiu para a formação de depósitos de turfa que, ao longo de milhões de anos, originaram importantes camadas de carvão mineral.', 'Os ambientes terrestres incluíam extensos pântanos, florestas úmidas, planícies aluviais e regiões próximas a rios e lagos. Esses locais ofereciam condições favoráveis à reprodução e ao desenvolvimento de anfíbios e artrópodes. Em regiões mais secas, começaram a se estabelecer ambientes com vegetação diferente das florestas pantanosas. Os ambientes marinhos também apresentavam grande diversidade, com recifes, mares rasos e fundos oceânicos habitados por numerosos invertebrados e peixes.', 'A biodiversidade terrestre era marcada pela presença de artrópodes de grande porte, incluindo insetos alados e miriápodes gigantes. Entre os animais conhecidos estavam Arthropleura, um enorme artrópode semelhante a um milípede, e Meganeura, um inseto alado com grande envergadura. Anfíbios diversificados ocupavam ambientes úmidos, enquanto os primeiros amniotas, representados por animais como Hylonomus, desenvolveram características reprodutivas que permitiram maior independência em relação à água. Nos oceanos, peixes cartilaginosos, peixes ósseos e diversos invertebrados continuavam a se diversificar.', 'O nome Carbonífero está relacionado à grande quantidade de carvão mineral formada a partir da matéria vegetal acumulada durante o período. As florestas pantanosas desse intervalo tiveram enorme importância na história geológica e na formação de depósitos explorados atualmente como combustíveis fósseis. Outra característica marcante foi o surgimento dos primeiros amniotas, vertebrados cujos ovos possuíam membranas especializadas para o desenvolvimento embrionário em ambientes terrestres. Essa inovação evolutiva abriu caminho para a diversificação posterior dos répteis, aves e mamíferos.'),
(40, 'terreneuviano', 'Terreneuviano', 'epoca', 538.8000, 521.0000, 35, 'O Terreneuviano foi a primeira época do período Cambriano e marcou o início de uma importante transformação na história da vida animal. Durante esse intervalo, os organismos marinhos começaram a apresentar maior diversidade e complexidade, com o desenvolvimento de estruturas corporais mineralizadas e diferentes formas de organização. O registro fóssil desse período inclui alguns dos primeiros animais com esqueletos e conchas, além de organismos de corpo mole. A vida permanecia restrita principalmente aos ambientes aquáticos, onde ocorreram mudanças fundamentais na organização dos ecossistemas.', 'Os continentes apresentavam uma configuração bastante diferente da atual. Gondwana era uma extensa massa continental localizada principalmente no hemisfério sul, enquanto Laurentia, Báltica e Sibéria permaneciam separadas. A maior parte das regiões continentais estava cercada por mares rasos, e as áreas próximas ao equador apresentavam extensas plataformas marinhas. A distribuição dessas massas continentais influenciava a circulação oceânica e a disponibilidade de habitats para os organismos.', 'O clima era predominantemente quente, com temperaturas globais relativamente elevadas e ausência de grandes calotas polares permanentes. O nível dos oceanos encontrava-se elevado, favorecendo a expansão de mares rasos sobre as plataformas continentais. Essas condições contribuíram para o desenvolvimento de ambientes marinhos diversos e para a expansão dos organismos que habitavam os fundos oceânicos.', 'Os oceanos eram os principais ambientes de desenvolvimento da vida. Mares rasos e plataformas continentais ofereciam condições favoráveis à alimentação, reprodução e preservação de organismos. Os fundos marinhos abrigavam comunidades de animais que viviam sobre os sedimentos ou parcialmente enterrados neles. A composição química da água também favorecia o desenvolvimento de estruturas mineralizadas em determinados grupos de organismos.', 'Não existiam plantas terrestres ou florestas. A produção de matéria orgânica dependia principalmente de organismos microscópicos, como cianobactérias e algas, que habitavam os oceanos. Tapetes microbianos eram encontrados em diferentes ambientes marinhos e desempenhavam um papel importante nos ecossistemas da época.', 'Os ambientes eram predominantemente marinhos, incluindo plataformas continentais, fundos oceânicos e mares rasos. Alguns locais apresentavam condições favoráveis à preservação de organismos, permitindo o registro de estruturas corporais delicadas. Os sedimentos marinhos acumulavam restos de animais e outros materiais que posteriormente poderiam se transformar em fósseis.', 'A biodiversidade começou a apresentar uma diversificação importante, com o aparecimento e a expansão de diferentes animais marinhos. Entre os organismos conhecidos estavam trilobitas primitivos, braquiópodes, esponjas, moluscos e outros invertebrados. Também existiam organismos de corpo mole, que nem sempre deixavam registros fósseis bem preservados. Alguns animais desenvolveram conchas e outras estruturas rígidas que aumentaram suas possibilidades de preservação no registro geológico.', 'O Terreneuviano representa uma etapa inicial da chamada Explosão Cambriana. Durante essa época, surgiram alguns dos primeiros registros abundantes de animais com partes mineralizadas. O Fortuniano, seu primeiro estágio, marca o início do Cambriano e é caracterizado por importantes evidências fósseis utilizadas para identificar o começo desse período geológico.'),
(41, 'serie-2', 'Série 2', 'epoca', 521.0000, 506.5000, 35, 'A Série 2 foi a segunda época do período Cambriano e testemunhou a continuidade da diversificação dos organismos marinhos. Durante esse intervalo, os animais desenvolveram diferentes estratégias de alimentação, locomoção e proteção. Os trilobitas tornaram-se mais diversificados e numerosos, enquanto outros grupos de invertebrados ocuparam diferentes ambientes dos fundos oceânicos. Também surgiram formas mais complexas de predadores, contribuindo para o desenvolvimento de relações ecológicas mais elaboradas.', 'Gondwana continuava sendo a maior massa continental, ocupando principalmente regiões do hemisfério sul. Laurentia, Báltica e Sibéria permaneciam separadas, enquanto extensas áreas oceânicas e mares rasos ocupavam as regiões entre os continentes. As plataformas continentais ofereciam grandes áreas de ambientes marinhos, favorecendo a diversificação dos organismos aquáticos.', 'O clima permaneceu predominantemente quente, com temperaturas elevadas em grande parte do planeta. O nível do mar continuava relativamente alto, permitindo a expansão de ambientes marinhos sobre áreas continentais. As condições ambientais variavam regionalmente, mas os mares rasos tropicais eram especialmente importantes para a manutenção da biodiversidade.', 'Os oceanos apresentavam ecossistemas cada vez mais complexos. Trilobitas, braquiópodes e diversos outros invertebrados ocupavam os fundos marinhos, enquanto organismos predadores exploravam diferentes níveis da coluna de água. A disponibilidade de ambientes rasos e ricos em nutrientes favorecia o desenvolvimento de comunidades diversificadas.', 'A vegetação terrestre ainda não havia se estabelecido. Algas e organismos fotossintetizantes microscópicos continuavam sendo os principais produtores primários dos ecossistemas. Tapetes microbianos permaneciam presentes em diferentes regiões dos fundos marinhos, contribuindo para a produção de matéria orgânica.', 'Os ambientes predominantes eram mares rasos, plataformas continentais e fundos oceânicos. Os sedimentos marinhos abrigavam comunidades diversificadas de organismos, incluindo animais que viviam sobre o substrato e outros que escavavam o fundo. Também existiam ambientes com condições favoráveis à preservação de fósseis, permitindo conhecer melhor a anatomia de organismos cambrianos.', 'A biodiversidade marinha continuou aumentando. Trilobitas tornaram-se especialmente importantes, acompanhados por braquiópodes, moluscos, esponjas e outros invertebrados. Predadores como os radiodontes desenvolveram características especializadas para capturar suas presas. Entre os organismos conhecidos desse intervalo estão diferentes formas de artrópodes e animais de corpo mole que contribuíram para a complexidade das cadeias alimentares marinhas.', 'A Série 2 é representada por estágios conhecidos como Estágio 3 e Estágio 4, cujos limites ainda apresentam aspectos em processo de definição internacional. Foi um intervalo importante para a diversificação dos trilobitas e para o desenvolvimento de interações entre predadores e presas. Essas mudanças contribuíram para a formação de ecossistemas marinhos cada vez mais complexos.'),
(42, 'miaolingiano', 'Miaolingiano', 'epoca', 506.5000, 497.0000, 35, 'O Miaolingiano foi a terceira época do período Cambriano e corresponde à antiga denominação informal Série 3. Durante esse intervalo, ocorreu uma diversificação significativa dos organismos marinhos, com o desenvolvimento de comunidades mais complexas e diferentes adaptações ecológicas. Trilobitas, braquiópodes e outros invertebrados continuaram se diversificando, enquanto os predadores marinhos ocupavam posições importantes nas cadeias alimentares. O registro fóssil desse intervalo apresenta organismos com grande variedade de formas corporais e estratégias de sobrevivência.', 'Gondwana continuava sendo a maior massa continental, enquanto Laurentia, Báltica e Sibéria permaneciam separadas. Os continentes apresentavam posições que permitiam a existência de extensas plataformas continentais e mares rasos. A configuração geográfica favorecia a formação de diferentes ambientes oceânicos, nos quais os organismos podiam se diversificar.', 'O clima permaneceu relativamente quente durante o Miaolingiano, com extensos ambientes marinhos distribuídos por diferentes regiões continentais. O nível dos oceanos continuava elevado, embora ocorressem variações regionais e mudanças nas condições ambientais. Essas condições permitiam a manutenção de ecossistemas marinhos diversificados.', 'Os mares abrigavam comunidades cada vez mais complexas de organismos. Trilobitas, braquiópodes, moluscos e outros invertebrados ocupavam diferentes nichos ecológicos. Os predadores marinhos desempenhavam um papel importante na estruturação das comunidades, enquanto os organismos filtradores e detritívoros participavam da circulação de matéria nos ecossistemas.', 'Não existiam florestas ou vegetação terrestre estabelecida. A produção primária continuava dependente de algas, cianobactérias e outros microrganismos fotossintetizantes. Esses organismos formavam a base das cadeias alimentares marinhas e contribuíam para a manutenção dos ecossistemas.', 'Os ambientes incluíam mares rasos, plataformas continentais, recifes primitivos e fundos oceânicos. Algumas regiões apresentavam condições excepcionais de fossilização, preservando não apenas estruturas rígidas, mas também partes delicadas de organismos. Esses depósitos são fundamentais para compreender a diversidade e a anatomia dos animais cambrianos.', 'A biodiversidade era marcada pela presença de trilobitas, braquiópodes, moluscos, esponjas, equinodermos primitivos e diferentes grupos de artrópodes. Entre os animais conhecidos estavam organismos como Anomalocaris, um radiodonte predador, e diferentes espécies de trilobitas. Também existiam formas primitivas de cordados, importantes para compreender a evolução inicial dos vertebrados.', 'O Miaolingiano recebeu seu nome de uma região da China e é composto pelos estágios Wuliuano, Drumiano e Guzhangiano. O intervalo é especialmente importante para o estudo da evolução dos artrópodes e de outros animais marinhos. Fósseis de depósitos como Chengjiang e outros sítios cambrianos ajudam a reconstruir a diversidade e a organização dos ecossistemas desse período.'),
(43, 'furongiano', 'Furongiano', 'epoca', 497.0000, 486.8500, 35, 'O Furongiano foi a quarta e última época do período Cambriano. Durante esse intervalo, os ecossistemas marinhos continuaram apresentando grande diversidade, embora tenham ocorrido mudanças na composição das comunidades e na distribuição dos organismos. Trilobitas, braquiópodes, moluscos e diferentes grupos de invertebrados permaneceram importantes nos ambientes oceânicos. O período também foi marcado por mudanças evolutivas e ambientais que antecederam a transição para o Ordoviciano.', 'Gondwana permanecia como a maior massa continental, enquanto Laurentia, Báltica e Sibéria continuavam separadas. Os continentes eram cercados por extensas regiões oceânicas e mares rasos. A configuração continental influenciava a distribuição das plataformas marinhas e dos habitats disponíveis para os organismos. Ao longo do intervalo, as mudanças tectônicas e ambientais contribuíram para a reorganização de diferentes ecossistemas.', 'O clima continuou relativamente quente em boa parte do Furongiano, embora tenham ocorrido variações ambientais e climáticas. Os mares permaneciam extensos e o nível oceânico apresentava oscilações que influenciavam a distribuição dos ambientes costeiros e das plataformas continentais. Essas mudanças afetavam as condições de vida e a distribuição das comunidades marinhas.', 'Os oceanos continuavam sendo os principais ambientes de biodiversidade. Mares rasos e plataformas continentais abrigavam comunidades de trilobitas, braquiópodes, moluscos e outros invertebrados. As mudanças nas condições oceânicas e na disponibilidade de habitats influenciavam a composição das comunidades marinhas. Esses ecossistemas prepararam o cenário para a diversificação que ocorreria durante o Ordoviciano.', 'A vegetação terrestre ainda não estava estabelecida. Algas e microrganismos fotossintetizantes continuavam desempenhando o papel de produtores primários, sustentando as cadeias alimentares marinhas. A ocupação significativa dos ambientes terrestres por plantas ainda ocorreria muito depois, durante o Paleozoico.', 'Os ambientes eram principalmente marinhos, incluindo fundos oceânicos, plataformas continentais e mares rasos. Diferentes comunidades ocupavam os sedimentos e a coluna de água, explorando recursos alimentares variados. Alguns depósitos sedimentares preservaram fósseis com detalhes anatômicos importantes, permitindo reconstruir a evolução dos organismos no final do Cambriano.', 'A fauna incluía trilobitas, braquiópodes, moluscos, equinodermos e diversos outros invertebrados. Os trilobitas continuavam sendo um dos grupos mais característicos e diversificados. Também existiam diferentes artrópodes predadores e organismos filtradores. A composição das comunidades variava conforme as condições ambientais e a disponibilidade de habitats marinhos.', 'O Furongiano é a última época do Cambriano e inclui os estágios Paibiano, Jiangshaniano e Estágio 10. Seu nome deriva de uma palavra chinesa associada à flor de lótus. O intervalo representa a etapa final da evolução cambriana antes do início do Ordoviciano, quando ocorreu uma nova expansão da biodiversidade marinha.'),
(44, 'ordoviciano-inferior', 'Ordoviciano Inferior', 'epoca', 486.8500, 471.3000, 36, 'O Ordoviciano Inferior foi a primeira época do período Ordoviciano e marcou a recuperação e a expansão dos ecossistemas marinhos após a extinção ocorrida no final do Cambriano. Durante esse intervalo, a biodiversidade continuou aumentando, com a diversificação de trilobitas, braquiópodes, moluscos e outros invertebrados. Também ocorreu uma expansão dos organismos construtores de recifes e dos primeiros vertebrados marinhos. As comunidades oceânicas tornaram-se progressivamente mais complexas, estabelecendo as bases para a grande biodiversificação que caracterizaria o Ordoviciano.', 'Gondwana era a maior massa continental, ocupando principalmente regiões do hemisfério sul e avançando gradualmente em direção às áreas polares. Laurentia, Báltica e Sibéria permaneciam separadas, enquanto o oceano Iapetus ocupava uma extensa região entre Laurentia e Báltica. As plataformas continentais eram amplas e apresentavam condições favoráveis à formação de mares rasos, que abrigavam grande diversidade de organismos.', 'O clima era predominantemente quente durante boa parte da época, com temperaturas elevadas e nível do mar relativamente alto. Essas condições favoreciam a expansão de mares rasos sobre as plataformas continentais. As regiões próximas ao equador apresentavam ambientes tropicais, enquanto as áreas mais austrais possuíam condições climáticas distintas. As condições ambientais favoreceram a recuperação e a diversificação da vida marinha.', 'Os oceanos apresentavam extensas plataformas continentais e mares rasos, que ofereciam habitats favoráveis ao desenvolvimento de comunidades marinhas. Recifes formados por organismos como esponjas e corais primitivos estavam presentes em determinadas regiões. Os fundos oceânicos abrigavam trilobitas, braquiópodes, moluscos e outros invertebrados, enquanto diferentes grupos de organismos ocupavam a coluna de água.', 'A vegetação terrestre ainda era extremamente simples e não existiam florestas ou plantas vasculares estabelecidas. A produção primária dependia principalmente de algas e microrganismos fotossintetizantes, que sustentavam as cadeias alimentares marinhas. Evidências de esporos relacionados a plantas terrestres primitivas indicam que os primeiros processos de colonização do ambiente continental estavam começando a ocorrer durante o Ordoviciano.', 'Os ambientes predominantes eram marinhos, incluindo mares rasos, plataformas continentais, fundos oceânicos e regiões de recifes. Os sedimentos desses ambientes ofereciam condições para a alimentação e reprodução de diferentes grupos de invertebrados. As áreas costeiras também representavam regiões importantes de interação entre os ambientes marinhos e continentais.', 'A biodiversidade incluía trilobitas, braquiópodes, moluscos, briozoários, esponjas, equinodermos e graptólitos. Os cefalópodes começaram a desempenhar papéis importantes como predadores, enquanto diferentes grupos de peixes sem mandíbulas representavam os primeiros vertebrados marinhos. Também ocorreu a diversificação de organismos filtradores e de animais que habitavam os fundos oceânicos.', 'O Ordoviciano Inferior inclui os estágios Tremadociano e Floiano. Durante essa época, os ecossistemas marinhos passaram por uma importante recuperação e diversificação. Os graptólitos tornaram-se organismos relevantes para o estudo e a identificação das camadas geológicas, enquanto os primeiros registros de plantas terrestres primitivas indicam o início de uma transformação que se intensificaria nos períodos seguintes.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(45, 'ordoviciano-medio', 'Ordoviciano Médio', 'epoca', 471.3000, 458.2000, 36, 'O Ordoviciano Médio foi a segunda época do período Ordoviciano e correspondeu a uma fase de intensa diversificação da vida marinha. Durante esse intervalo, ocorreu uma etapa importante do Grande Evento de Biodiversificação Ordoviciana, caracterizada pelo aumento da variedade de espécies e pela ocupação de novos nichos ecológicos. Os recifes se desenvolveram, diferentes grupos de invertebrados se diversificaram e os vertebrados aquáticos continuaram sua evolução. Os ecossistemas marinhos tornaram-se mais estruturados e complexos.', 'Gondwana continuava sendo o maior continente, localizado principalmente no hemisfério sul. Laurentia, Báltica e Sibéria permaneciam como massas continentais separadas, embora movimentos tectônicos modificassem gradualmente suas posições. O oceano Iapetus continuava separando Laurentia e Báltica. A distribuição dos continentes favorecia a existência de extensas plataformas marinhas e ambientes costeiros em diferentes regiões do planeta.', 'O clima permaneceu relativamente quente, com temperaturas globais elevadas e nível do mar alto durante boa parte da época. Essas condições favoreceram a expansão de mares rasos e a formação de ambientes tropicais ricos em biodiversidade. Entretanto, ocorreram variações climáticas regionais e mudanças nas condições oceânicas que influenciaram a distribuição dos organismos.', 'Os oceanos apresentavam ecossistemas cada vez mais diversificados, com extensos recifes e comunidades de invertebrados. Braquiópodes, trilobitas, moluscos, briozoários e equinodermos ocupavam diferentes ambientes. Os graptólitos eram importantes componentes do plâncton, enquanto cefalópodes e outros predadores participavam das cadeias alimentares marinhas. A diversidade dos habitats oceânicos contribuiu para o aumento da variedade de espécies.', 'A vegetação terrestre ainda não apresentava florestas ou estruturas vegetais complexas. Algas e microrganismos fotossintetizantes continuavam sendo os principais produtores primários. Evidências de esporos indicam a presença de organismos relacionados às primeiras plantas terrestres, que provavelmente ocupavam ambientes úmidos e costeiros. Essas formas primitivas ainda eram muito diferentes das plantas vasculares que surgiriam posteriormente.', 'Os ambientes marinhos incluíam plataformas continentais, mares rasos, recifes e fundos oceânicos. Os recifes formavam estruturas importantes para a manutenção da biodiversidade, oferecendo abrigo e recursos alimentares. Diferentes organismos ocupavam os sedimentos, enquanto outros nadavam livremente ou viviam associados ao plâncton. As regiões costeiras também apresentavam condições favoráveis para os primeiros organismos relacionados à vegetação terrestre.', 'A biodiversidade marinha era bastante elevada, incluindo trilobitas, braquiópodes, moluscos, briozoários, crinoides, corais e graptólitos. Os cefalópodes, especialmente formas com conchas externas, eram importantes predadores. Os peixes sem mandíbulas continuaram se diversificando e representam alguns dos primeiros vertebrados conhecidos. A variedade de formas corporais e estratégias alimentares demonstra o aumento da complexidade ecológica dos mares.', 'O Ordoviciano Médio inclui os estágios Dapingiano e Darriwiliano. Esse intervalo foi fundamental para o Grande Evento de Biodiversificação Ordoviciana, durante o qual a diversidade marinha aumentou consideravelmente. A expansão dos recifes e a diversificação de diferentes grupos de invertebrados transformaram os ecossistemas oceânicos e prepararam o cenário para a grande variedade de organismos encontrada no Ordoviciano Superior.'),
(46, 'ordoviciano-superior', 'Ordoviciano Superior', 'epoca', 458.2000, 443.1000, 36, 'O Ordoviciano Superior foi a terceira e última época do período Ordoviciano. Durante a primeira parte desse intervalo, os ecossistemas marinhos apresentavam grande diversidade, resultado da intensa biodiversificação ocorrida anteriormente. Entretanto, o final da época foi marcado por uma das maiores extinções em massa da história da Terra. O resfriamento global e a formação de extensas geleiras sobre Gondwana provocaram uma queda significativa do nível dos oceanos, alterando os ambientes marinhos e causando o desaparecimento de numerosos grupos de organismos.', 'Gondwana continuava sendo a maior massa continental e deslocava-se em direção às regiões polares do sul, onde extensas geleiras começaram a se desenvolver. Laurentia, Báltica e Sibéria permaneciam separadas, enquanto os movimentos tectônicos continuavam modificando a distribuição dos continentes. As alterações na configuração das massas continentais e nas regiões costeiras influenciaram a circulação oceânica e a disponibilidade de habitats marinhos.', 'A época começou com condições relativamente quentes, mas passou por mudanças climáticas importantes. Durante o final do Ordoviciano, ocorreu um intenso resfriamento global, associado à glaciação de Gondwana. A formação de geleiras provocou uma redução significativa do nível do mar, diminuindo a extensão dos mares rasos. Posteriormente, ocorreram mudanças ambientais relacionadas ao recuo das geleiras e à reorganização dos ecossistemas marinhos.', 'Os oceanos abrigavam uma grande diversidade de organismos, incluindo trilobitas, braquiópodes, moluscos, graptólitos e diferentes grupos de equinodermos. Os mares rasos eram especialmente importantes para a biodiversidade, mas sofreram alterações significativas com a queda do nível do mar. No final da época, mudanças na circulação oceânica e episódios de redução do oxigênio em determinadas regiões contribuíram para o desaparecimento de diversas comunidades marinhas.', 'A vegetação terrestre permanecia simples, sem a presença de florestas ou plantas vasculares desenvolvidas. Algas e microrganismos fotossintetizantes continuavam sustentando a produção primária dos ecossistemas. Evidências de esporos indicam a existência de plantas terrestres primitivas, possivelmente relacionadas aos ancestrais das plantas atuais, mas sua distribuição ainda era limitada.', 'Os ambientes incluíam mares rasos, plataformas continentais, recifes e fundos oceânicos. Durante a maior parte da época, esses locais sustentavam comunidades marinhas diversificadas. Entretanto, a expansão das geleiras sobre Gondwana provocou uma queda do nível do mar, reduzindo a área disponível para os organismos que dependiam das plataformas continentais. Essas alterações ambientais modificaram profundamente os habitats e as cadeias alimentares.', 'A biodiversidade incluía trilobitas, braquiópodes, moluscos, briozoários, corais, graptólitos e diferentes grupos de equinodermos. Os cefalópodes continuavam importantes predadores marinhos, enquanto os peixes sem mandíbulas representavam os principais vertebrados aquáticos. No final da época, a extinção em massa do Ordoviciano afetou especialmente organismos marinhos, provocando a perda de uma grande parcela das espécies existentes.', 'O Ordoviciano Superior inclui os estágios Sandbiano, Katiano e Hirnantiano. Seu acontecimento mais marcante foi a extinção em massa do final do Ordoviciano, considerada uma das cinco maiores extinções da história da vida. O evento ocorreu em duas fases principais e esteve relacionado ao resfriamento global, à glaciação de Gondwana e às mudanças no nível do mar. Essa extinção encerrou o período e abriu caminho para a reorganização dos ecossistemas durante o Siluriano.'),
(47, 'llandovery', 'Llandovery', 'epoca', 443.1000, 432.9000, 37, 'Llandovery foi a primeira época do período Siluriano e marcou a recuperação dos ecossistemas após a grande extinção em massa do final do Ordoviciano. Durante esse intervalo, os ambientes marinhos passaram por uma reorganização ecológica, com a diversificação de trilobitas, braquiópodes, moluscos e graptólitos. Os recifes começaram a se desenvolver novamente e diferentes grupos de peixes primitivos continuaram sua evolução. Nos ambientes terrestres, surgiram algumas das primeiras evidências de plantas vasculares e artrópodes, representando o início de uma transformação importante na ocupação dos continentes.', 'Gondwana permanecia como a maior massa continental, ocupando principalmente o hemisfério sul e incluindo regiões próximas ao polo sul. Laurentia, Báltica e Sibéria continuavam como massas continentais separadas. A aproximação entre Laurentia e Báltica prosseguia, enquanto o oceano Iapetus ainda ocupava parte da região entre esses continentes. As plataformas continentais apresentavam extensas áreas inundadas por mares rasos, importantes para a recuperação da biodiversidade marinha.', 'No início da época, o clima ainda apresentava os efeitos do resfriamento e da glaciação que encerraram o Ordoviciano. Entretanto, o recuo das geleiras sobre Gondwana provocou uma elevação do nível do mar e uma recuperação gradual das temperaturas. Durante grande parte de Llandovery, as condições tornaram-se relativamente quentes, favorecendo a expansão dos ambientes marinhos rasos e a recuperação dos ecossistemas.', 'Os oceanos passaram por uma importante reorganização após a extinção do Ordoviciano. A elevação do nível do mar favoreceu a expansão das plataformas continentais e a recuperação dos recifes. Braquiópodes, trilobitas, graptólitos e moluscos voltaram a ocupar diferentes nichos ecológicos. Os graptólitos, especialmente, eram componentes importantes do plâncton e constituem fósseis fundamentais para a identificação das camadas geológicas dessa época.', 'As primeiras evidências de plantas terrestres vasculares aparecem no registro fóssil durante o Siluriano. Organismos semelhantes a Cooksonia apresentavam pequenos caules ramificados e estruturas reprodutivas nas extremidades. Essas plantas eram pequenas e provavelmente viviam em ambientes úmidos, próximos a rios e regiões costeiras. Algas e microrganismos fotossintetizantes continuavam desempenhando um papel importante nos ecossistemas aquáticos.', 'Os ambientes marinhos incluíam plataformas continentais, mares rasos, recifes e fundos oceânicos. Nas regiões continentais, áreas úmidas e margens de rios começaram a receber as primeiras plantas vasculares e artrópodes terrestres. Esses ambientes ainda eram relativamente simples quando comparados aos ecossistemas terrestres que se desenvolveriam nos períodos seguintes.', 'A biodiversidade marinha incluía trilobitas, braquiópodes, moluscos, crinoides, graptólitos, corais e diferentes grupos de peixes primitivos. Os peixes sem mandíbulas continuavam importantes, enquanto os primeiros vertebrados com mandíbulas começaram a aparecer e se diversificar. Nos ambientes terrestres, plantas primitivas e artrópodes representam alguns dos primeiros organismos conhecidos a ocupar o continente.', 'Llandovery é dividido nos estágios Rhuddaniano, Aeroniano e Teliquiano. Seu nome está relacionado à localidade de Llandovery, no País de Gales. Essa época foi fundamental para a recuperação da biodiversidade após a extinção do Ordoviciano e para o início da expansão de plantas vasculares nos ambientes terrestres.'),
(48, 'wenlock', 'Wenlock', 'epoca', 432.9000, 426.7000, 37, 'Wenlock foi a segunda época do período Siluriano e correspondeu a uma fase de desenvolvimento e diversificação dos ecossistemas marinhos. Durante esse intervalo, os recifes atingiram grande desenvolvimento, enquanto diferentes grupos de peixes continuaram sua evolução. Nos ambientes terrestres, as plantas vasculares primitivas começaram a apresentar maior diversidade, e os artrópodes passaram a ocupar diferentes habitats continentais. As comunidades marinhas apresentavam relações ecológicas cada vez mais complexas.', 'Gondwana continuava ocupando grande parte do hemisfério sul, enquanto Laurentia e Báltica se aproximavam progressivamente. A aproximação dessas massas continentais contribuiu para a redução gradual do oceano Iapetus e para a formação do continente Laurússia. Sibéria permanecia relativamente isolada. A configuração continental favorecia a existência de extensos mares rasos e plataformas continentais em diferentes regiões.', 'O clima era relativamente quente durante grande parte da época, sem a presença de grandes geleiras continentais. O nível do mar permanecia elevado, favorecendo a expansão de mares rasos e o desenvolvimento de recifes. As condições climáticas permitiam o crescimento de vegetação primitiva em ambientes úmidos e a diversificação de organismos marinhos em diferentes regiões do planeta.', 'Os oceanos apresentavam recifes bem desenvolvidos, formados principalmente por corais e estromatoporoides. Esses ambientes sustentavam comunidades diversificadas de invertebrados, incluindo braquiópodes, trilobitas, moluscos e crinoides. Os peixes continuavam ocupando diferentes posições nas cadeias alimentares, enquanto os graptólitos eram importantes organismos planctônicos. A diversidade dos habitats favorecia a especialização ecológica de diferentes grupos.', 'As plantas vasculares primitivas continuaram sua expansão. Cooksonia é um dos exemplos conhecidos de plantas desse intervalo, apresentando pequenos caules ramificados e estruturas reprodutivas. Também existiam outras formas vegetais simples, ainda sem folhas e raízes verdadeiras como as das plantas modernas. A vegetação ocupava principalmente regiões úmidas e próximas a corpos de água, enquanto os primeiros artrópodes terrestres começavam a se estabelecer nesses ambientes.', 'Os ambientes marinhos incluíam extensos recifes, plataformas continentais e fundos oceânicos. Nas regiões continentais, áreas úmidas, margens de rios e superfícies próximas a corpos de água ofereciam habitats para plantas primitivas e artrópodes. A ocupação desses ambientes representava uma etapa importante na formação dos primeiros ecossistemas terrestres.', 'A fauna marinha era composta por trilobitas, braquiópodes, moluscos, briozoários, crinoides, corais, graptólitos e diferentes peixes primitivos. Os peixes placodermos e outros vertebrados com mandíbulas começaram a se diversificar. Nos continentes, artrópodes como miriápodes e outros invertebrados passaram a ocupar ambientes terrestres. Alguns dos primeiros registros de animais capazes de respirar fora da água são associados a esse intervalo.', 'Wenlock é dividido nos estágios Sheinwoodiano e Homeriano. Seu nome tem origem na região de Much Wenlock, na Inglaterra. Essa época é importante para o estudo da evolução das plantas vasculares e dos primeiros animais terrestres, além de apresentar alguns dos recifes mais desenvolvidos do Siluriano.'),
(49, 'ludlow', 'Ludlow', 'epoca', 426.7000, 422.7000, 37, 'Ludlow foi a terceira época do período Siluriano e apresentou uma continuidade da diversificação dos organismos marinhos e terrestres. Os recifes permaneceram importantes componentes dos ambientes oceânicos, enquanto diferentes grupos de peixes com mandíbulas e sem mandíbulas se diversificaram. As plantas vasculares também continuaram sua evolução, contribuindo para a expansão da vegetação em ambientes continentais úmidos. O intervalo foi marcado por ecossistemas cada vez mais complexos e pela consolidação de importantes transformações evolutivas iniciadas nas épocas anteriores.', 'Gondwana permanecia como uma extensa massa continental no hemisfério sul. Laurentia e Báltica já haviam se aproximado significativamente, formando a Laurússia, também conhecida como Euramérica. Esse processo estava relacionado ao fechamento progressivo do oceano Iapetus e a eventos de colisão continental. Sibéria continuava separada das demais massas continentais. As mudanças tectônicas influenciavam a distribuição dos mares e das regiões costeiras.', 'O clima era predominantemente quente e relativamente estável, com temperaturas favoráveis ao desenvolvimento de ecossistemas marinhos e terrestres. O nível dos oceanos permanecia relativamente elevado, embora ocorressem oscilações regionais. Essas condições favoreciam a manutenção de recifes e a expansão de ambientes úmidos onde plantas vasculares e artrópodes podiam se desenvolver.', 'Os oceanos apresentavam extensos recifes e comunidades diversificadas de organismos. Corais e estromatoporoides formavam estruturas que serviam de abrigo para diferentes invertebrados. Braquiópodes, trilobitas, moluscos, crinoides e graptólitos continuavam presentes. Os peixes com mandíbulas tornaram-se mais diversificados e passaram a ocupar diferentes nichos alimentares nos ambientes aquáticos.', 'A vegetação terrestre continuava se diversificando, com plantas vasculares primitivas ocupando regiões úmidas e margens de corpos de água. Cooksonia e outras plantas de organização simples representam parte dessa vegetação. Alguns grupos vegetais apresentavam estruturas condutoras que permitiam maior eficiência no transporte de água e nutrientes. Embora ainda não existissem florestas desenvolvidas, essas transformações preparavam o caminho para a expansão da vegetação nos períodos seguintes.', 'Os ambientes marinhos incluíam recifes, plataformas continentais, mares rasos e regiões de fundo oceânico. Nos continentes, áreas úmidas e regiões costeiras eram ocupadas por plantas vasculares e artrópodes. Esses ambientes permitiam o desenvolvimento de comunidades terrestres ainda pequenas e pouco complexas, mas importantes para a evolução da vida fora da água.', 'A biodiversidade marinha incluía trilobitas, braquiópodes, moluscos, corais, crinoides e graptólitos. Os peixes placodermos e outros vertebrados com mandíbulas continuaram sua diversificação. Entre os organismos terrestres, destacavam-se plantas vasculares primitivas e artrópodes, que ocupavam ambientes úmidos e costeiros. A presença desses organismos demonstra o avanço gradual da colonização dos continentes.', 'Ludlow é dividido nos estágios Gorstiano e Ludfordiano. Seu nome está relacionado à cidade de Ludlow, na Inglaterra. A época representa uma etapa importante na evolução dos peixes com mandíbulas e na expansão das primeiras comunidades terrestres. Também apresenta registros fósseis importantes para compreender a transformação dos ecossistemas no final do Siluriano.'),
(50, 'pridoli', 'Pridoli', 'epoca', 422.7000, 419.6200, 37, 'Pridoli foi a quarta e última época do período Siluriano. Durante esse intervalo, os ecossistemas marinhos continuaram apresentando grande diversidade, enquanto os vertebrados aquáticos e as plantas terrestres passaram por novas transformações evolutivas. Os peixes com mandíbulas tornaram-se cada vez mais diversificados, e as plantas vasculares continuaram ocupando ambientes continentais. A época também representou uma fase de transição para o Devoniano, período em que as florestas e os vertebrados terrestres se desenvolveriam ainda mais.', 'Gondwana permanecia como uma grande massa continental localizada principalmente no hemisfério sul, enquanto a Laurússia já estava formada pela aproximação de Laurentia e Báltica. Sibéria continuava como uma massa continental separada. Os movimentos tectônicos contribuíam para a reorganização das regiões continentais e para mudanças na distribuição dos mares e das plataformas costeiras.', 'O clima era predominantemente quente, com condições favoráveis à manutenção de ambientes marinhos e ao desenvolvimento de plantas primitivas em regiões úmidas. Não havia grandes calotas polares permanentes como aquelas observadas durante o final do Ordoviciano. As condições ambientais permitiam a continuidade da diversificação dos organismos e a expansão gradual da vida nos continentes.', 'Os oceanos continuavam abrigando comunidades diversificadas de invertebrados e vertebrados. Recifes, plataformas continentais e mares rasos sustentavam diferentes organismos, incluindo braquiópodes, trilobitas, moluscos, corais e crinoides. Os peixes com mandíbulas continuavam sua diversificação, enquanto os peixes sem mandíbulas permaneciam presentes em diversos ambientes aquáticos.', 'As plantas vasculares continuaram se diversificando e ocupando diferentes regiões continentais. Formas primitivas de licófitas e outras plantas vasculares começaram a apresentar maior variedade de estruturas e adaptações. Embora as florestas ainda não apresentassem a complexidade que atingiriam no Devoniano, a vegetação terrestre já desempenhava um papel importante na transformação dos ambientes úmidos e costeiros.', 'Os ambientes marinhos incluíam recifes, mares rasos, plataformas continentais e fundos oceânicos. Nos continentes, regiões úmidas, margens de rios e áreas alagadas abrigavam plantas vasculares e artrópodes. Esses ambientes representavam etapas iniciais de ecossistemas terrestres mais complexos, que se desenvolveriam durante o Devoniano.', 'A biodiversidade incluía braquiópodes, trilobitas, moluscos, crinoides, corais e diferentes grupos de peixes. Os vertebrados com mandíbulas continuaram se diversificando, incluindo placodermos e outros peixes ósseos primitivos. Entre os organismos terrestres, plantas vasculares e artrópodes ocupavam diferentes habitats, demonstrando o avanço da colonização dos continentes.', 'Pridoli é a última época do período Siluriano e não possui subdivisões formais em estágios na escala internacional. Seu nome deriva de uma localidade próxima a Praga, na atual República Tcheca. Essa época representa a transição entre o Siluriano e o Devoniano, antecedendo a expansão das florestas e a grande diversificação dos peixes que caracterizariam o período seguinte.'),
(51, 'devoniano-inferior', 'Devoniano Inferior', 'epoca', 419.6200, 393.4700, 38, 'O Devoniano Inferior marcou o início de um período de importantes transformações na vida terrestre e marinha. Durante essa época, os oceanos abrigavam uma grande diversidade de peixes, incluindo formas primitivas de peixes ósseos e placodermos. Nos continentes, as primeiras plantas vasculares continuaram se diversificando e começaram a ocupar áreas maiores, enquanto os primeiros artrópodes terrestres já estavam presentes em alguns ambientes. Foi uma etapa fundamental para a expansão da vida fora dos oceanos.', 'Os continentes estavam distribuídos de maneira bastante diferente da configuração atual. Gondwana ocupava grande parte do hemisfério sul, enquanto Laurentia e Báltica se encontravam em regiões mais próximas do equador. A aproximação entre essas massas continentais contribuía para mudanças geológicas e para a formação gradual de novas regiões continentais. O continente Euramérica começava a se consolidar a partir da união de Laurentia e Báltica.', 'O clima era predominantemente quente, com condições que variavam conforme a latitude e a região. Muitas áreas próximas ao equador apresentavam temperaturas elevadas, enquanto regiões mais distantes podiam apresentar condições mais amenas. A presença de ambientes úmidos favorecia a expansão das primeiras plantas vasculares, embora grandes regiões continentais ainda fossem relativamente desprovidas de vegetação.', 'Os mares apresentavam grande diversidade de organismos e diferentes condições ambientais. Recifes e plataformas marinhas rasas eram importantes ambientes para a vida, abrigando trilobitas, braquiópodes, moluscos, corais e diversos grupos de peixes. A circulação oceânica e a distribuição dos mares rasos influenciavam a biodiversidade e a disponibilidade de habitats.', 'A vegetação era formada principalmente por plantas vasculares primitivas, como licófitas e outras plantas de pequeno porte. Entre os exemplos conhecidos estão formas semelhantes a Cooksonia e plantas relacionadas aos primeiros grupos de traqueófitas. Essas plantas ainda não formavam florestas extensas, mas representavam uma etapa importante na colonização dos continentes.', 'Os ambientes incluíam mares rasos, plataformas continentais, regiões costeiras, planícies aluviais e áreas próximas a rios. Nas regiões terrestres, paisagens com vegetação baixa e esparsa começavam a se desenvolver. Os ambientes aquáticos continuavam sendo os principais centros de diversidade biológica, enquanto os ecossistemas terrestres apresentavam comunidades ainda relativamente simples.', 'A vida marinha era dominada por uma grande variedade de peixes, incluindo placodermos, peixes sem mandíbulas, acantódios e formas primitivas de peixes ósseos. Trilobitas, braquiópodes, moluscos e corais também eram comuns. Em terra, plantas vasculares e artrópodes representavam alguns dos principais organismos já estabelecidos fora da água.', 'O Devoniano Inferior inclui três estágios internacionais: Lochkoviano, Praguiano e Emsiano. Durante essa época, os peixes passaram por uma importante diversificação evolutiva, motivo pelo qual o Devoniano é frequentemente conhecido como a Era dos Peixes. Também ocorreram avanços importantes na evolução das plantas terrestres.'),
(52, 'devoniano-medio', 'Devoniano Médio', 'epoca', 393.4700, 382.3100, 38, 'O Devoniano Médio foi uma época de intensa diversificação da vida marinha e de importantes mudanças nos ecossistemas terrestres. Os peixes apresentavam uma variedade cada vez maior de formas e adaptações, enquanto os recifes marinhos atingiam grande desenvolvimento em diversas regiões. Nos continentes, as plantas vasculares continuavam evoluindo e se tornando mais complexas, contribuindo para a transformação das paisagens terrestres.', 'A configuração continental continuava sendo marcada pela presença de Gondwana no hemisfério sul e pela aproximação entre Laurentia e Báltica, que formavam a Euramérica. As regiões continentais próximas ao equador apresentavam condições favoráveis ao desenvolvimento de ecossistemas terrestres e marinhos. A movimentação das placas tectônicas também influenciava a formação de cadeias montanhosas e a distribuição dos mares.', 'O clima permanecia predominantemente quente em grande parte do planeta, embora existissem diferenças regionais relacionadas à latitude, altitude e proximidade dos oceanos. Muitas regiões equatoriais apresentavam condições quentes e úmidas, favoráveis ao crescimento da vegetação. Alterações ambientais e climáticas também afetavam os ecossistemas marinhos ao longo dessa época.', 'Os oceanos apresentavam ecossistemas bastante diversificados, com extensos recifes formados por corais e estromatoporoides. Os mares rasos ofereciam habitats para peixes, trilobitas, braquiópodes e moluscos. Durante o Devoniano Médio, algumas regiões marinhas passaram por mudanças ambientais significativas, incluindo episódios de redução do oxigênio nas águas, que afetaram a distribuição dos organismos.', 'A vegetação terrestre tornou-se progressivamente mais complexa. Plantas vasculares desenvolveram estruturas mais elaboradas, incluindo sistemas de sustentação e condução de nutrientes. Surgiram formas arbóreas primitivas, como Wattieza, relacionadas aos primeiros ambientes florestais. A expansão dessas plantas contribuiu para modificar os solos, a retenção de água e os ciclos de nutrientes.', 'Os ambientes incluíam extensos recifes marinhos, plataformas continentais, mares rasos, rios e planícies aluviais. Em terra, áreas úmidas e regiões próximas a cursos de água passaram a apresentar vegetação mais desenvolvida. O crescimento das primeiras estruturas florestais começou a transformar os ecossistemas terrestres e a criar novos habitats para os organismos.', 'Os peixes continuaram sua diversificação, com destaque para os placodermos, peixes ósseos e outros grupos primitivos. Entre os organismos marinhos também estavam presentes corais, estromatoporoides, trilobitas e braquiópodes. Nos ambientes terrestres, plantas vasculares e artrópodes ocupavam diferentes habitats. Surgiram também importantes linhagens de vertebrados com características relacionadas à futura ocupação do ambiente terrestre.', 'O Devoniano Médio compreende os estágios Eifeliano e Givetiano. Nessa época, desenvolveram-se algumas das primeiras florestas conhecidas, representando uma transformação significativa dos ambientes continentais. Também ocorreram episódios de perturbação ambiental nos oceanos, como o evento Kellwasser, associado principalmente à transição para o Devoniano Superior.'),
(53, 'devoniano-superior', 'Devoniano Superior', 'epoca', 382.3100, 358.8600, 38, 'O Devoniano Superior foi marcado por importantes transformações evolutivas e ambientais. As florestas terrestres tornaram-se mais desenvolvidas, com plantas de maior porte e sistemas radiculares mais complexos. Nos ambientes aquáticos, os peixes continuavam apresentando grande diversidade, enquanto alguns vertebrados desenvolveram características que permitiram a exploração de ambientes próximos à água e, posteriormente, a ocupação do ambiente terrestre. Essa época também foi marcada por uma série de crises ambientais que provocaram uma das grandes extinções em massa da história da Terra.', 'Gondwana continuava ocupando grande parte do hemisfério sul, enquanto a Euramérica estava posicionada em regiões próximas ao equador. A movimentação das placas tectônicas provocava mudanças na distribuição dos mares e na formação de cadeias montanhosas. A aproximação entre os continentes contribuiu para processos geológicos que, ao longo do tempo, participariam da formação do supercontinente Pangeia.', 'O clima apresentava variações regionais, com condições geralmente quentes em muitas regiões equatoriais. A expansão das florestas alterava o funcionamento dos ecossistemas continentais, influenciando a umidade dos solos e os ciclos de carbono. Durante o Devoniano Superior, mudanças climáticas e ambientais contribuíram para episódios de instabilidade nos oceanos e para importantes crises biológicas.', 'Os ambientes marinhos passaram por alterações significativas. Em diversas regiões, episódios de anoxia, caracterizados pela diminuição do oxigênio dissolvido na água, afetaram a sobrevivência de organismos. Os recifes, anteriormente muito desenvolvidos, sofreram impactos importantes. Mesmo assim, os oceanos ainda abrigavam peixes, moluscos, braquiópodes e diversos outros grupos de invertebrados.', 'As florestas tornaram-se mais extensas e complexas, com plantas vasculares de maior porte, incluindo licófitas e outras linhagens primitivas de plantas arbóreas. Archaeopteris, uma planta semelhante a uma árvore e relacionada às progimnospermas, formava grandes estruturas florestais. Essas comunidades vegetais apresentavam raízes mais desenvolvidas e contribuíam para a formação de solos mais complexos.', 'Os ambientes terrestres incluíam florestas primitivas, áreas alagadas, planícies fluviais e regiões costeiras. Os rios e lagos eram habitats importantes para peixes e vertebrados próximos à transição entre a vida aquática e terrestre. Nos mares, recifes e plataformas continentais continuavam existindo, embora muitos tenham sido afetados pelas crises ambientais do final do Devoniano.', 'Os peixes apresentavam grande diversidade, incluindo placodermos, peixes ósseos e peixes de nadadeiras lobadas. Entre os vertebrados mais importantes dessa época estavam formas próximas à origem dos primeiros tetrápodes, como Acanthostega e Ichthyostega, que possuíam membros e características associadas à locomoção em ambientes rasos. Nas florestas, plantas de grande porte e artrópodes terrestres ocupavam diferentes nichos ecológicos.', 'O Devoniano Superior compreende os estágios Frasniano e Fameniano. Essa época foi marcada por importantes eventos de extinção, especialmente os eventos Kellwasser, no final do Frasniano, e Hangenberg, próximo ao final do Devoniano. Essas crises provocaram grandes perdas na biodiversidade marinha, incluindo o desaparecimento de muitos grupos de placodermos e a redução dos recifes de corais.'),
(54, 'mississippiano', 'Mississippiano', 'epoca', 358.8600, 323.4000, 39, 'O Mississippiano corresponde à primeira grande subdivisão do Carbonífero e foi marcado pela expansão de ambientes marinhos rasos e pelo desenvolvimento de extensas florestas em regiões úmidas. Os oceanos abrigavam uma grande diversidade de organismos, especialmente crinoides, braquiópodes, corais, moluscos e peixes. Nos continentes, as plantas vasculares continuaram se diversificando, formando comunidades vegetais cada vez mais complexas. As condições ambientais de muitas regiões favoreceram a formação de depósitos de calcário e outros sedimentos marinhos.', 'Durante o Mississippiano, os continentes ainda estavam distribuídos de maneira diferente da configuração atual. Gondwana ocupava grande parte do hemisfério sul, enquanto a Euramérica, formada pela aproximação de Laurentia e Báltica, encontrava-se em latitudes próximas ao equador. A aproximação entre Gondwana e os continentes do norte contribuía para os processos tectônicos que posteriormente participariam da formação da Pangeia. Grandes áreas continentais eram cobertas por mares rasos, especialmente nas regiões equatoriais.', 'O clima variava bastante de acordo com a localização geográfica. Nas regiões equatoriais, predominavam condições quentes e úmidas, favoráveis ao desenvolvimento de vegetação abundante. Em partes de Gondwana, especialmente nas regiões mais austrais, o clima era mais frio e existiam condições associadas à glaciação. Essa diferença climática entre as regiões influenciava a distribuição dos ambientes e dos organismos.', 'Os oceanos apresentavam extensas plataformas continentais e mares rasos, ambientes que favoreciam o desenvolvimento de comunidades marinhas diversificadas. Crinoides e outros equinodermos eram particularmente abundantes, formando grandes concentrações em determinados ambientes. Corais, braquiópodes, moluscos, trilobitas e peixes também ocupavam os mares. A deposição de carbonatos em águas rasas contribuiu para a formação de extensos depósitos de calcário.', 'A vegetação terrestre era composta por diversas plantas vasculares, incluindo licófitas, esfenófitas, samambaias e progimnospermas remanescentes. Em regiões úmidas, essas plantas formavam comunidades densas, principalmente próximas a rios e áreas alagadas. Embora as grandes florestas pantanosas associadas à formação de carvão tenham atingido seu desenvolvimento mais conhecido posteriormente, a vegetação já apresentava considerável diversidade e complexidade.', 'Os ambientes incluíam mares tropicais rasos, plataformas carbonáticas, recifes, regiões costeiras, rios, planícies aluviais e áreas pantanosas. Os mares rasos eram especialmente importantes para a biodiversidade marinha e para a formação de calcários. Nos continentes, áreas úmidas sustentavam comunidades vegetais e diferentes grupos de artrópodes, enquanto regiões mais frias de Gondwana apresentavam condições ambientais distintas.', 'A vida marinha era extremamente diversificada, com destaque para crinoides, braquiópodes, corais, briozoários, moluscos e peixes cartilaginosos e ósseos. Trilobitas ainda estavam presentes, embora já tivessem perdido parte de sua diversidade em comparação com períodos anteriores. Nos ambientes terrestres, artrópodes, anfíbios primitivos e diferentes grupos de plantas vasculares ocupavam os ecossistemas continentais.', 'O Mississippiano compreende três épocas formais na subdivisão norte-americana: Tournaisiano, Viseano e Serpukhoviano. Seu nome está relacionado ao vale do rio Mississippi, na América do Norte, onde foram estudadas importantes sequências de rochas dessa idade. A época também é conhecida pela abundância de organismos marinhos e pela formação de extensos depósitos de calcário.'),
(55, 'pensilvaniano', 'Pensilvaniano', 'epoca', 323.4000, 298.9000, 39, 'O Pensilvaniano foi uma época marcada pelo desenvolvimento de extensas florestas pantanosas, pela diversificação dos vertebrados terrestres e pela expansão de ambientes continentais úmidos. Grandes áreas de vegetação acumulavam matéria orgânica que, ao longo de milhões de anos, contribuiu para a formação de importantes depósitos de carvão mineral. Durante essa época, os primeiros amniotas se diversificaram, representando um avanço fundamental na evolução dos vertebrados terrestres. Os continentes também continuaram sua aproximação, preparando as condições para a formação da Pangeia.', 'A movimentação das placas tectônicas aproximava progressivamente Gondwana e Euramérica, enquanto outros blocos continentais também participavam desse processo. A Euramérica permanecia em regiões equatoriais, onde se desenvolviam extensas florestas tropicais. Gondwana ocupava grande parte do hemisfério sul e ainda apresentava importantes áreas afetadas por condições glaciais. A colisão gradual entre massas continentais contribuía para a formação de cadeias montanhosas e para a consolidação da Pangeia.', 'O clima apresentava diferenças regionais bastante marcantes. Nas regiões equatoriais, predominavam condições quentes e úmidas, com chuvas abundantes que favoreciam o crescimento de florestas pantanosas. Em outras regiões, especialmente em partes de Gondwana, ainda existiam condições frias associadas às glaciações. Ao longo do Pensilvaniano, ocorreram oscilações climáticas e do nível do mar, que influenciaram a distribuição dos ambientes e dos ecossistemas.', 'Os mares continuavam abrigando uma grande diversidade de organismos, incluindo braquiópodes, crinoides, corais, moluscos, foraminíferos e peixes. Plataformas continentais e mares rasos eram ambientes importantes para a vida marinha. As oscilações do nível do mar provocavam mudanças na extensão desses ambientes, alternando períodos de expansão e retração das áreas marinhas sobre os continentes.', 'A vegetação atingiu grande desenvolvimento em regiões tropicais úmidas. Florestas pantanosas eram dominadas por licófitas arbóreas, como Lepidodendron e Sigillaria, além de esfenófitas como Calamites e diversas samambaias. Também estavam presentes as primeiras plantas com sementes, incluindo formas relacionadas às pteridospermas. A enorme quantidade de matéria vegetal acumulada em ambientes alagados contribuiu para a formação de extensos depósitos de carvão.', 'Os ambientes incluíam vastas florestas pantanosas, planícies fluviais, deltas, lagos, regiões costeiras e mares rasos. As florestas tropicais eram caracterizadas por vegetação densa e grande disponibilidade de matéria orgânica. Os ambientes terrestres passaram a abrigar comunidades mais diversificadas de artrópodes e vertebrados, enquanto os ecossistemas aquáticos continuavam importantes para anfíbios e diferentes grupos de peixes.', 'A biodiversidade terrestre apresentou importantes avanços evolutivos. Anfíbios primitivos eram comuns em ambientes úmidos, enquanto os primeiros amniotas se diversificaram e passaram a apresentar adaptações que permitiam maior independência da água para a reprodução. Entre os animais conhecidos desse período estão Hylonomus e Archaeothyris, representantes de linhagens muito antigas de amniotas. Artrópodes de grande porte também estavam presentes, como algumas formas de milípedes e insetos. Nos oceanos, peixes, braquiópodes, crinoides e moluscos continuavam abundantes.', 'O Pensilvaniano compreende quatro épocas formais na subdivisão norte-americana: Bashkiriano, Moscoviano, Kasimoviano e Gzheliano. É especialmente conhecido pelas extensas florestas pantanosas que contribuíram para a formação de grandes depósitos de carvão mineral. Também foi uma etapa fundamental para a evolução dos vertebrados terrestres, pois os primeiros amniotas surgiram e começaram a se diversificar durante essa época.'),
(56, 'triassico-inferior', 'Triássico Inferior', 'epoca', 251.9020, 247.0000, 66, 'O Triássico Inferior foi a primeira época do período Triássico e começou após a grande extinção em massa do final do Permiano, o maior evento de extinção conhecido da história da Terra. Os ecossistemas ainda estavam em recuperação, e muitas comunidades marinhas e terrestres apresentavam diversidade reduzida. Apesar das condições ambientais difíceis, diferentes grupos de organismos sobreviveram e começaram a se diversificar novamente. Entre os vertebrados terrestres, os répteis e outros amniotas ganharam importância, enquanto os oceanos passaram por uma lenta reorganização de suas comunidades.', 'A maior parte das massas continentais estava reunida no supercontinente Pangeia, que se estendia por grande parte do planeta. Sua configuração apresentava uma enorme extensão territorial, desde regiões próximas ao polo norte até áreas do hemisfério sul. O oceano Panthalassa cobria grande parte da superfície oceânica, enquanto o mar de Tétis ocupava uma região entre as porções setentrionais e meridionais da Pangeia.', 'O clima era geralmente quente e apresentava condições áridas em grandes áreas do interior continental. A distância dos oceanos e a enorme extensão da Pangeia favoreciam a formação de regiões secas e desertos. Entretanto, existiam áreas costeiras e regiões próximas a rios onde a umidade permitia o desenvolvimento de vegetação. A recuperação dos ecossistemas também foi influenciada por alterações climáticas e ambientais posteriores à extinção do Permiano.', 'Os oceanos ainda apresentavam os efeitos da extinção em massa do final do Permiano. Em algumas regiões, as águas possuíam baixos níveis de oxigênio e condições químicas desfavoráveis à vida. Os recifes estavam em processo de recuperação, enquanto moluscos, braquiópodes, amonoides e diferentes grupos de peixes voltavam a ocupar os ambientes marinhos.', 'A vegetação era composta principalmente por gimnospermas, samambaias, licófitas e outras plantas vasculares sobreviventes. Coníferas e plantas semelhantes a cicadófitas ocupavam diferentes regiões continentais. A vegetação ainda apresentava mudanças relacionadas à recuperação dos ecossistemas após a extinção do Permiano, e muitas áreas interiores permaneciam relativamente secas.', 'Os ambientes incluíam desertos, planícies fluviais, regiões costeiras, lagos, mares rasos e extensas áreas continentais secas. As regiões próximas aos rios e lagos eram importantes refúgios para diferentes organismos terrestres. Nos oceanos, plataformas marinhas e ambientes costeiros ofereciam condições para a recuperação gradual das comunidades biológicas.', 'A fauna terrestre incluía terápsidos sobreviventes, répteis primitivos e diferentes grupos de anfíbios. Entre os animais marinhos estavam amonoides, moluscos, braquiópodes, equinodermos e peixes. Os ecossistemas ainda eram menos diversificados do que aqueles que existiam antes da extinção do Permiano, mas diferentes linhagens estavam se recuperando e ocupando novos nichos ecológicos.', 'O Triássico Inferior compreende as idades Induano e Olenekiano. Essa época começou imediatamente após a extinção Permiano-Triássico, ocorrida há aproximadamente 252 milhões de anos. A recuperação da biodiversidade foi gradual e desigual, e alguns grupos de organismos precisaram de milhões de anos para recuperar sua diversidade e importância ecológica.'),
(57, 'triassico-medio', 'Triássico Médio', 'epoca', 247.0000, 237.0000, 66, 'O Triássico Médio foi uma época de recuperação e diversificação dos ecossistemas terrestres e marinhos. Muitos grupos de animais que haviam sobrevivido à extinção do Permiano passaram por importantes processos de diversificação. Os répteis tornaram-se cada vez mais variados, incluindo linhagens que posteriormente dariam origem a importantes grupos de répteis marinhos e terrestres. Nos oceanos, os recifes começaram a se desenvolver novamente e os amonoides apresentaram grande diversificação.', 'A Pangeia continuava sendo o principal supercontinente do planeta, embora processos tectônicos e movimentações internas já provocassem mudanças em sua estrutura. O oceano Panthalassa permanecia ocupando a maior parte do planeta, enquanto o mar de Tétis apresentava grande importância para os ambientes marinhos. As regiões equatoriais da Pangeia eram caracterizadas por extensas áreas continentais, enquanto Gondwana ocupava grande parte das latitudes meridionais.', 'O clima permanecia predominantemente quente e sazonal, com regiões interiores frequentemente áridas e áreas costeiras mais úmidas. As monções e as variações sazonais influenciavam a distribuição das chuvas em diferentes partes da Pangeia. Em comparação com o início do Triássico, os ecossistemas apresentavam maior estabilidade e muitas comunidades biológicas estavam em processo de diversificação.', 'Os oceanos apresentavam uma recuperação significativa da biodiversidade. Recifes formados por organismos construtores voltavam a se desenvolver, enquanto amonoides, moluscos, braquiópodes e equinodermos ocupavam diferentes habitats. Os répteis marinhos também se diversificaram, incluindo ictiossauros e notossauros, que exploravam diferentes ambientes aquáticos.', 'A vegetação era dominada por gimnospermas, especialmente coníferas, cicadófitas e plantas relacionadas às bennettitales. Samambaias e outras plantas vasculares também ocupavam ambientes úmidos. Em diferentes regiões, as comunidades vegetais formavam paisagens relativamente densas, embora grandes áreas continentais ainda apresentassem condições áridas e vegetação mais esparsa.', 'Os ambientes incluíam desertos, florestas abertas, planícies fluviais, lagos, regiões costeiras, plataformas marinhas e recifes. Os mares rasos eram importantes para a diversificação de organismos marinhos, enquanto os ambientes terrestres abrigavam diferentes grupos de répteis, anfíbios e sinapsídeos. Regiões próximas a rios e lagos ofereciam habitats favoráveis para uma grande variedade de animais.', 'A fauna terrestre apresentava uma grande variedade de répteis, incluindo arcossauros e diferentes linhagens de diápsidos. Alguns grupos de arcossauros começaram a apresentar características que seriam importantes para a evolução dos dinossauros e crocodilianos. Nos oceanos, ictiossauros, notossauros e outros répteis marinhos coexistiam com peixes, amonoides e diversos invertebrados.', 'O Triássico Médio compreende as idades Anisiano e Ladiniano. Foi uma etapa importante para a diversificação dos répteis e para a recuperação dos ecossistemas marinhos. Durante essa época, diferentes linhagens de répteis passaram a ocupar ambientes terrestres e aquáticos, preparando o cenário para a grande diversificação dos dinossauros e de outros grupos durante o Triássico Superior.'),
(58, 'triassico-superior', 'Triássico Superior', 'epoca', 237.0000, 201.4000, 66, 'O Triássico Superior foi a última época do período Triássico e marcou uma importante etapa na evolução dos ecossistemas terrestres. Durante esse intervalo, surgiram os primeiros dinossauros conhecidos, assim como os primeiros mamíferos verdadeiros. Os arcossauros apresentavam grande diversidade e ocupavam diferentes nichos ecológicos, enquanto os répteis marinhos continuavam importantes nos oceanos. A época terminou com uma grande extinção em massa, que eliminou diversos grupos de organismos e abriu espaço para a expansão dos dinossauros durante o Jurássico.', 'A Pangeia continuava reunindo praticamente todas as grandes massas continentais, embora processos tectônicos começassem a provocar fraturas em algumas regiões. O oceano Panthalassa permanecia cobrindo a maior parte do planeta, enquanto o mar de Tétis ocupava áreas entre as porções setentrionais e meridionais do supercontinente. As regiões continentais apresentavam extensas áreas interiores, frequentemente distantes da influência moderadora dos oceanos.', 'O clima era predominantemente quente e apresentava forte sazonalidade em muitas regiões. Grandes áreas interiores da Pangeia possuíam condições áridas e semiáridas, enquanto regiões costeiras e próximas a rios apresentavam maior disponibilidade de água. Próximo ao final da época, intensas atividades vulcânicas associadas à Província Magmática do Atlântico Central contribuíram para alterações climáticas e ambientais relacionadas à extinção do final do Triássico.', 'Os oceanos apresentavam comunidades diversificadas, com amonoides, moluscos, equinodermos, corais e diferentes grupos de peixes. Répteis marinhos, como ictiossauros e plesiossauromorfos primitivos, ocupavam diferentes posições nas cadeias alimentares. No final do Triássico, alterações ambientais e químicas nos oceanos provocaram impactos importantes sobre os ecossistemas marinhos.', 'A vegetação era dominada por gimnospermas, incluindo coníferas, cicadófitas, bennettitales e ginkgófitas. Samambaias e outras plantas vasculares ocupavam regiões úmidas e ambientes próximos a cursos de água. Em muitas regiões continentais, a vegetação apresentava adaptações às condições sazonais e à disponibilidade variável de água.', 'Os ambientes incluíam desertos, florestas abertas, planícies aluviais, lagos, rios, regiões costeiras e mares rasos. Os ambientes terrestres abrigavam comunidades diversificadas de répteis, sinapsídeos e anfíbios. Nos oceanos, recifes e plataformas marinhas sustentavam uma grande diversidade de organismos. A fragmentação inicial de algumas regiões da Pangeia também começou a modificar a distribuição dos ambientes.', 'Os arcossauros apresentavam grande diversidade, incluindo dinossauros primitivos, pterossauros, crocodilomorfos e outros grupos. Entre os primeiros dinossauros conhecidos estavam formas como Coelophysis e Plateosaurus. Os primeiros mamíferos verdadeiros também surgiram durante o Triássico Superior, incluindo formas pequenas e geralmente insetívoras. Nos ambientes marinhos, ictiossauros, répteis relacionados aos plesiossauros, peixes e amonoides eram importantes componentes da fauna.', 'O Triássico Superior compreende as idades Carniano, Noriano e Rhaetiano. Os primeiros dinossauros e mamíferos surgiram durante essa época. Seu encerramento foi marcado pela extinção em massa do Triássico-Jurássico, há aproximadamente 201,4 milhões de anos, associada a intensas atividades vulcânicas e alterações climáticas. A crise eliminou diversos grupos de répteis e outros organismos, permitindo que os dinossauros se tornassem ainda mais dominantes durante o Jurássico.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(59, 'induano', 'Induano', 'idade', 251.9020, 250.8000, 56, 'O Induano foi a primeira idade do Triássico e começou imediatamente após a extinção em massa do final do Permiano. Os ecossistemas terrestres e marinhos ainda estavam profundamente afetados pela crise biológica, que provocou o desaparecimento de uma enorme parcela das espécies existentes. As comunidades sobreviventes eram relativamente simples e apresentavam baixa diversidade em comparação com os ecossistemas anteriores. A vida começou a se reorganizar gradualmente, embora muitas regiões ainda apresentassem condições ambientais extremas.', 'A Pangeia permanecia reunindo praticamente todas as massas continentais. Gondwana ocupava grande parte do hemisfério sul, enquanto a Laurásia correspondia às regiões setentrionais. O oceano Panthalassa cobria uma enorme extensão do planeta e o mar de Tétis ocupava uma região entre partes da Pangeia. A configuração continental favorecia grandes contrastes climáticos entre áreas costeiras e interiores.', 'As condições climáticas eram frequentemente extremas, com temperaturas elevadas em muitas regiões e extensas áreas áridas. A crise ambiental do final do Permiano provocou alterações no ciclo do carbono e no funcionamento dos ecossistemas. Algumas regiões apresentavam condições de calor intenso e baixa disponibilidade de água, dificultando a recuperação da vegetação e da fauna.', 'Os oceanos ainda apresentavam condições desfavoráveis em diversas regiões, incluindo águas com pouco oxigênio e alterações na composição química. Organismos marinhos sobreviventes, como moluscos, braquiópodes, amonoides e peixes, começaram a ocupar novamente diferentes habitats. Os recifes ainda eram pouco desenvolvidos e a biodiversidade marinha permanecia reduzida.', 'A vegetação era composta por plantas vasculares sobreviventes à extinção, incluindo samambaias, licófitas e gimnospermas primitivas. Em algumas regiões, a vegetação era bastante escassa devido às condições climáticas e ambientais. Comunidades vegetais começaram a se recuperar especialmente em áreas próximas a rios, lagos e regiões costeiras.', 'Os ambientes incluíam desertos, planícies áridas, rios, lagos, regiões costeiras e mares rasos. Muitos ecossistemas ainda estavam em processo de reorganização após a extinção. Áreas próximas a fontes de água ofereciam condições relativamente favoráveis para a sobrevivência de plantas e animais terrestres.', 'A fauna era composta principalmente por organismos que sobreviveram à extinção Permiano-Triássico. Entre os vertebrados terrestres estavam terápsidos, répteis primitivos e anfíbios. Nos oceanos, amonoides, moluscos, braquiópodes e peixes voltavam a ocupar diferentes nichos ecológicos, embora a diversidade ainda fosse limitada.', 'O Induano representa o início da recuperação da vida após a maior extinção em massa conhecida. Seu nome deriva da região do rio Indo, na Ásia. Essa idade foi marcada por condições ambientais difíceis e por uma recuperação biológica que ocorreu de maneira gradual e desigual entre os diferentes ecossistemas.'),
(60, 'olenekiano', 'Olenekiano', 'idade', 250.8000, 247.0000, 56, 'O Olenekiano foi a segunda idade do Triássico Inferior e correspondeu a uma etapa de recuperação e diversificação dos organismos sobreviventes à extinção do Permiano. Os ecossistemas marinhos começaram a apresentar maior diversidade, com a expansão de amonoides, moluscos e outros invertebrados. Nos continentes, diferentes grupos de répteis e terápsidos continuaram ocupando os ambientes terrestres, enquanto a vegetação apresentava sinais de recuperação em várias regiões.', 'A Pangeia continuava sendo o principal supercontinente, com Gondwana no hemisfério sul e as regiões correspondentes à Laurásia no hemisfério norte. O oceano Panthalassa permanecia dominante e o mar de Tétis ocupava regiões entre as massas continentais. A distribuição dos continentes ainda influenciava fortemente os contrastes climáticos e a disponibilidade de ambientes úmidos.', 'O clima permanecia quente em grande parte do planeta, com extensas regiões áridas no interior da Pangeia. Entretanto, algumas áreas apresentavam condições mais favoráveis ao desenvolvimento da vegetação. A recuperação dos ecossistemas foi acompanhada por mudanças ambientais e por uma maior diversificação de organismos terrestres e marinhos.', 'Os ambientes marinhos apresentavam uma recuperação gradual da biodiversidade. Amonoides tornaram-se especialmente importantes para a caracterização das rochas dessa idade. Peixes, moluscos, braquiópodes e outros invertebrados ocupavam os mares rasos, enquanto diferentes regiões oceânicas ainda apresentavam condições de oxigenação variável.', 'A vegetação incluía samambaias, licófitas, coníferas e outras gimnospermas primitivas. Em áreas úmidas, as plantas vasculares apresentavam maior desenvolvimento e começavam a ocupar ambientes anteriormente afetados pela crise do Permiano. Nas regiões mais áridas, a cobertura vegetal permanecia mais esparsa.', 'Os ambientes incluíam rios, lagos, planícies aluviais, desertos, regiões costeiras e plataformas marinhas. As áreas próximas a cursos de água eram importantes para a sobrevivência dos animais terrestres. Os ambientes marinhos rasos ofereciam condições favoráveis à recuperação de diferentes grupos de invertebrados e peixes.', 'A fauna terrestre incluía terápsidos, répteis e anfíbios, enquanto os oceanos abrigavam amonoides, peixes, moluscos e braquiópodes. Os répteis marinhos começaram a ocupar diferentes nichos aquáticos, e grupos como os ictiossauros apresentaram importantes diversificações durante o Triássico Inferior.', 'O Olenekiano é a última idade do Triássico Inferior. Seu nome está relacionado à região do rio Olenek, na Sibéria. Durante essa idade, os ecossistemas apresentaram avanços importantes em sua recuperação, preparando o cenário para a diversificação ainda maior dos organismos durante o Triássico Médio.'),
(61, 'anisiano', 'Anisiano', 'idade', 247.0000, 241.4640, 57, 'O Anisiano foi a primeira idade do Triássico Médio e marcou uma etapa de maior diversificação dos ecossistemas após a recuperação inicial do início do período. Os oceanos apresentavam comunidades mais complexas, com a expansão de amonoides, moluscos e outros invertebrados. Nos ambientes terrestres, os répteis continuaram se diversificando e diferentes linhagens de arcossauros passaram a ocupar importantes posições ecológicas.', 'A Pangeia permanecia reunindo os continentes, embora processos tectônicos continuassem modificando gradualmente sua estrutura. Gondwana ocupava as regiões austrais, enquanto a Laurásia abrangia as áreas setentrionais. O mar de Tétis e o oceano Panthalassa continuavam sendo importantes elementos da configuração geográfica e influenciavam a distribuição dos ambientes marinhos.', 'O clima era predominantemente quente, com condições áridas e sazonais em muitas regiões continentais. Áreas próximas ao equador apresentavam períodos úmidos e secos, enquanto regiões costeiras podiam receber maior influência oceânica. A estabilidade relativa dos ecossistemas favoreceu a expansão de diferentes grupos de plantas e animais.', 'Os mares apresentavam maior diversidade de organismos e condições favoráveis ao desenvolvimento de recifes em algumas regiões. Amonoides, braquiópodes, moluscos, equinodermos e peixes ocupavam diferentes ambientes. Os répteis marinhos também apresentavam diversificação, incluindo ictiossauros e notossauros.', 'A vegetação era composta por coníferas, cicadófitas, samambaias, ginkgófitas e outras plantas vasculares. As gimnospermas apresentavam grande importância nas comunidades terrestres, ocupando diferentes regiões da Pangeia. Em ambientes úmidos, samambaias e outras plantas formavam uma cobertura vegetal mais densa.', 'Os ambientes incluíam florestas abertas, planícies fluviais, lagos, desertos, regiões costeiras e mares rasos. Os rios e lagos eram importantes para anfíbios e outros vertebrados, enquanto as plataformas marinhas sustentavam comunidades diversificadas de invertebrados e peixes.', 'A fauna terrestre incluía arcossauros, terápsidos, anfíbios e outros répteis. Nos oceanos, ictiossauros e notossauros ocupavam diferentes posições nas cadeias alimentares. A diversificação dos répteis durante essa idade contribuiu para o desenvolvimento de linhagens que se tornariam importantes durante o restante do Mesozoico.', 'O Anisiano representa o início do Triássico Médio. Durante essa idade, os ecossistemas marinhos e terrestres apresentaram uma recuperação mais evidente em comparação com o início do período. Seu nome deriva de uma referência geográfica associada à região dos Alpes.'),
(62, 'ladiniano', 'Ladiniano', 'idade', 241.4640, 237.0000, 57, 'O Ladiniano foi a segunda idade do Triássico Médio e apresentou uma importante diversificação dos répteis marinhos e terrestres. Os oceanos abrigavam comunidades complexas, incluindo ictiossauros, notossauros, amonoides e diferentes invertebrados. Nos continentes, os arcossauros continuaram evoluindo e ocupando novos nichos ecológicos. A vegetação era dominada por gimnospermas, enquanto diferentes ambientes terrestres apresentavam comunidades cada vez mais diversificadas.', 'A Pangeia continuava sendo o principal supercontinente, com grandes regiões continentais próximas ao equador e extensas áreas austrais pertencentes a Gondwana. O oceano Panthalassa e o mar de Tétis influenciavam a distribuição dos ambientes marinhos. A movimentação tectônica continuava provocando alterações nas margens continentais e nas regiões costeiras.', 'O clima permanecia quente e sazonal, com áreas interiores frequentemente secas e regiões costeiras mais úmidas. As variações na distribuição das chuvas influenciavam a vegetação e os ambientes continentais. Em algumas regiões, condições favoráveis permitiam a existência de florestas abertas e comunidades vegetais relativamente densas.', 'Os oceanos apresentavam grande diversidade de répteis marinhos e invertebrados. Recifes e plataformas marinhas sustentavam comunidades de corais, moluscos, braquiópodes e equinodermos. Amonoides eram abundantes e importantes para a identificação das camadas geológicas dessa idade.', 'A vegetação era dominada por coníferas, cicadófitas, ginkgófitas e outras gimnospermas. Samambaias e plantas vasculares menores ocupavam áreas úmidas e regiões próximas a rios. As comunidades vegetais apresentavam adaptações às condições sazonais de muitas regiões continentais.', 'Os ambientes incluíam florestas abertas, planícies aluviais, rios, lagos, regiões costeiras, mares rasos e recifes. Os ambientes marinhos eram especialmente importantes para a diversidade de répteis aquáticos e invertebrados. Nos continentes, diferentes grupos de répteis e anfíbios ocupavam habitats terrestres e de água doce.', 'Entre os animais marinhos estavam ictiossauros, notossauros, peixes, amonoides e diferentes invertebrados. Nos ambientes terrestres, arcossauros, terápsidos e outros répteis continuavam se diversificando. Essa diversidade preparou o cenário para o surgimento e a expansão dos primeiros dinossauros no Triássico Superior.', 'O Ladiniano corresponde à última idade do Triássico Médio. Seu nome está relacionado à região dos Dolomitas, nos Alpes. Durante essa idade, os répteis marinhos apresentaram uma diversificação importante, e os ecossistemas aproximaram-se da complexidade que caracterizaria o Triássico Superior.'),
(63, 'carniano', 'Carniano', 'idade', 237.0000, 227.0000, 58, 'O Carniano foi a primeira idade do Triássico Superior e correspondeu a uma etapa importante para a evolução dos ecossistemas terrestres. Durante esse intervalo, surgiram os primeiros dinossauros conhecidos, ainda relativamente pequenos e pouco diversificados em comparação com os grupos que dominariam o Jurássico. Os arcossauros apresentavam grande variedade, enquanto os oceanos continuavam abrigando répteis marinhos, amonoides, peixes e invertebrados. Também ocorreu um importante episódio de mudanças climáticas conhecido como Episódio Pluvial Carniano.', 'A Pangeia permanecia reunindo as principais massas continentais, embora processos tectônicos começassem a preparar a futura fragmentação do supercontinente. O oceano Panthalassa cobria grande parte do planeta, enquanto o mar de Tétis ocupava regiões entre as porções setentrionais e meridionais da Pangeia. As regiões interiores eram extensas e apresentavam fortes contrastes ambientais em relação às áreas costeiras.', 'O clima era geralmente quente e sazonal, com extensas regiões áridas. Entretanto, durante o Episódio Pluvial Carniano ocorreram mudanças importantes no regime de chuvas, com períodos de aumento da umidade em diversas regiões. Essas alterações climáticas modificaram os ecossistemas terrestres e podem ter favorecido a expansão de diferentes grupos de plantas e animais.', 'Os oceanos abrigavam comunidades diversificadas de amonoides, moluscos, braquiópodes, corais e peixes. Répteis marinhos, como ictiossauros e diferentes grupos de sauropterígios, ocupavam as cadeias alimentares aquáticas. As mudanças climáticas do Carniano também afetaram os ambientes marinhos e a distribuição dos organismos.', 'A vegetação era composta principalmente por coníferas, cicadófitas, ginkgófitas, samambaias e outras plantas vasculares. As alterações na umidade durante o Episódio Pluvial Carniano favoreceram a expansão de algumas comunidades vegetais em regiões anteriormente mais secas. As gimnospermas continuavam sendo importantes componentes das paisagens terrestres.', 'Os ambientes incluíam desertos, florestas abertas, planícies fluviais, lagos, regiões costeiras e mares rasos. Durante os intervalos mais úmidos do Episódio Pluvial Carniano, algumas regiões passaram a apresentar rios mais ativos, lagos maiores e maior disponibilidade de água. Esses ambientes favoreciam a ocupação por diferentes grupos de vertebrados.', 'A fauna terrestre incluía diversos arcossauros, rincossauros, dicinodontes e outros répteis. Os primeiros dinossauros conhecidos surgiram durante o Triássico Superior, com formas primitivas como Eoraptor e Herrerasaurus associadas a depósitos do Carniano ou próximas de sua transição. Nos mares, ictiossauros, amonoides, peixes e invertebrados continuavam abundantes.', 'O Carniano é especialmente conhecido pelo Episódio Pluvial Carniano, um intervalo de mudanças climáticas que provocou aumento das chuvas em diversas regiões do planeta. Esse evento está associado a importantes transformações ecológicas e pode ter contribuído para a diversificação de diferentes grupos, incluindo as linhagens iniciais dos dinossauros.'),
(64, 'noriano', 'Noriano', 'idade', 227.0000, 205.7000, 58, 'O Noriano foi a segunda idade do Triássico Superior e apresentou uma grande diversificação dos dinossauros e de outros grupos de arcossauros. Os dinossauros passaram a ocupar diferentes nichos ecológicos, embora ainda coexistissem com numerosos outros répteis terrestres. Os oceanos continuavam abrigando répteis marinhos e uma grande diversidade de invertebrados. Os primeiros mamíferos também estavam presentes durante o Triássico Superior, enquanto as comunidades vegetais eram dominadas por gimnospermas.', 'A Pangeia continuava sendo o principal supercontinente, embora processos tectônicos provocassem alterações graduais em sua estrutura. Gondwana ocupava grande parte do hemisfério sul, enquanto a Laurásia abrangia as regiões setentrionais. O oceano Panthalassa e o mar de Tétis continuavam influenciando os ambientes marinhos e as condições climáticas das regiões costeiras.', 'O clima era predominantemente quente, com forte sazonalidade e extensas regiões áridas no interior continental. As áreas próximas aos oceanos e aos grandes sistemas fluviais apresentavam maior disponibilidade de água. As condições ambientais variavam de acordo com a latitude, a altitude e a proximidade dos mares.', 'Os mares apresentavam comunidades diversificadas, incluindo amonoides, moluscos, braquiópodes, equinodermos, corais e peixes. Ictiossauros e outros répteis marinhos ocupavam diferentes nichos ecológicos. Os ambientes marinhos continuavam importantes para a biodiversidade, enquanto os mares rasos ofereciam condições favoráveis à vida de numerosos invertebrados.', 'A vegetação era composta principalmente por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As gimnospermas dominavam muitas paisagens continentais, formando florestas abertas e comunidades adaptadas às condições sazonais. Em regiões úmidas, samambaias e outras plantas vasculares ocupavam áreas próximas a rios e lagos.', 'Os ambientes incluíam florestas abertas, planícies fluviais, desertos, lagos, regiões costeiras e mares rasos. Os sistemas fluviais eram importantes para os ecossistemas terrestres e ofereciam habitats para diferentes grupos de vertebrados. As áreas continentais apresentavam grande variedade de ambientes, desde regiões secas até áreas com vegetação mais densa.', 'Os dinossauros apresentavam diversificação crescente, incluindo formas herbívoras e carnívoras. Entre os animais conhecidos de depósitos do Noriano estão Plateosaurus e Coelophysis. Outros arcossauros, como crocodilomorfos primitivos e diferentes répteis, também ocupavam os ambientes terrestres. Nos oceanos, répteis marinhos, peixes e invertebrados continuavam diversificados.', 'O Noriano foi uma idade de grande importância para a evolução dos dinossauros. Durante esse intervalo, diferentes linhagens começaram a se diversificar e a ocupar novos ambientes. Seu nome deriva de uma antiga referência geográfica relacionada à região de Noricum, na Europa Central.'),
(65, 'rhaetiano', 'Rhaetiano', 'idade', 205.7000, 201.4000, 58, 'O Rhaetiano foi a última idade do Triássico e correspondeu aos momentos finais de um período marcado pela diversificação dos répteis e pelo surgimento dos primeiros dinossauros e mamíferos. Os ecossistemas terrestres apresentavam comunidades variadas de arcossauros, dinossauros primitivos, sinapsídeos e outros vertebrados. Nos oceanos, répteis marinhos e invertebrados continuavam ocupando diferentes nichos. A idade terminou com a extinção em massa do Triássico-Jurássico, que provocou mudanças profundas na biodiversidade global.', 'A Pangeia ainda reunia as principais massas continentais, mas processos tectônicos relacionados à futura abertura do oceano Atlântico já estavam em desenvolvimento. O oceano Panthalassa cobria grande parte do planeta e o mar de Tétis permanecia como um importante ambiente marinho. A atividade tectônica e vulcânica começou a influenciar de maneira significativa algumas regiões continentais.', 'O clima era geralmente quente e apresentava variações sazonais em muitas regiões. Próximo ao final do Rhaetiano, intensas atividades vulcânicas associadas à Província Magmática do Atlântico Central liberaram grandes quantidades de gases na atmosfera. Essas emissões contribuíram para alterações climáticas, aquecimento global, mudanças na química dos oceanos e perturbações nos ecossistemas.', 'Os oceanos abrigavam amonoides, moluscos, braquiópodes, equinodermos, peixes e diferentes grupos de répteis marinhos. As condições ambientais sofreram alterações importantes durante a crise do final do Triássico, incluindo mudanças na temperatura e na composição química das águas. Diversos organismos marinhos foram afetados pela extinção que marcou o encerramento da idade.', 'A vegetação era composta principalmente por coníferas, cicadófitas, ginkgófitas, bennettitales e samambaias. Essas plantas ocupavam diferentes regiões continentais e formavam florestas abertas e comunidades adaptadas às condições sazonais. As alterações climáticas do final do Triássico também afetaram a distribuição e a composição da vegetação.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, desertos, regiões costeiras e mares rasos. Os ecossistemas terrestres sustentavam dinossauros primitivos, outros arcossauros e diferentes vertebrados. Nos ambientes marinhos, répteis aquáticos e invertebrados ocupavam as cadeias alimentares até as perturbações ambientais do final da idade.', 'A fauna incluía dinossauros, crocodilomorfos primitivos, pterossauros, sinapsídeos e outros répteis. Os primeiros mamíferos verdadeiros já estavam presentes, representados por pequenos animais adaptados a diferentes hábitos alimentares. Nos oceanos, ictiossauros, outros répteis marinhos, peixes e invertebrados continuavam compondo comunidades diversificadas.', 'O Rhaetiano foi a última idade do Triássico e terminou há aproximadamente 201,4 milhões de anos. Seu encerramento coincidiu com a extinção em massa do Triássico-Jurássico, associada principalmente à intensa atividade vulcânica da Província Magmática do Atlântico Central. Essa crise eliminou diversos grupos de organismos e permitiu a expansão dos dinossauros durante o Jurássico.'),
(66, 'triassico', 'Triássico', 'periodo', 251.9020, 201.4000, 24, 'O Triássico foi o primeiro período da Era Mesozoica, iniciado há aproximadamente 251,9 milhões de anos e encerrado há 201,4 milhões de anos. Começou após a maior extinção em massa conhecida da história da Terra, ocorrida no final do Permiano. Durante esse período, os ecossistemas terrestres e marinhos passaram por uma recuperação gradual. Diversos grupos de répteis se diversificaram, surgiram os primeiros dinossauros e os primeiros mamíferos, e importantes transformações ambientais prepararam o cenário para a evolução da vida durante o restante do Mesozoico.', 'Durante o Triássico, praticamente todas as grandes massas continentais estavam reunidas no supercontinente Pangeia. Sua enorme extensão territorial criava grandes áreas interiores distantes da influência dos oceanos. O oceano Panthalassa ocupava a maior parte da superfície oceânica, enquanto o mar de Tétis se estendia entre regiões da Pangeia. Ao longo do período, processos tectônicos começaram a provocar fraturas no supercontinente, preparando sua fragmentação durante o Jurássico.', 'O clima do Triássico era predominantemente quente, com extensas regiões áridas e semiáridas no interior de Pangeia. A grande extensão continental favorecia fortes contrastes de temperatura e períodos de seca. Regiões costeiras e áreas próximas a rios apresentavam condições mais úmidas. Ao longo do período ocorreram variações climáticas significativas, incluindo o Episódio Pluvial Carniano, caracterizado por alterações no regime de chuvas. No final do Triássico, intensas atividades vulcânicas contribuíram para novas perturbações ambientais.', 'Os oceanos do Triássico passaram por uma recuperação gradual após a extinção do final do Permiano. O oceano Panthalassa ocupava uma grande extensão do planeta, enquanto o mar de Tétis apresentava importantes ambientes costeiros e marinhos rasos. A biodiversidade marinha aumentou progressivamente, incluindo amonoides, moluscos, peixes, corais e equinodermos. Répteis marinhos, como ictiossauros e notossauros, também se diversificaram, ocupando diferentes posições nas cadeias alimentares.', 'A vegetação terrestre era dominada principalmente por gimnospermas, incluindo coníferas, cicadófitas, ginkgófitas e outros grupos de plantas com sementes. Samambaias, licófitas e outras plantas vasculares também estavam presentes, especialmente em ambientes úmidos. A distribuição da vegetação variava conforme o clima, com florestas abertas em determinadas regiões e cobertura vegetal mais esparsa nas áreas áridas do interior continental.', 'Os ambientes terrestres incluíam desertos, planícies áridas, florestas abertas, rios, lagos, regiões pantanosas e extensas planícies aluviais. A configuração de Pangeia favorecia grandes diferenças ambientais entre o interior continental e as regiões costeiras. Nos ambientes aquáticos existiam mares rasos, plataformas continentais, recifes e oceanos profundos. Essa variedade de habitats permitiu a recuperação e a diversificação de diferentes comunidades de organismos.', 'A biodiversidade do Triássico apresentou importantes transformações após a extinção do Permiano. Nos ambientes terrestres, terápsidos, anfíbios e diferentes grupos de répteis continuaram presentes. Os arcossauros passaram por grande diversificação, originando linhagens que incluem os dinossauros, crocodilianos e pterossauros. Os primeiros dinossauros conhecidos surgiram durante o Triássico Superior, assim como os primeiros mamíferos. Nos oceanos, ictiossauros, notossauros, peixes e numerosos invertebrados formavam ecossistemas progressivamente mais complexos.', 'O Triássico marcou o início da Era Mesozoica e foi um período fundamental para a evolução dos vertebrados. Durante esse intervalo surgiram os primeiros dinossauros e mamíferos, enquanto diferentes grupos de répteis passaram a ocupar ambientes terrestres, aquáticos e aéreos. O período é dividido em três épocas: Triássico Inferior, Triássico Médio e Triássico Superior. Seu encerramento foi marcado pela extinção em massa do Triássico-Jurássico, associada principalmente à intensa atividade vulcânica da Província Magmática do Atlântico Central.'),
(67, 'jurassico', 'Jurássico', 'periodo', 201.4000, 143.1000, 24, 'O Jurássico foi o segundo período da Era Mesozoica, iniciado há aproximadamente 201,4 milhões de anos e encerrado há 143,1 milhões de anos. Durante esse intervalo, os dinossauros passaram por uma grande diversificação e se estabeleceram como componentes importantes dos ecossistemas terrestres. Grandes saurópodes, terópodes e outros grupos de dinossauros ocuparam diferentes ambientes. Também ocorreu a diversificação dos répteis marinhos, a expansão das florestas de gimnospermas e o aparecimento das primeiras aves conhecidas. O período foi marcado pela fragmentação progressiva do supercontinente Pangeia.', 'Durante o Jurássico, o supercontinente Pangeia continuou seu processo de fragmentação. As grandes massas continentais começaram a se separar em dois conjuntos principais: Laurásia, ao norte, e Gondwana, ao sul. A abertura de bacias oceânicas, incluindo regiões relacionadas à formação do oceano Atlântico, modificou gradualmente a configuração geográfica. O mar de Tétis ocupava uma importante região entre as massas continentais, enquanto o oceano Panthalassa continuava cobrindo grande parte do planeta. A separação continental criou novas regiões costeiras e influenciou a distribuição dos organismos.', 'O clima do Jurássico era predominantemente quente, embora apresentasse variações regionais e ao longo do tempo. A ausência de grandes calotas polares permanentes favorecia temperaturas relativamente elevadas em comparação com muitos intervalos mais recentes. Regiões tropicais e subtropicais apresentavam ambientes úmidos, enquanto áreas interiores continentais podiam apresentar condições áridas e sazonais. As mudanças na posição dos continentes e na circulação oceânica influenciaram a distribuição das chuvas e das temperaturas.', 'Os oceanos do Jurássico abrigavam uma grande diversidade de organismos. Amonites, belemnites, moluscos, equinodermos, peixes e tubarões ocupavam diferentes ambientes marinhos. Entre os principais predadores estavam répteis marinhos como ictiossauros, plesiossauros e pliossauros. O mar de Tétis e os oceanos em expansão contribuíam para a formação de extensas plataformas marinhas e regiões costeiras. Em determinados intervalos ocorreram mudanças na circulação e na oxigenação das águas, afetando as comunidades oceânicas.', 'A vegetação terrestre era dominada principalmente por gimnospermas, incluindo coníferas, cicadófitas, bennettitales e ginkgófitas. Samambaias e cavalinhas também eram abundantes, especialmente em regiões úmidas. Extensas florestas ocupavam diferentes áreas continentais, oferecendo alimento e abrigo para numerosos animais. As plantas com flores ainda não desempenhavam o papel dominante que alcançariam posteriormente, durante o Cretáceo.', 'Os ambientes terrestres incluíam extensas florestas, planícies aluviais, regiões pantanosas, lagos, rios, deltas e áreas áridas. As regiões próximas a sistemas fluviais apresentavam condições favoráveis à existência de grandes dinossauros herbívoros e seus predadores. Ambientes costeiros e mares rasos também eram comuns, enquanto os oceanos abrigavam comunidades diversificadas de organismos aquáticos. As transformações continentais contribuíram para a formação de novos habitats e barreiras geográficas.', 'A biodiversidade terrestre foi marcada pela expansão dos dinossauros, especialmente grandes saurópodes herbívoros, terópodes carnívoros e diferentes grupos de ornitisquianos. Entre os animais conhecidos desse período estavam Diplodocus, Apatosaurus, Brachiosaurus, Stegosaurus e Allosaurus. Pterossauros ocupavam os ambientes aéreos, enquanto pequenos mamíferos viviam em diferentes ecossistemas terrestres. O surgimento das primeiras aves conhecidas, representadas por Archaeopteryx, constituiu uma importante etapa na evolução dos dinossauros terópodes. Nos oceanos, ictiossauros, plesiossauros, pliossauros, amonites e peixes apresentavam grande diversidade.', 'O Jurássico é frequentemente associado à expansão dos grandes dinossauros saurópodes, alguns dos maiores animais terrestres que já existiram. Durante esse período também surgiu Archaeopteryx, um dos fósseis mais conhecidos para o estudo da origem das aves. A fragmentação de Pangeia modificou profundamente os ambientes terrestres e marinhos. O nome Jurássico deriva da Cordilheira do Jura, localizada na Europa, onde foram estudadas importantes formações rochosas desse intervalo.'),
(68, 'jurassico-inferior', 'Jurássico Inferior', 'epoca', 201.4000, 174.7000, 67, 'O Jurássico Inferior foi a primeira época do Jurássico e começou após a extinção em massa do final do Triássico. Durante esse intervalo, os ecossistemas terrestres passaram por uma reorganização e os dinossauros se diversificaram, ocupando diferentes ambientes e nichos ecológicos. Grandes herbívoros e predadores começaram a apresentar adaptações que se tornariam ainda mais importantes posteriormente. Nos oceanos, os répteis marinhos e os amonoides também apresentaram grande diversidade.', 'A Pangeia ainda reunia extensas massas continentais, mas sua fragmentação continuava avançando. Processos tectônicos associados à futura abertura do oceano Atlântico modificavam algumas regiões continentais. Laurásia e Gondwana começavam a apresentar separações mais evidentes, enquanto o mar de Tétis se estendia por importantes regiões marinhas. A reorganização geográfica influenciava a distribuição das áreas costeiras e dos ambientes terrestres.', 'O clima era predominantemente quente, com diferenças regionais de umidade e temperatura. Algumas áreas interiores apresentavam condições áridas ou sazonais, enquanto regiões costeiras e próximas a rios possuíam maior disponibilidade de água. Durante o Toarciano ocorreram importantes alterações ambientais, incluindo episódios de aquecimento e mudanças na química dos oceanos.', 'Os oceanos apresentavam comunidades diversificadas de amonites, belemnites, moluscos, peixes e répteis marinhos. Ictiossauros e plesiossauros ocupavam importantes posições nas cadeias alimentares. Em determinados intervalos, mudanças ambientais provocaram alterações na oxigenação das águas, especialmente durante o Evento Anóxico Oceânico do Toarciano.', 'A vegetação era composta principalmente por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As gimnospermas dominavam muitas paisagens terrestres, formando florestas e comunidades vegetais adaptadas a diferentes condições climáticas. Em regiões úmidas, samambaias e cavalinhas eram abundantes.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, pântanos, áreas costeiras e regiões áridas. Os sistemas fluviais sustentavam comunidades de dinossauros, outros répteis e pequenos mamíferos. Nos mares rasos e oceanos existiam ecossistemas diversificados, habitados por répteis marinhos, peixes e invertebrados.', 'A fauna terrestre incluía dinossauros terópodes, saurópodes primitivos, outros sauropodomorfos e diferentes grupos de ornitisquianos. Entre os animais conhecidos estavam Dilophosaurus e Scelidosaurus. Pequenos mamíferos, crocodilomorfos e pterossauros também estavam presentes. Nos oceanos, ictiossauros, plesiossauros, peixes e amonites apresentavam grande diversidade.', 'O Jurássico Inferior compreende quatro idades: Hettangiano, Sinemuriano, Pliensbachiano e Toarciano. A época começou após a extinção do Triássico-Jurássico, que transformou profundamente os ecossistemas. Um de seus principais acontecimentos ambientais foi o Evento Anóxico Oceânico do Toarciano, associado a mudanças climáticas e a alterações nos organismos marinhos.'),
(69, 'jurassico-medio', 'Jurássico Médio', 'epoca', 174.7000, 161.5000, 67, 'O Jurássico Médio foi a segunda época do Jurássico e correspondeu a uma fase de importante diversificação dos dinossauros e de outros organismos terrestres e marinhos. Os saurópodes desenvolveram formas corporais cada vez maiores e diferentes linhagens de terópodes se diversificaram. Os ecossistemas terrestres apresentavam florestas de gimnospermas, enquanto os oceanos sustentavam comunidades abundantes de invertebrados, peixes e répteis marinhos.', 'A fragmentação de Pangeia continuava, com a separação gradual entre Laurásia e Gondwana. Novas bacias oceânicas e regiões costeiras começaram a se desenvolver, enquanto o mar de Tétis permanecia como uma importante região de circulação marinha. Os continentes ainda estavam muito diferentes de suas posições atuais, mas as mudanças tectônicas contribuíam para a formação de novos ambientes.', 'O clima era predominantemente quente, com variações regionais de temperatura e precipitação. Muitas regiões apresentavam condições favoráveis ao desenvolvimento de extensas florestas, enquanto outras possuíam ambientes mais secos. As mudanças na configuração continental influenciavam os padrões de circulação atmosférica e oceânica.', 'Os mares apresentavam diversidade de amonites, belemnites, braquiópodes, moluscos, corais e equinodermos. Répteis marinhos, incluindo plesiossauros, pliossauros e ictiossauros, ocupavam diferentes nichos ecológicos. As plataformas marinhas rasas eram importantes para a formação de depósitos fossilíferos e para a manutenção de comunidades diversas.', 'A vegetação terrestre continuava dominada por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As florestas ocupavam extensas regiões, especialmente em ambientes úmidos. Diferentes espécies vegetais forneciam alimento para os grandes dinossauros herbívoros e contribuíam para a estrutura dos ecossistemas.', 'Os ambientes incluíam florestas, planícies aluviais, sistemas fluviais, lagos, pântanos, regiões costeiras e mares rasos. As planícies vegetadas ofereciam recursos alimentares para dinossauros herbívoros de diferentes tamanhos. Os ambientes marinhos apresentavam recifes, fundos sedimentares e regiões oceânicas habitadas por numerosos organismos.', 'A fauna terrestre incluía saurópodes, terópodes e dinossauros ornitisquianos. Alguns saurópodes, como Cetiosaurus, são conhecidos de depósitos dessa época. Também existiam pterossauros, crocodilomorfos e pequenos mamíferos. Nos oceanos, plesiossauros, pliossauros, ictiossauros, peixes e numerosos invertebrados apresentavam grande diversidade.', 'O Jurássico Médio compreende quatro idades: Aaleniano, Bajociano, Bathoniano e Calloviano. Essa época foi importante para a evolução dos grandes dinossauros saurópodes e para a diversificação dos ecossistemas marinhos. Muitos depósitos fossilíferos desse intervalo preservam amonites e répteis marinhos utilizados em estudos paleontológicos.'),
(70, 'jurassico-superior', 'Jurássico Superior', 'epoca', 161.5000, 143.1000, 67, 'O Jurássico Superior foi a última época do Jurássico e ficou marcado pela presença de alguns dos maiores dinossauros terrestres conhecidos. Grandes saurópodes, como Diplodocus, Apatosaurus e Brachiosaurus, habitavam diferentes regiões, convivendo com predadores como Allosaurus. Também ocorreu o aparecimento de Archaeopteryx, um dos fósseis mais importantes para o estudo da origem das aves. Os ambientes marinhos continuavam apresentando grande diversidade de répteis, peixes e invertebrados.', 'A separação dos continentes continuava avançando. Laurásia e Gondwana estavam progressivamente mais diferenciadas, enquanto o oceano Atlântico começava a se expandir em algumas regiões. O mar de Tétis permanecia como uma importante área oceânica, conectando diferentes ambientes marinhos. Essas mudanças geográficas influenciavam a distribuição dos organismos e a formação de novos habitats.', 'O clima era geralmente quente, com diferenças regionais na distribuição das chuvas. Extensas florestas ocupavam regiões úmidas, enquanto planícies abertas e ambientes sazonais estavam presentes em outras áreas. As temperaturas relativamente elevadas contribuíam para a existência de ecossistemas diversificados em diferentes latitudes.', 'Os oceanos abrigavam amonites, belemnites, moluscos, corais, peixes, tubarões e diferentes grupos de répteis marinhos. Plesiossauros, pliossauros e ictiossauros ocupavam importantes posições ecológicas. Mares rasos e plataformas continentais apresentavam grande diversidade biológica, enquanto determinados ambientes sedimentares ofereciam condições excepcionais para a preservação de fósseis.', 'A vegetação era composta principalmente por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. Extensas florestas forneciam alimento para grandes herbívoros, especialmente saurópodes. Plantas de menor porte ocupavam regiões úmidas, margens de rios e áreas abertas, compondo diferentes comunidades vegetais.', 'Os ambientes incluíam florestas, planícies aluviais, rios, lagos, pântanos, regiões costeiras e mares rasos. Em algumas áreas da atual América do Norte, grandes planícies fluviais sustentavam comunidades de saurópodes, estegossauros e terópodes. Ambientes lagunares e costeiros de determinadas regiões europeias apresentavam condições favoráveis à preservação de organismos delicados.', 'A biodiversidade terrestre incluía grandes saurópodes, como Diplodocus, Apatosaurus e Brachiosaurus, além de terópodes como Allosaurus e ornitisquianos como Stegosaurus. Pterossauros, crocodilomorfos e pequenos mamíferos também estavam presentes. Archaeopteryx representa um importante registro de dinossauros avianos primitivos. Nos oceanos existiam plesiossauros, pliossauros, ictiossauros, amonites e diversos peixes.', 'O Jurássico Superior compreende três idades: Oxfordiano, Kimmeridgiano e Tithoniano. É conhecido pelos grandes dinossauros encontrados em formações como Morrison, na América do Norte. Também abriga os fósseis de Archaeopteryx preservados em depósitos calcários da região de Solnhofen, na Alemanha, que apresentam detalhes anatômicos importantes para compreender a evolução das aves.'),
(71, 'hettangiano', 'Hettangiano', 'idade', 201.4000, 199.5000, 68, 'O Hettangiano foi a primeira idade do Jurássico e começou após a extinção em massa que encerrou o Triássico. Durante esse intervalo, os ecossistemas terrestres e marinhos passaram por uma reorganização. Os dinossauros sobreviventes continuaram sua evolução e diferentes grupos de organismos começaram a ocupar os nichos ecológicos disponíveis.', 'A Pangeia ainda reunia extensas massas continentais, embora processos tectônicos relacionados à sua fragmentação já estivessem em desenvolvimento. O mar de Tétis e o oceano Panthalassa continuavam sendo importantes componentes geográficos.', 'O clima era predominantemente quente e apresentava variações regionais de umidade. As condições ambientais ainda refletiam as perturbações ocorridas na transição entre o Triássico e o Jurássico.', 'Os oceanos começaram a apresentar uma recuperação gradual após a extinção do final do Triássico. Amonites, moluscos, peixes e diferentes répteis marinhos ocupavam os ambientes aquáticos.', 'A vegetação era dominada por coníferas, cicadófitas, ginkgófitas e samambaias. Essas plantas ocupavam diferentes regiões, especialmente ambientes úmidos próximos a rios e lagos.', 'Os ambientes incluíam planícies fluviais, regiões costeiras, lagos, áreas florestais e zonas mais áridas. Os mares rasos também ofereciam habitats para diversas comunidades marinhas.', 'A fauna terrestre incluía dinossauros, outros répteis, anfíbios e pequenos mamíferos primitivos. Nos oceanos, amonites, peixes e répteis marinhos continuavam presentes.', 'O Hettangiano marca o início oficial do Jurássico. Seu limite inferior está associado à reorganização biológica posterior à extinção em massa do Triássico-Jurássico.'),
(72, 'sinemuriano', 'Sinemuriano', 'idade', 199.5000, 192.9000, 68, 'O Sinemuriano foi a segunda idade do Jurássico Inferior e apresentou uma diversificação crescente dos ecossistemas terrestres e marinhos. Dinossauros de diferentes grupos ocuparam ambientes continentais, enquanto amonites e répteis marinhos continuaram sua expansão nos oceanos.', 'A fragmentação inicial de Pangeia continuava, embora as massas continentais ainda permanecessem relativamente próximas. O mar de Tétis e outras regiões oceânicas influenciavam os ambientes costeiros.', 'O clima era geralmente quente, com diferenças regionais entre ambientes úmidos e áreas mais secas. Essas condições favoreciam a existência de diferentes comunidades vegetais e animais.', 'Os oceanos abrigavam amonites, belemnites, peixes e répteis marinhos. As plataformas marinhas rasas apresentavam comunidades diversificadas de invertebrados.', 'Coníferas, cicadófitas, ginkgófitas e samambaias compunham a vegetação. As florestas ocupavam regiões úmidas, enquanto comunidades mais abertas estavam presentes em áreas sazonais.', 'Os ambientes incluíam florestas, rios, lagos, planícies aluviais, regiões costeiras e mares rasos. A diversidade de habitats favorecia diferentes grupos de vertebrados.', 'A fauna incluía dinossauros terópodes e herbívoros, crocodilomorfos, pequenos mamíferos e pterossauros. Nos oceanos viviam ictiossauros, plesiossauros primitivos, peixes e amonites.', 'O Sinemuriano recebeu seu nome de uma localidade da França. Seus depósitos fossilíferos incluem importantes registros de amonites, utilizados para reconhecer e correlacionar rochas dessa idade.'),
(73, 'pliensbachiano', 'Pliensbachiano', 'idade', 192.9000, 184.2000, 68, 'O Pliensbachiano foi a terceira idade do Jurássico Inferior e caracterizou-se pela continuidade da diversificação dos organismos terrestres e marinhos. Os dinossauros passaram a ocupar diferentes nichos ecológicos, enquanto os oceanos apresentavam comunidades abundantes de amonites e répteis marinhos.', 'Pangeia continuava seu processo gradual de fragmentação. Laurásia e Gondwana começavam a apresentar mudanças geográficas, embora ainda permanecessem conectadas em diferentes regiões.', 'O clima era predominantemente quente, mas apresentava oscilações e diferenças regionais. Ambientes úmidos coexistiam com regiões mais secas e sazonais.', 'Os mares abrigavam amonites, belemnites, moluscos, peixes e répteis marinhos. Ictiossauros e plesiossauros estavam entre os vertebrados aquáticos mais característicos.', 'A vegetação incluía coníferas, cicadófitas, ginkgófitas, samambaias e cavalinhas. Essas plantas formavam comunidades florestais e vegetação de menor porte em ambientes úmidos.', 'Os ambientes incluíam florestas, planícies fluviais, regiões pantanosas, lagos e mares rasos. A disponibilidade de água influenciava a distribuição dos organismos terrestres.', 'Dinossauros terópodes, saurópodes primitivos e outros herbívoros estavam presentes. Pterossauros, pequenos mamíferos e diferentes répteis também ocupavam os ecossistemas. Nos mares existiam ictiossauros, plesiossauros e numerosos invertebrados.', 'O Pliensbachiano é conhecido por importantes depósitos marinhos fossilíferos, especialmente na Europa. As amonites desse intervalo são utilizadas como fósseis-guia em estudos de estratigrafia.'),
(74, 'toarciano', 'Toarciano', 'idade', 184.2000, 174.7000, 68, 'O Toarciano foi a última idade do Jurássico Inferior e ficou marcado por importantes mudanças ambientais nos oceanos. Durante esse intervalo ocorreu um episódio de redução da oxigenação das águas, conhecido como Evento Anóxico Oceânico do Toarciano. Apesar das perturbações, os ecossistemas terrestres e marinhos continuaram apresentando diferentes grupos de animais e plantas.', 'A Pangeia continuava em processo de fragmentação, com o desenvolvimento de bacias sedimentares e mudanças nas regiões costeiras. O mar de Tétis permanecia como uma importante região oceânica.', 'O clima apresentou episódios de aquecimento global e alterações no ciclo do carbono. Essas mudanças contribuíram para perturbações ambientais que afetaram diferentes organismos marinhos.', 'Os oceanos passaram por episódios de anoxia, caracterizados pela redução do oxigênio dissolvido na água. Essas condições afetaram diferentes comunidades marinhas e favoreceram a preservação de sedimentos ricos em matéria orgânica.', 'A vegetação terrestre era formada por coníferas, cicadófitas, ginkgófitas e samambaias. As comunidades vegetais variavam conforme a umidade e as mudanças climáticas.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, regiões costeiras e plataformas marinhas. Algumas bacias oceânicas apresentavam condições ambientais desfavoráveis à vida durante episódios de anoxia.', 'A fauna incluía dinossauros terrestres, pterossauros, pequenos mamíferos, ictiossauros, plesiossauros, peixes e amonites. Determinados grupos marinhos foram afetados pelas mudanças ambientais.', 'O Toarciano é especialmente conhecido pelo Evento Anóxico Oceânico do Toarciano, associado a alterações climáticas e à redução do oxigênio nos oceanos. Seus depósitos sedimentares são importantes para estudos das mudanças ambientais do Jurássico.'),
(75, 'aaleniano', 'Aaleniano', 'idade', 174.7000, 170.9000, 69, 'O Aaleniano foi a primeira idade do Jurássico Médio e correspondeu a uma etapa de diversificação dos dinossauros e de diferentes organismos marinhos. Os ecossistemas terrestres apresentavam comunidades vegetais desenvolvidas, enquanto os mares abrigavam abundantes amonites e outros invertebrados.', 'A fragmentação de Pangeia continuava avançando, com mudanças nas regiões continentais e costeiras. Laurásia e Gondwana apresentavam uma separação progressiva.', 'O clima era geralmente quente, com diferenças regionais de umidade. Muitas regiões apresentavam condições favoráveis ao desenvolvimento de florestas e comunidades vegetais diversificadas.', 'Os mares abrigavam amonites, belemnites, moluscos, equinodermos, peixes e répteis marinhos. As plataformas marinhas rasas eram importantes para a biodiversidade.', 'Coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias compunham a vegetação. As gimnospermas permaneciam dominantes nos ambientes terrestres.', 'Os ambientes incluíam florestas, rios, planícies aluviais, lagos, regiões costeiras e mares rasos. Diferentes paisagens sustentavam comunidades de vertebrados e invertebrados.', 'A fauna terrestre incluía dinossauros herbívoros e carnívoros, pterossauros e pequenos mamíferos. Nos oceanos existiam plesiossauros, ictiossauros, peixes e numerosos invertebrados.', 'O Aaleniano recebeu seu nome da cidade de Aalen, na Alemanha. Seus depósitos apresentam importantes registros de amonites, utilizados na identificação e correlação das camadas geológicas.'),
(76, 'bajociano', 'Bajociano', 'idade', 170.9000, 168.2000, 69, 'O Bajociano foi a segunda idade do Jurássico Médio e apresentou ecossistemas terrestres e marinhos diversificados. Os dinossauros continuaram evoluindo, enquanto os oceanos eram habitados por numerosas espécies de amonites, peixes e répteis marinhos.', 'A separação progressiva das massas continentais continuava modificando a configuração geográfica. O mar de Tétis e as bacias oceânicas em desenvolvimento influenciavam os ambientes marinhos.', 'O clima era predominantemente quente, com variações regionais de temperatura e precipitação. Ambientes úmidos e florestais coexistiam com regiões mais secas.', 'Os oceanos apresentavam comunidades diversificadas de amonites, belemnites, moluscos, corais, equinodermos e peixes. Plesiossauros e outros répteis marinhos também estavam presentes.', 'A vegetação terrestre era dominada por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. Florestas e comunidades vegetais abertas ocupavam diferentes regiões.', 'Os ambientes incluíam florestas, planícies aluviais, lagos, regiões costeiras, mares rasos e plataformas continentais. Os habitats aquáticos e terrestres sustentavam diferentes grupos de organismos.', 'A fauna incluía dinossauros saurópodes, terópodes e ornitisquianos, além de pterossauros, crocodilomorfos e pequenos mamíferos. Nos oceanos viviam peixes, amonites e répteis marinhos.', 'O Bajociano possui importantes registros fossilíferos utilizados em estudos da evolução marinha. Seu nome está relacionado à cidade francesa de Bayeux, conhecida historicamente pelo nome latino Bajocae.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(77, 'bathoniano', 'Bathoniano', 'idade', 168.2000, 165.3000, 69, 'O Bathoniano foi a terceira idade do Jurássico Médio e apresentou uma importante diversidade de vertebrados terrestres e organismos marinhos. Dinossauros saurópodes e terópodes ocupavam diferentes ambientes, enquanto os ecossistemas oceânicos continuavam apresentando répteis marinhos, peixes e invertebrados.', 'Os continentes continuavam se separando gradualmente, com o desenvolvimento de novas regiões costeiras e bacias sedimentares. Laurásia e Gondwana apresentavam mudanças em sua configuração.', 'O clima era geralmente quente, com diferenças regionais de umidade. Condições favoráveis ao crescimento da vegetação estavam presentes em diversas regiões continentais.', 'Os mares apresentavam grande diversidade de amonites, belemnites, moluscos, peixes e répteis marinhos. Plataformas continentais e mares rasos sustentavam comunidades abundantes.', 'A vegetação era composta principalmente por coníferas, cicadófitas, ginkgófitas, bennettitales e samambaias. As florestas ofereciam recursos alimentares para grandes dinossauros herbívoros.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, pântanos, regiões costeiras e mares rasos. Diferentes grupos de animais ocupavam nichos ecológicos variados.', 'Entre os animais terrestres estavam dinossauros saurópodes, terópodes, ornitisquianos, pterossauros e pequenos mamíferos. Cetiosaurus é um exemplo de saurópode conhecido de depósitos do Jurássico Médio. Os oceanos abrigavam plesiossauros, peixes e invertebrados.', 'O Bathoniano recebeu seu nome de Bath, na Inglaterra. Seus depósitos incluem importantes fósseis de dinossauros e organismos marinhos, contribuindo para a compreensão dos ecossistemas do Jurássico Médio.'),
(78, 'calloviano', 'Calloviano', 'idade', 165.3000, 161.5000, 69, 'O Calloviano foi a última idade do Jurássico Médio e apresentou comunidades terrestres e marinhas bastante diversificadas. Grandes dinossauros herbívoros e predadores ocupavam os continentes, enquanto os oceanos abrigavam répteis marinhos de grande porte, incluindo pliossauros.', 'A fragmentação continental continuava, contribuindo para a expansão de bacias sedimentares e ambientes costeiros. Laurásia e Gondwana estavam progressivamente mais diferenciadas.', 'O clima era predominantemente quente, embora apresentasse variações regionais. Florestas ocupavam diferentes regiões, enquanto áreas sazonais e mais secas também estavam presentes.', 'Os oceanos apresentavam grande diversidade de amonites, belemnites, peixes, tubarões e répteis marinhos. Plesiossauros e pliossauros ocupavam importantes posições nas cadeias alimentares.', 'A vegetação incluía coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As gimnospermas dominavam grande parte das comunidades vegetais terrestres.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, regiões costeiras e mares rasos. Depósitos sedimentares marinhos preservaram importantes registros fossilíferos dessa idade.', 'A fauna terrestre incluía saurópodes, terópodes, outros dinossauros, pterossauros e pequenos mamíferos. Nos mares viviam plesiossauros, pliossauros, ictiossauros, peixes e amonites.', 'O Calloviano é conhecido por importantes depósitos fossilíferos, incluindo sedimentos da Formação Oxford Clay, na Inglaterra. Esses depósitos preservam uma grande diversidade de organismos marinhos, incluindo répteis de grande porte.'),
(79, 'oxfordiano', 'Oxfordiano', 'idade', 161.5000, 154.8000, 70, 'O Oxfordiano foi a primeira idade do Jurássico Superior e marcou uma etapa de diversificação dos grandes dinossauros e de outros organismos terrestres e marinhos. Os saurópodes continuaram evoluindo e os ecossistemas marinhos apresentavam abundantes amonites, répteis aquáticos e comunidades associadas a mares rasos.', 'A separação continental continuava avançando, enquanto novas bacias oceânicas e regiões costeiras se desenvolviam. O mar de Tétis permanecia como uma importante região marinha.', 'O clima era predominantemente quente, com diferenças regionais de temperatura e umidade. Regiões florestais e planícies abertas estavam presentes em diferentes continentes.', 'Os oceanos apresentavam amonites, belemnites, moluscos, corais, peixes e répteis marinhos. Recifes e plataformas carbonáticas se desenvolveram em diferentes regiões.', 'A vegetação era composta por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As florestas forneciam alimento e abrigo para diferentes animais.', 'Os ambientes incluíam florestas, planícies fluviais, lagos, regiões costeiras, mares rasos e recifes. A diversidade de habitats favorecia diferentes comunidades ecológicas.', 'A fauna terrestre incluía saurópodes, terópodes e dinossauros ornitisquianos, além de pterossauros e pequenos mamíferos. Nos oceanos, plesiossauros, pliossauros, peixes e invertebrados continuavam diversificados.', 'O Oxfordiano recebeu seu nome da cidade de Oxford, na Inglaterra. Seus depósitos são importantes para o estudo de ambientes marinhos e das transformações que ocorreram no início do Jurássico Superior.'),
(80, 'kimmeridgiano', 'Kimmeridgiano', 'idade', 154.8000, 149.2000, 70, 'O Kimmeridgiano foi a segunda idade do Jurássico Superior e ficou marcado pela presença de grandes dinossauros saurópodes, terópodes e ornitisquianos. Em diferentes regiões, extensas planícies fluviais sustentavam comunidades de herbívoros de grande porte e seus predadores. Os oceanos continuavam apresentando rica biodiversidade.', 'A fragmentação de Pangeia continuava, com o afastamento progressivo de diferentes massas continentais. O desenvolvimento de novas bacias oceânicas modificava os ambientes costeiros e as rotas de circulação marinha.', 'O clima era geralmente quente, com diferenças regionais de umidade e sazonalidade. Áreas florestais coexistiam com planícies abertas e regiões de condições mais secas.', 'Os mares abrigavam amonites, belemnites, peixes, tubarões, plesiossauros, pliossauros e ictiossauros. Algumas bacias sedimentares acumularam grande quantidade de matéria orgânica, formando depósitos geológicos importantes.', 'A vegetação era dominada por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. As florestas ofereciam recursos alimentares para grandes dinossauros herbívoros.', 'Os ambientes incluíam florestas, planícies aluviais, rios, lagos, regiões costeiras e mares rasos. Em determinadas regiões da América do Norte existiam extensos sistemas fluviais associados à Formação Morrison.', 'Entre os animais conhecidos estavam grandes saurópodes, terópodes e ornitisquianos, incluindo linhagens representadas por Apatosaurus, Diplodocus, Allosaurus e Stegosaurus. Pterossauros, pequenos mamíferos e crocodilomorfos também estavam presentes. Os oceanos abrigavam répteis marinhos e numerosos invertebrados.', 'O Kimmeridgiano recebeu seu nome da região de Kimmeridge, na Inglaterra. É conhecido por importantes depósitos sedimentares marinhos ricos em matéria orgânica e por registros fossilíferos de grandes dinossauros do Jurássico Superior.'),
(81, 'tithoniano', 'Tithoniano', 'idade', 149.2000, 143.1000, 70, 'O Tithoniano foi a última idade do Jurássico e correspondeu aos momentos finais de um período marcado pela diversificação dos grandes dinossauros. Os ecossistemas terrestres abrigavam saurópodes gigantes, terópodes e diferentes herbívoros. Também são conhecidos fósseis de Archaeopteryx, importantes para compreender a evolução inicial das aves.', 'A fragmentação continental continuava modificando a configuração geográfica do planeta. Laurásia e Gondwana estavam progressivamente mais separadas, enquanto novas bacias oceânicas se desenvolviam.', 'O clima era predominantemente quente, com variações regionais na distribuição das chuvas. Ambientes florestais coexistiam com planícies abertas, regiões úmidas e áreas sazonais.', 'Os oceanos apresentavam diversidade de amonites, belemnites, peixes, tubarões e répteis marinhos. Ambientes costeiros e lagunares também estavam presentes, alguns oferecendo condições excepcionais de fossilização.', 'A vegetação era composta principalmente por coníferas, cicadófitas, bennettitales, ginkgófitas e samambaias. Essas plantas dominavam os ambientes terrestres e sustentavam grandes comunidades de herbívoros.', 'Os ambientes incluíam florestas, planícies fluviais, rios, lagos, regiões costeiras, lagoas e mares rasos. Ambientes lagunares de determinadas regiões europeias favoreceram a preservação de fósseis delicados.', 'A fauna incluía grandes saurópodes, terópodes, ornitisquianos, pterossauros, crocodilomorfos e pequenos mamíferos. Archaeopteryx está entre os organismos mais conhecidos desse intervalo. Nos oceanos existiam plesiossauros, ictiossauros, peixes e numerosos invertebrados.', 'O Tithoniano foi a última idade do Jurássico e antecedeu o início do Cretáceo. Um de seus registros mais conhecidos é Archaeopteryx, encontrado em depósitos calcários da região de Solnhofen, na Alemanha. Esses fósseis preservam características anatômicas fundamentais para o estudo da origem das aves.'),
(82, 'paleogeno', 'Paleógeno', 'periodo', 66.0000, 23.0300, 25, 'O Paleógeno foi o primeiro período da Era Cenozoica, entre aproximadamente 66 e 23,03 milhões de anos atrás. Começou após a extinção que eliminou os dinossauros não avianos e testemunhou a diversificação dos mamíferos, das aves e das plantas com flores. Abrange as épocas Paleoceno, Eoceno e Oligoceno, marcadas por uma transição de condições predominantemente quentes para o resfriamento global.', 'Os continentes já estavam bastante separados após a fragmentação de Gondwana, mas continuaram se deslocando. A Índia aproximou-se da Ásia e iniciou sua colisão, enquanto a África avançava em direção à Eurásia. As conexões oceânicas em torno da Antártida mudaram progressivamente, influenciando a circulação marinha e o clima.', 'O Paleoceno e o início do Eoceno apresentaram condições globalmente quentes, com florestas chegando a altas latitudes. O Máximo Térmico do Paleoceno-Eoceno foi um episódio de aquecimento abrupto. A partir do Eoceno, o resfriamento tornou-se mais pronunciado e culminou na expansão de grandes geleiras antárticas perto de 33,9 milhões de anos atrás.', 'Os oceanos abrigavam peixes, tubarões, moluscos, corais e numerosos grupos de plâncton. Cetáceos surgiram e se diversificaram durante o Eoceno, passando a ocupar ambientes costeiros e oceânicos. Mudanças na abertura de passagens marítimas, na circulação das correntes e na temperatura das águas transformaram gradualmente os ecossistemas marinhos.', 'As angiospermas já formavam grande parte das florestas, acompanhadas por coníferas, samambaias e outras plantas. No início, florestas tropicais e subtropicais estendiam-se a latitudes elevadas. Com o resfriamento progressivo, diferentes comunidades vegetais se reorganizaram, e ecossistemas mais abertos passaram a ocupar algumas regiões.', 'Os ambientes incluíam florestas tropicais e temperadas, planícies de inundação, rios, pântanos, lagos, áreas costeiras e mares rasos. A variedade dos habitats favoreceu a evolução de mamíferos terrestres e de organismos marinhos. No Oligoceno, condições mais frias e secas afetaram parte dos continentes.', 'Após a extinção do final do Cretáceo, mamíferos e aves expandiram-se em inúmeros nichos ecológicos. Surgiram ou se diversificaram linhagens de primatas, perissodáctilos, artiodáctilos, carnívoros e cetáceos. Nos oceanos também ocorreram grandes transformações no plâncton, nos peixes e nos mamíferos marinhos.', 'O Paleógeno começa imediatamente após a extinção do Cretáceo-Paleógeno. Entre seus acontecimentos mais importantes estão o Máximo Térmico do Paleoceno-Eoceno e a transição Eoceno-Oligoceno, quando grandes mantos de gelo se desenvolveram na Antártida. Seu nome significa aproximadamente origem recente, em referência à história geológica da era.'),
(83, 'neogeno', 'Neógeno', 'periodo', 23.0300, 2.5800, 25, 'O Neógeno foi o segundo período da Era Cenozoica, entre aproximadamente 23,03 e 2,58 milhões de anos atrás. Inclui as épocas Mioceno e Plioceno e foi marcado pela diversificação de mamíferos e aves, pela expansão de campos e savanas e por mudanças importantes nas correntes oceânicas. Ao longo do período, muitos ecossistemas passaram a adquirir características próximas das atuais.', 'Os continentes aproximaram-se gradualmente de suas posições modernas. A elevação dos Andes e do Himalaia e as mudanças nas conexões entre África, Eurásia e Américas alteraram paisagens e rotas de dispersão. A configuração da região do istmo do Panamá e das passagens marítimas mudou ao longo do Neógeno, influenciando a circulação oceânica.', 'O início do Mioceno foi relativamente ameno, com um importante intervalo de aquecimento no Mioceno Médio. Depois ocorreu uma tendência de resfriamento e ampliação de condições mais secas em diversas regiões. No Plioceno, o clima ainda apresentou fases quentes, mas as glaciações do Hemisfério Norte se intensificaram perto do final do período.', 'Os oceanos apresentaram mudanças na circulação e na distribuição da temperatura e dos nutrientes. Baleias, golfinhos, focas, tubarões e peixes diversificaram-se em diferentes regiões. A Crise de Salinidade Messiniana afetou profundamente o Mediterrâneo no final do Mioceno, antes do restabelecimento da conexão com o Atlântico.', 'As plantas com flores dominavam a maior parte dos ecossistemas terrestres. Gramíneas e outras plantas adaptadas a habitats abertos expandiram-se em várias regiões, com desenvolvimento de pradarias, estepes e savanas. Florestas tropicais e temperadas continuaram importantes e tiveram sua distribuição modificada pelo clima.', 'Os ambientes incluíam grandes florestas, savanas, pradarias, desertos, montanhas, planícies fluviais, rios, lagos e mares costeiros. A expansão de áreas abertas criou novos habitats para herbívoros corredores e seus predadores. Barreiras montanhosas e corredores terrestres também influenciaram a distribuição das espécies.', 'Diversificaram-se cavalos, proboscídeos, ruminantes, felinos, canídeos, primatas e numerosos outros mamíferos. Os hominínios mais antigos conhecidos surgiram durante o Neógeno, assim como representantes iniciais do gênero Homo perto do final do Plioceno. Aves e mamíferos marinhos também adquiriram grande diversidade.', 'O Neógeno registra a expansão de muitos ecossistemas campestres modernos e importantes etapas da evolução humana. A Crise de Salinidade Messiniana e as mudanças climáticas do Plioceno são eventos especialmente conhecidos. O período terminou com o início do Quaternário e a intensificação dos ciclos glaciais.'),
(84, 'paleoceno', 'Paleoceno', 'epoca', 66.0000, 56.0000, 82, 'O Paleoceno foi a primeira época do Paleógeno, entre 66 e 56 milhões de anos atrás. Começou após a extinção do final do Cretáceo e foi marcado pela reorganização dos ecossistemas. Mamíferos e aves se diversificaram em ambientes onde os dinossauros não avianos já não estavam presentes.', 'Os continentes prosseguiam em sua separação, com a América do Sul relativamente isolada e a Índia movendo-se em direção à Ásia. O Atlântico continuava se alargando, enquanto o mar de Tétis ocupava áreas entre a África e a Eurásia.', 'As temperaturas globais eram relativamente elevadas, e florestas podiam ocorrer em altas latitudes. Perto do limite com o Eoceno, um aumento muito rápido da temperatura marcou o Máximo Térmico do Paleoceno-Eoceno.', 'Oceanos quentes abrigavam peixes, tubarões, moluscos e micro-organismos planctônicos. Comunidades marinhas se recuperavam da extinção do Cretáceo e passavam por nova diversificação.', 'Florestas de plantas com flores e coníferas ocupavam extensas áreas. Samambaias e outras plantas cresciam em ambientes úmidos, e as comunidades vegetais reorganizaram-se depois da extinção do Cretáceo.', 'Existiam florestas quentes, planícies aluviais, pântanos, lagos, rios e áreas costeiras. Esses habitats favoreciam pequenos e médios mamíferos, aves e outros vertebrados.', 'Mamíferos placentários, marsupiais e outras linhagens se diversificaram, incluindo formas herbívoras, insetívoras e predadoras. Aves terrestres e aquáticas também ganharam importância ecológica.', 'O Paleoceno compreende as idades Daniano, Selandiano e Thanetiano. Seu encerramento coincide com o início do Máximo Térmico do Paleoceno-Eoceno, um evento importante para o estudo das mudanças climáticas rápidas.'),
(85, 'eoceno', 'Eoceno', 'epoca', 56.0000, 33.9000, 82, 'O Eoceno foi a segunda época do Paleógeno, entre aproximadamente 56 e 33,9 milhões de anos atrás. Apresentou um início muito quente, seguido por resfriamento gradual. Durante essa época diversificaram-se diversos grupos modernos de mamíferos, surgiram os primeiros cetáceos e muitos ecossistemas florestais se expandiram.', 'A Índia aproximou-se e colidiu com a Ásia, favorecendo a evolução de grandes cadeias montanhosas. A África continuou seu deslocamento para o norte, e a Antártida passou por transformações em suas conexões oceânicas.', 'O Eoceno começou com intenso aquecimento no Máximo Térmico do Paleoceno-Eoceno e apresentou um ótimo climático no início da época. Posteriormente, uma tendência geral de resfriamento alterou a distribuição das florestas e os ecossistemas de altas latitudes.', 'Os mares abrigavam peixes, tubarões, moluscos, corais e cetáceos primitivos. Baleias passaram de ancestrais terrestres a formas adaptadas ao ambiente aquático. Alterações na temperatura e nas correntes influenciaram os ecossistemas costeiros e oceânicos.', 'Florestas tropicais e subtropicais de angiospermas eram extensas, acompanhadas por coníferas e samambaias. À medida que o clima esfriou, florestas temperadas ganharam espaço em algumas regiões.', 'Os habitats incluíam florestas densas, rios, lagos, pântanos, planícies costeiras e ambientes marinhos. Paisagens fluviais e lacustres preservaram fósseis importantes de mamíferos e répteis.', 'Diversificaram-se primatas, cavalos primitivos, rinocerontes antigos, morcegos, carnívoros e cetáceos. Também existiam crocodilianos, tartarugas, aves de grande porte e numerosos peixes.', 'O Eoceno compreende Ypresiano, Lutetiano, Bartoniano e Priaboniano. Durante essa época ocorreram etapas fundamentais da evolução das baleias. Seu final antecede a formação de um grande manto de gelo na Antártida na transição Eoceno-Oligoceno.'),
(86, 'oligoceno', 'Oligoceno', 'epoca', 33.9000, 23.0300, 82, 'O Oligoceno foi a última época do Paleógeno, entre aproximadamente 33,9 e 23,03 milhões de anos atrás. Seu início foi marcado por forte resfriamento global e pela expansão de mantos de gelo na Antártida. Os ecossistemas terrestres e marinhos se reorganizaram e vários grupos de mamíferos se diversificaram.', 'Os continentes continuaram em direção às posições atuais. Mudanças nas passagens oceânicas ao redor da Antártida influenciaram a circulação global, enquanto a Índia e a Ásia permaneceram em processo de reorganização tectônica.', 'O clima tornou-se mais frio do que durante grande parte do Eoceno. A glaciação antártica e oscilações no nível do mar afetaram os ambientes costeiros. Em várias áreas continentais, a aridez se intensificou.', 'Os oceanos experimentaram alterações nas correntes, na temperatura e nos nutrientes. Baleias com barbatanas e cetáceos dentados passaram por importantes etapas evolutivas, acompanhados por peixes, tubarões e muitos invertebrados.', 'Florestas tropicais recuaram em parte das regiões, enquanto formações temperadas e vegetação aberta passaram a ganhar espaço. As angiospermas continuavam dominantes em muitos ambientes.', 'Os ambientes incluíam florestas, planícies abertas, estepes incipientes, rios, lagos e mares costeiros. O resfriamento e a maior sazonalidade influenciaram a distribuição da fauna.', 'Entre os mamíferos estavam rinocerontes primitivos, parentes antigos de cavalos, artiodáctilos, carnívoros e primatas. Os cetáceos se diversificaram nos mares, enquanto aves e répteis continuaram ocupando diferentes habitats.', 'O Oligoceno compreende Rupeliano e Chattiano. Sua transição inicial é marcada pelo desenvolvimento de extensos mantos de gelo na Antártida, um dos acontecimentos climáticos mais importantes do Cenozoico.'),
(87, 'mioceno', 'Mioceno', 'epoca', 23.0300, 5.3330, 83, 'O Mioceno foi a primeira época do Neógeno, entre aproximadamente 23,03 e 5,333 milhões de anos atrás. Testemunhou a diversificação de mamíferos, a expansão de gramíneas e habitats abertos e importantes transformações tectônicas e climáticas. Diversas linhagens de primatas e de mamíferos modernos evoluíram durante essa época.', 'O relevo de grandes cadeias montanhosas, como Andes e Himalaia, continuou se transformando. A aproximação entre África e Eurásia modificou as conexões terrestres e marinhas, permitindo dispersões de organismos.', 'Depois de fases relativamente amenas e de um ótimo climático no Mioceno Médio, ocorreu resfriamento global e ampliação de condições sazonais ou secas em numerosas regiões. A expansão de campos variou conforme a latitude e o continente.', 'Os oceanos abrigavam baleias, golfinhos, focas, tubarões, peixes e numerosos invertebrados. No final da época, o Mediterrâneo foi afetado pela Crise de Salinidade Messiniana, que provocou grandes mudanças nos ambientes marinhos regionais.', 'Gramíneas e formações campestres expandiram-se em várias regiões, acompanhadas por savanas e ambientes abertos. Florestas tropicais, subtropicais e temperadas continuaram importantes e variaram em extensão conforme o clima.', 'Existiam florestas, savanas, pradarias, estepes, rios, lagos e ambientes montanhosos. A ampliação de habitats abertos ofereceu novos nichos para herbívoros pastadores e predadores.', 'Diversificaram-se cavalos, proboscídeos, bovídeos, cervídeos, felinos, canídeos e primatas. Grandes símios tiveram importante história evolutiva durante o Mioceno, e os primeiros hominínios conhecidos surgiram perto de seu final.', 'O Mioceno é subdividido em Aquitaniano, Burdigaliano, Langhiano, Serravalliano, Tortoniano e Messiniano. Destacam-se o ótimo climático do Mioceno Médio e a Crise de Salinidade Messiniana, que afetou a bacia do Mediterrâneo.'),
(88, 'plioceno', 'Plioceno', 'epoca', 5.3330, 2.5800, 83, 'O Plioceno foi a última época do Neógeno, entre aproximadamente 5,333 e 2,58 milhões de anos atrás. Os continentes e muitos ecossistemas já apresentavam características semelhantes às atuais. Mamíferos terrestres, primatas e aves continuaram se diversificando, enquanto o clima evoluiu em direção às condições glaciais do Quaternário.', 'Os continentes estavam próximos das posições modernas. Mudanças na região do istmo do Panamá alteraram gradualmente as conexões entre os oceanos e facilitaram intercâmbios faunísticos entre as Américas. Cordilheiras continuaram influenciando os regimes climáticos.', 'O início do Plioceno apresentou condições relativamente quentes em muitas regiões. Depois ocorreu resfriamento de longo prazo, acompanhado pela intensificação das glaciações do Hemisfério Norte perto do final da época.', 'Os mares abrigavam cetáceos, peixes, tubarões, moluscos e comunidades de plâncton semelhantes às atuais. Mudanças na circulação oceânica influenciaram temperaturas, nutrientes e habitats costeiros.', 'Campos, savanas, florestas e estepes já estavam bem estabelecidos em diferentes regiões. A distribuição da vegetação acompanhou as alterações de temperatura e precipitação.', 'Os habitats incluíam savanas, pradarias, florestas, planícies fluviais, desertos e áreas montanhosas. Alterações nos níveis oceânicos e no clima modificaram paisagens costeiras.', 'Diversos cavalos, proboscídeos, felinos, canídeos, ruminantes e primatas habitavam os continentes. Na África surgiram importantes linhagens de hominínios, incluindo representantes iniciais do gênero Homo perto do final do Plioceno.', 'O Plioceno compreende as idades Zancleano e Piacenziano. A época registrou importantes transformações na evolução dos hominínios e no clima, antecedendo os ciclos glaciais intensos do Pleistoceno.'),
(89, 'daniano', 'Daniano', 'idade', 66.0000, 61.6600, 84, 'O Daniano foi a primeira idade do Paleoceno e começou imediatamente após a extinção do Cretáceo-Paleógeno, há 66 milhões de anos. As comunidades biológicas se reorganizaram após o desaparecimento dos dinossauros não avianos e de muitos organismos marinhos.', 'Os continentes permaneciam em movimento após a fragmentação de Gondwana, enquanto a Índia avançava rumo à Ásia e o oceano Atlântico continuava sua expansão. A distribuição das massas continentais condicionava a recuperação de populações isoladas em diferentes regiões.', 'O clima foi relativamente quente, embora os efeitos ambientais imediatos do impacto e da extinção tenham provocado perturbações no início da idade.', 'O plâncton marinho, os moluscos e outros organismos se recuperavam da extinção, enquanto peixes e tubarões ocupavam os mares.', 'Florestas de angiospermas e coníferas ocupavam amplas áreas quentes, com samambaias e outras plantas em regiões úmidas. Samambaias se expandiram temporariamente em algumas áreas devastadas, acompanhando a recuperação gradual das florestas.', 'Florestas, planícies aluviais, pântanos, lagos e ambientes costeiros ofereciam habitats diversificados para a fauna em recuperação. Áreas afetadas pela crise biológica começaram a recuperar solos, vegetação e cadeias alimentares.', 'Pequenos mamíferos, aves, crocodilianos e tartarugas sobreviveram e se diversificaram, enquanto muitos grupos marinhos reconstruíam suas comunidades.', 'O Daniano registra as consequências do impacto de Chicxulub e a recuperação da biosfera após uma das maiores extinções da história da Terra.'),
(90, 'selandiano', 'Selandiano', 'idade', 61.6600, 59.2400, 84, 'O Selandiano foi a segunda idade do Paleoceno, entre aproximadamente 61,66 e 59,24 milhões de anos atrás. Os ecossistemas terrestres e marinhos tornaram-se progressivamente mais complexos após a reorganização inicial do Daniano.', 'Os continentes permaneciam em movimento após a fragmentação de Gondwana, enquanto a Índia avançava rumo à Ásia e o oceano Atlântico continuava sua expansão. Regiões continentais relativamente isoladas favoreceram a diferenciação de linhagens de mamíferos e aves.', 'O clima continuou geralmente quente, com diferenças regionais de umidade e flutuações que influenciaram as comunidades vegetais.', 'Mares rasos e oceânicos abrigavam foraminíferos, moluscos, peixes e tubarões, com comunidades planctônicas em diversificação.', 'Florestas de angiospermas e coníferas ocupavam amplas áreas quentes, com samambaias e outras plantas em regiões úmidas. Florestas quentes se expandiram e ofereceram novos recursos alimentares para herbívoros e pequenos vertebrados.', 'Florestas, planícies aluviais, pântanos, lagos e ambientes costeiros ofereciam habitats diversificados para a fauna em recuperação. Planícies úmidas e margens de rios sustentavam uma fauna terrestre progressivamente mais diversificada.', 'Diversos mamíferos placentários e outros grupos de vertebrados exploravam nichos herbívoros, insetívoros e predadores.', 'O nome Selandiano deriva da ilha da Zelândia, na Dinamarca, e corresponde a um intervalo importante para correlacionar sedimentos paleocênicos.'),
(91, 'thanetiano', 'Thanetiano', 'idade', 59.2400, 56.0000, 84, 'O Thanetiano foi a última idade do Paleoceno, entre aproximadamente 59,24 e 56 milhões de anos atrás. Os mamíferos e as aves continuaram a se diversificar, e seu encerramento antecedeu um dos maiores eventos de aquecimento rápido do Cenozoico.', 'Os continentes permaneciam em movimento após a fragmentação de Gondwana, enquanto a Índia avançava rumo à Ásia e o oceano Atlântico continuava sua expansão. A configuração continental mantinha importantes barreiras e corredores de dispersão entre faunas regionais.', 'O clima era predominantemente quente; na transição para o Ypresiano ocorreu o Máximo Térmico do Paleoceno-Eoceno.', 'Comunidades marinhas de plâncton, moluscos e peixes foram influenciadas por mudanças de temperatura e química dos oceanos no final da idade.', 'Florestas de angiospermas e coníferas ocupavam amplas áreas quentes, com samambaias e outras plantas em regiões úmidas. Florestas subtropicais e tropicais eram comuns e podiam alcançar latitudes elevadas.', 'Florestas, planícies aluviais, pântanos, lagos e ambientes costeiros ofereciam habitats diversificados para a fauna em recuperação. Ecossistemas florestais e costeiros foram afetados pelas mudanças climáticas que se intensificaram no limite com o Eoceno.', 'Mamíferos, aves, crocodilianos e outros grupos terrestres apresentavam crescente diversidade; os oceanos abrigavam peixes e diversos invertebrados.', 'O Thanetiano recebeu seu nome da ilha de Thanet, na Inglaterra. Seu fim coincide com a transição Paleoceno-Eoceno e o início de um aquecimento global abrupto.'),
(92, 'ypresiano', 'Ypresiano', 'idade', 56.0000, 48.0700, 85, 'O Ypresiano foi a primeira idade do Eoceno e iniciou-se há aproximadamente 56 milhões de anos. Foi marcado por temperaturas globais elevadas, pelo Máximo Térmico do Paleoceno-Eoceno e por importantes mudanças na evolução dos mamíferos.', 'A Índia se aproximava e colidia com a Ásia, enquanto as demais massas continentais e as passagens oceânicas continuavam se reorganizando. Conexões e barreiras geográficas condicionaram dispersões de mamíferos entre regiões do hemisfério norte.', 'O início foi marcado pelo Máximo Térmico do Paleoceno-Eoceno, seguido por condições muito quentes durante parte do Eoceno Inferior.', 'As águas oceânicas aqueceram e passaram por alterações químicas; plâncton, moluscos e peixes responderam às novas condições ambientais.', 'Angiospermas dominavam muitas florestas, acompanhadas por coníferas e samambaias; a distribuição da vegetação variava com a temperatura. Florestas de clima quente expandiram-se para latitudes altas durante intervalos de aquecimento.', 'Florestas, rios, lagos, pântanos e ambientes marinhos sustentavam grande diversidade de vertebrados e invertebrados. Regiões florestais extensas ofereceram habitats para pequenos mamíferos arborícolas e aves.', 'Diversificaram-se primatas primitivos, perissodáctilos e artiodáctilos iniciais, enquanto importantes linhagens de morcegos e outros mamíferos apareceram no registro fóssil.', 'O Ypresiano registra o Máximo Térmico do Paleoceno-Eoceno, um evento de interesse para compreender mudanças rápidas no ciclo do carbono e no clima.'),
(93, 'lutetiano', 'Lutetiano', 'idade', 48.0700, 41.0300, 85, 'O Lutetiano foi a segunda idade do Eoceno, entre aproximadamente 48,07 e 41,03 milhões de anos atrás. Florestas quentes e diversos grupos de mamíferos caracterizavam os ecossistemas, enquanto os cetáceos evoluíam em direção a uma vida cada vez mais aquática.', 'A Índia se aproximava e colidia com a Ásia, enquanto as demais massas continentais e as passagens oceânicas continuavam se reorganizando. A aproximação da Índia com a Ásia e a evolução das bacias costeiras criavam novos ambientes para organismos terrestres e marinhos.', 'Predominavam condições globais quentes, embora o clima começasse a apresentar oscilações e tendências regionais de mudança.', 'Cetáceos primitivos, tubarões, peixes e numerosos invertebrados ocupavam ambientes marinhos costeiros e abertos.', 'Angiospermas dominavam muitas florestas, acompanhadas por coníferas e samambaias; a distribuição da vegetação variava com a temperatura. Florestas de angiospermas eram extensas, sustentando numerosas comunidades de mamíferos e aves.', 'Florestas, rios, lagos, pântanos e ambientes marinhos sustentavam grande diversidade de vertebrados e invertebrados. Mares rasos, deltas e planícies fluviais preservaram fósseis de organismos aquáticos e terrestres.', 'Baleias primitivas, cavalos ancestrais, primatas, morcegos e outros mamíferos se diversificaram ao longo desse intervalo.', 'O Lutetiano recebeu seu nome de Lutécia, designação latina de Paris, onde importantes rochas e fósseis foram estudados.'),
(94, 'bartoniano', 'Bartoniano', 'idade', 41.0300, 37.7100, 85, 'O Bartoniano foi a terceira idade do Eoceno e apresentou importantes mudanças nos ecossistemas terrestres e marinhos. Mamíferos e cetáceos diversificados viveram em um planeta ainda relativamente quente.', 'A Índia se aproximava e colidia com a Ásia, enquanto as demais massas continentais e as passagens oceânicas continuavam se reorganizando. A reorganização tectônica do sul do planeta influenciava as conexões oceânicas e as futuras mudanças na circulação marítima.', 'O clima permaneceu relativamente quente, mas a tendência geral de resfriamento tornou-se mais perceptível em direção ao fim do Eoceno.', 'Os mares abrigavam cetáceos, peixes, tubarões, moluscos e foraminíferos, com variações associadas à temperatura da água.', 'Angiospermas dominavam muitas florestas, acompanhadas por coníferas e samambaias; a distribuição da vegetação variava com a temperatura. Florestas tropicais e temperadas se distribuíam de acordo com as diferenças regionais de clima.', 'Florestas, rios, lagos, pântanos e ambientes marinhos sustentavam grande diversidade de vertebrados e invertebrados. Ambientes costeiros, fluviais e florestais preservaram comunidades de vertebrados e invertebrados.', 'Rinocerontes primitivos, outros perissodáctilos, primatas e cetáceos integravam faunas variadas nos continentes e oceanos.', 'O Bartoniano recebeu seu nome da região de Barton, na Inglaterra. Seus depósitos marinhos ajudam a estudar a biodiversidade do Eoceno Médio e Superior.'),
(95, 'priaboniano', 'Priaboniano', 'idade', 37.7100, 33.9000, 85, 'O Priaboniano foi a última idade do Eoceno, entre cerca de 37,71 e 33,9 milhões de anos atrás. O resfriamento de longo prazo se intensificou e preparou o cenário para mudanças climáticas profundas no início do Oligoceno.', 'A Índia se aproximava e colidia com a Ásia, enquanto as demais massas continentais e as passagens oceânicas continuavam se reorganizando. As mudanças nas passagens oceânicas próximas à Antártida contribuíam para novas condições de circulação marinha.', 'O clima apresentava tendência geral de resfriamento; a grande expansão de geleiras antárticas se consolidaria na transição para o Oligoceno.', 'Comunidades marinhas passaram por mudanças, incluindo transformações na distribuição de plâncton e de organismos sensíveis à temperatura.', 'Angiospermas dominavam muitas florestas, acompanhadas por coníferas e samambaias; a distribuição da vegetação variava com a temperatura. Florestas persistiam em diversas regiões, mas comunidades vegetais adaptadas a temperaturas mais amenas se expandiam localmente.', 'Florestas, rios, lagos, pântanos e ambientes marinhos sustentavam grande diversidade de vertebrados e invertebrados. A reorganização climática afetava habitats costeiros, florestais e marinhos.', 'Cetáceos, peixes, mamíferos terrestres e aves apresentavam fauna diversificada, embora diferentes linhagens tenham sido afetadas pela transição climática.', 'O limite entre Priaboniano e Rupeliano corresponde à transição Eoceno-Oligoceno, marcada por forte resfriamento global e ampliação do gelo antártico.'),
(96, 'rupeliano', 'Rupeliano', 'idade', 33.9000, 27.3000, 86, 'O Rupeliano foi a primeira idade do Oligoceno e começou há aproximadamente 33,9 milhões de anos. Um grande resfriamento climático favoreceu a expansão das geleiras antárticas e transformou as comunidades terrestres e marinhas.', 'Os continentes continuavam seus deslocamentos, e a reorganização das passagens marinhas próximas à Antártida contribuía para novas condições de circulação oceânica. Mudanças nas conexões oceânicas contribuíam para o isolamento térmico da Antártida e para alterações de circulação.', 'O início da idade foi marcado pelo evento de glaciação Oi-1 e por uma queda significativa das temperaturas em relação ao Eoceno.', 'A circulação oceânica e o nível do mar mudaram, afetando comunidades de plâncton, peixes, moluscos e cetáceos.', 'Florestas de angiospermas e coníferas continuavam presentes, enquanto vegetação adaptada a maior sazonalidade se expandia em determinadas regiões. Em diversas regiões, florestas quentes recuaram e formações vegetais adaptadas a temperaturas mais baixas se expandiram.', 'Florestas, ambientes abertos, sistemas fluviais e litorais abrigavam faunas em reorganização sob condições mais frias. Ambientes marinhos rasos foram modificados por mudanças de nível do mar e temperatura.', 'Mamíferos terrestres, incluindo ungulados e carnívoros primitivos, passaram por reorganizações; cetáceos continuaram evoluindo nos oceanos.', 'O Rupeliano recebeu seu nome da região do rio Rupel, na Bélgica. Seu início registra uma das mais importantes transições climáticas do Cenozoico.'),
(97, 'chattiano', 'Chattiano', 'idade', 27.3000, 23.0300, 86, 'O Chattiano foi a segunda e última idade do Oligoceno, entre aproximadamente 27,3 e 23,03 milhões de anos atrás. A fauna de mamíferos e aves continuou se diversificando sob condições mais frias do que as do Eoceno.', 'Os continentes continuavam seus deslocamentos, e a reorganização das passagens marinhas próximas à Antártida contribuía para novas condições de circulação oceânica. Os movimentos tectônicos continuavam alterando a distribuição de cadeias montanhosas e de bacias oceânicas.', 'O clima apresentou oscilações, incluindo episódios de relativo aquecimento e resfriamento; a Antártida manteve importantes mantos de gelo.', 'Os mares abrigavam baleias, tubarões, peixes e numerosos invertebrados, com mudanças nas correntes e na produtividade.', 'Florestas de angiospermas e coníferas continuavam presentes, enquanto vegetação adaptada a maior sazonalidade se expandia em determinadas regiões. Florestas temperadas e vegetação de áreas relativamente secas ocupavam diferentes regiões, sem eliminar as florestas tropicais.', 'Florestas, ambientes abertos, sistemas fluviais e litorais abrigavam faunas em reorganização sob condições mais frias. Sistemas fluviais, planícies e ambientes marinhos sustentavam faunas regionais distintas.', 'Rinocerontes, outros ungulados, predadores e primatas integravam faunas terrestres; baleias modernas se diversificavam nos mares.', 'O Chattiano antecede o Mioceno. Seu nome deriva dos Chatti, povo antigo associado à região que hoje integra a Alemanha.'),
(98, 'aquitaniano', 'Aquitaniano', 'idade', 23.0300, 20.4500, 87, 'O Aquitaniano foi a primeira idade do Mioceno, começando por volta de 23,03 milhões de anos atrás. Os ecossistemas terrestres apresentavam mamíferos cada vez mais diversificados e ambientes florestais e abertos.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. Mudanças na África e na Eurásia alteravam a distribuição das bacias sedimentares e os caminhos de dispersão.', 'O clima era relativamente ameno em diversas regiões, com diferenças importantes na sazonalidade e precipitação.', 'Oceanos abrigavam cetáceos, tubarões e peixes; mares rasos apresentavam moluscos e outros invertebrados.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Florestas de angiospermas e comunidades herbáceas ocupavam ambientes distintos.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. Habitats florestais e fluviais continuavam importantes para primatas e pequenos mamíferos.', 'Ungulados, carnívoros primitivos, roedores e primatas apresentavam diversidade crescente; cetáceos também ocupavam os mares.', 'O Aquitaniano marca o início do Mioceno e recebeu seu nome da região da Aquitânia, no sudoeste da França.'),
(99, 'burdigaliano', 'Burdigaliano', 'idade', 20.4500, 15.9800, 87, 'O Burdigaliano foi a segunda idade do Mioceno e registrou a expansão de diversos grupos de mamíferos. Primatas, ungulados e carnívoros ocuparam variados ecossistemas terrestres.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. Conexões terrestres entre regiões da África e Eurásia favoreceram episódios de dispersão de mamíferos.', 'As temperaturas eram relativamente elevadas em parte do intervalo, antecedendo o ótimo climático do Mioceno Médio.', 'Cetáceos, tubarões, peixes e invertebrados marinhos diversificaram-se em ambientes costeiros e oceânicos.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Florestas eram extensas em várias regiões, coexistindo com comunidades herbáceas e áreas mais abertas.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. Regiões florestais, áreas abertas e ambientes fluviais sustentavam faunas em expansão.', 'Diversas linhagens de grandes símios aparecem no registro fóssil do início do Mioceno, além de ungulados e outros mamíferos.', 'O Burdigaliano recebeu seu nome de Burdigala, denominação romana de Bordeaux, na França.'),
(100, 'langhiano', 'Langhiano', 'idade', 15.9800, 13.8200, 87, 'O Langhiano foi a terceira idade do Mioceno, entre aproximadamente 15,98 e 13,82 milhões de anos atrás. Ocorreu durante o ótimo climático do Mioceno Médio e testemunhou importante diversidade de mamíferos e primatas.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. A evolução de cadeias montanhosas e das conexões continentais influenciava habitats e rotas migratórias.', 'O planeta apresentava condições relativamente quentes durante o ótimo climático do Mioceno Médio, antes de resfriamento posterior.', 'Os oceanos abrigavam cetáceos, tubarões e peixes, enquanto mudanças na temperatura afetavam a distribuição das comunidades marinhas.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Florestas de angiospermas prosperavam em várias regiões, enquanto gramíneas ocupavam habitats abertos.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. Florestas quentes e sistemas fluviais forneciam recursos para numerosos mamíferos e aves.', 'Primatas, proboscídeos, rinocerontes, cervídeos e outros mamíferos diversificaram-se; ecossistemas marinhos abrigavam grandes cetáceos.', 'O Langhiano integra o ótimo climático do Mioceno Médio, importante para compreender mudanças na temperatura global.'),
(101, 'serravalliano', 'Serravalliano', 'idade', 13.8200, 11.6300, 87, 'O Serravalliano foi a quarta idade do Mioceno. Durante esse intervalo, a transição climática do Mioceno Médio contribuiu para o resfriamento global e para mudanças nos ambientes terrestres e aquáticos.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. A tectônica continuou modificando o relevo da Eurásia e de outras regiões continentais.', 'O clima tornou-se progressivamente mais frio após o ótimo climático do Mioceno Médio, favorecendo mudanças na vegetação.', 'A circulação oceânica e as temperaturas da água passaram por transformações, influenciando cetáceos e comunidades planctônicas.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Em algumas regiões, ambientes mais abertos ganharam espaço, embora florestas ainda fossem extensas.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. A expansão regional de áreas abertas alterou habitats e cadeias alimentares.', 'Mamíferos herbívoros e predadores passaram por diversificações e mudanças de distribuição, enquanto cetáceos continuavam presentes nos oceanos.', 'O Serravalliano está associado à Transição Climática do Mioceno Médio, que marcou uma mudança importante no sistema climático global.'),
(102, 'tortoniano', 'Tortoniano', 'idade', 11.6300, 7.2460, 87, 'O Tortoniano foi a quinta idade do Mioceno e ficou marcado pela expansão de ambientes mais abertos em diversas regiões. Mamíferos pastadores e seus predadores se diversificaram em habitats campestres e florestais.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. Mudanças no relevo e nas conexões entre África e Eurásia continuaram influenciando rotas de dispersão.', 'O clima foi geralmente mais frio e, em várias regiões, mais seco ou sazonal do que no Mioceno Médio.', 'Baleias, golfinhos, tubarões e peixes ocupavam diferentes ambientes; a bacia mediterrânea passava por reorganizações.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Gramíneas adaptadas a áreas abertas ganharam importância em algumas regiões, enquanto florestas persistiam em outras.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. Savanas, campos e florestas sustentavam grandes herbívoros, predadores e primatas.', 'Cavalos, bovídeos, proboscídeos, felinos, canídeos e primatas compunham faunas diversificadas.', 'O Tortoniano antecede a Crise de Salinidade Messiniana. Seu nome deriva da região de Tortona, na Itália.'),
(103, 'messiniano', 'Messiniano', 'idade', 7.2460, 5.3330, 87, 'O Messiniano foi a última idade do Mioceno, entre aproximadamente 7,246 e 5,333 milhões de anos atrás. Ficou marcado pela Crise de Salinidade Messiniana e por transformações em ambientes terrestres e marinhos.', 'As massas continentais aproximavam-se das posições atuais; mudanças tectônicas nos Andes, no Himalaia e entre África e Eurásia afetavam relevo e rotas de dispersão. Mudanças tectônicas e nas ligações entre o Atlântico e o Mediterrâneo influenciaram fortemente a geografia regional.', 'O clima apresentou condições relativamente secas em várias regiões, com diferenças regionais de temperatura e precipitação.', 'O Mediterrâneo sofreu restrições na conexão com o Atlântico, resultando em extensa deposição de evaporitos durante a Crise de Salinidade Messiniana.', 'As gramíneas e as angiospermas florestais compunham mosaicos de campos, savanas e florestas cuja distribuição variava entre as regiões. Campos, savanas e florestas distribuíam-se conforme os padrões regionais de umidade.', 'Florestas, savanas, pradarias, planícies fluviais e ambientes costeiros ofereciam habitats variados para mamíferos, aves e outros organismos. Paisagens abertas e ambientes mediterrâneos profundamente alterados coexistiam com florestas e rios.', 'Diversos mamíferos herbívoros e predadores ocupavam os continentes; linhagens próximas à origem dos hominínios surgiram no final do Mioceno.', 'O Messiniano terminou com o restabelecimento da ligação marinha entre o Atlântico e o Mediterrâneo no início do Plioceno.'),
(104, 'zancleano', 'Zancleano', 'idade', 5.3330, 3.6000, 88, 'O Zancleano foi a primeira idade do Plioceno e começou há aproximadamente 5,333 milhões de anos. O clima era relativamente quente em várias regiões, e ecossistemas modernos de florestas e campos continuavam se desenvolvendo.', 'Os continentes já ocupavam posições próximas das atuais, enquanto transformações na região do istmo do Panamá afetavam conexões terrestres e oceânicas. A região do istmo do Panamá e outras conexões geográficas passavam por transformações importantes.', 'As temperaturas eram em média relativamente elevadas em parte do intervalo, com oscilações regionais.', 'O Mediterrâneo voltou a receber águas atlânticas no início do Zancleano, encerrando a Crise de Salinidade Messiniana.', 'Gramíneas, árvores e arbustos compunham savanas, pradarias, estepes e florestas de distribuição variável conforme o clima. Savanas, florestas e gramíneas ocupavam uma diversidade de paisagens.', 'Paisagens de campos, florestas, desertos, rios e lagos abrigavam mamíferos e aves relativamente semelhantes aos modernos. Rios, savanas e florestas sustentavam faunas regionais de mamíferos e aves.', 'Hominínios antigos, proboscídeos, cavalos, antílopes e diferentes predadores habitavam ambientes terrestres.', 'O início do Zancleano coincide com a reinundação do Mediterrâneo, evento frequentemente chamado de inundação zancleana.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(105, 'piacenziano', 'Piacenziano', 'idade', 3.6000, 2.5800, 88, 'O Piacenziano foi a última idade do Plioceno, entre 3,6 e 2,58 milhões de anos atrás. Testemunhou importantes etapas da evolução de hominínios e mudanças climáticas que antecederam o Pleistoceno.', 'Os continentes já ocupavam posições próximas das atuais, enquanto transformações na região do istmo do Panamá afetavam conexões terrestres e oceânicas. As conexões biogeográficas entre as Américas e as mudanças nas correntes oceânicas influenciavam a dispersão dos organismos.', 'O intervalo apresentou fases quentes, seguidas por intensificação do resfriamento e das glaciações do Hemisfério Norte perto do seu final.', 'Mudanças nas temperaturas das águas e na circulação oceânica influenciaram comunidades de cetáceos, peixes e plâncton.', 'Gramíneas, árvores e arbustos compunham savanas, pradarias, estepes e florestas de distribuição variável conforme o clima. Campos, savanas e florestas variavam conforme as alterações de temperatura e precipitação.', 'Paisagens de campos, florestas, desertos, rios e lagos abrigavam mamíferos e aves relativamente semelhantes aos modernos. Mosaicos de habitats abertos e florestais ofereceram condições para diferentes hominínios e grandes mamíferos.', 'Australopitecíneos, representantes iniciais do gênero Homo e numerosos herbívoros e predadores aparecem no registro fóssil do Plioceno final.', 'O Piacenziano antecede o Gelasiano, início do Quaternário. Parte de seu intervalo é usada como referência para estudar climas antigos relativamente quentes.'),
(106, 'gelasiano', 'Gelasiano', 'idade', 2.5800, 1.8000, 4, 'O Gelasiano foi a primeira idade do Pleistoceno, entre 2,58 e 1,80 milhões de anos atrás. Seu início marca também a base do período Quaternário e a intensificação das oscilações glaciais no Hemisfério Norte.', 'Os continentes tinham posições próximas das atuais, mas as glaciações alteravam o nível do mar e expunham plataformas continentais e pontes terrestres. Oscilações do nível dos mares modificavam margens continentais e a extensão de passagens terrestres.', 'Os ciclos frios e relativamente quentes se alternavam e alteravam a extensão das geleiras e dos campos.', 'As mudanças no volume de gelo provocavam oscilações no nível do mar e influenciavam correntes oceânicas e ecossistemas costeiros.', 'A cobertura vegetal alternava entre estepes, tundras, florestas e formações mais abertas conforme as oscilações glaciais e interglaciais. Estepes e formações abertas se expandiam nas fases mais frias em diversas regiões.', 'Geleiras, estepes frias, florestas, rios, lagos e litorais variáveis compunham paisagens modificadas pelo clima. A variação da extensão de geleiras e campos modificava continuamente áreas adequadas à fauna.', 'Grandes mamíferos, como proboscídeos e outros herbívoros, coexistiam com predadores; linhagens humanas primitivas evoluíam na África.', 'O Gelasiano foi transferido para a base do Quaternário na classificação internacional e representa o início formal do Pleistoceno.'),
(107, 'calabriano', 'Calabriano', 'idade', 1.8000, 0.7740, 4, 'O Calabriano foi a segunda idade do Pleistoceno, entre 1,80 e 0,774 milhão de anos atrás. Os ciclos glaciais continuaram transformando paisagens, enquanto populações humanas antigas se dispersavam por diferentes continentes.', 'Os continentes tinham posições próximas das atuais, mas as glaciações alteravam o nível do mar e expunham plataformas continentais e pontes terrestres. As oscilações de nível marinho modificavam litorais, plataformas e pontes terrestres.', 'O clima alternava fases glaciais e interglaciais, com mudanças regionais de umidade e vegetação.', 'Correntes marinhas e linhas costeiras variavam conforme a expansão e o recuo das grandes geleiras.', 'A cobertura vegetal alternava entre estepes, tundras, florestas e formações mais abertas conforme as oscilações glaciais e interglaciais. Florestas avançavam em intervalos mais amenos e campos frios aumentavam durante glaciações.', 'Geleiras, estepes frias, florestas, rios, lagos e litorais variáveis compunham paisagens modificadas pelo clima. Estepes, rios, lagos e regiões florestais ofereciam rotas e habitats para humanos antigos e grandes mamíferos.', 'Grandes herbívoros, carnívoros e representantes antigos do gênero Homo estavam presentes; Homo erectus expandiu-se para fora da África.', 'O Calabriano recebeu seu nome da Calábria, na Itália, e antecede o Chibaniano, o estágio formal do Pleistoceno Médio.'),
(108, 'chibaniano', 'Chibaniano', 'idade', 0.7740, 0.1290, 4, 'O Chibaniano corresponde à idade formal do Pleistoceno Médio, entre 774 mil e 129 mil anos atrás. Foi marcado por glaciações recorrentes e transformações importantes nos vertebrados e na evolução humana.', 'Os continentes tinham posições próximas das atuais, mas as glaciações alteravam o nível do mar e expunham plataformas continentais e pontes terrestres. Pontos de conexão terrestre variavam conforme o nível oceânico durante os ciclos glaciais.', 'Os ciclos climáticos passaram a apresentar frequentemente alternâncias glaciais de maior duração e amplitude.', 'Oscilações do nível do mar e da circulação oceânica acompanhavam mudanças no volume de gelo continental.', 'A cobertura vegetal alternava entre estepes, tundras, florestas e formações mais abertas conforme as oscilações glaciais e interglaciais. Estepes frias, tundras e florestas expandiam-se ou recuavam durante os ciclos climáticos.', 'Geleiras, estepes frias, florestas, rios, lagos e litorais variáveis compunham paisagens modificadas pelo clima. Grandes planícies e corredores temporários de dispersão conectavam algumas regiões continentais.', 'Mamutes, outros grandes mamíferos e populações humanas arcaicas ocupavam a Eurásia e a África; linhagens relacionadas aos neandertais se diversificaram.', 'A base do Chibaniano está associada à reversão geomagnética Matuyama-Brunhes, perto de 774 mil anos atrás. A idade recebeu esse nome da região de Chiba, no Japão.'),
(109, 'pleistoceno-superior', 'Pleistoceno Superior', 'idade', 0.1290, 0.0117, 4, 'O Pleistoceno Superior foi a última subdivisão do Pleistoceno, entre aproximadamente 129 mil e 11.700 anos atrás. Inclui a última grande glaciação e importantes fases de expansão de Homo sapiens.', 'Os continentes tinham posições próximas das atuais, mas as glaciações alteravam o nível do mar e expunham plataformas continentais e pontes terrestres. Durante fases de mar baixo, áreas hoje submersas ficavam expostas, incluindo conexões como a Beríngia.', 'O clima alternou condições relativamente quentes e intensos episódios glaciais; a última glaciação terminou no limite com o Holoceno.', 'O nível oceânico caiu muito durante o Último Máximo Glacial e voltou a subir com o degelo posterior.', 'A cobertura vegetal alternava entre estepes, tundras, florestas e formações mais abertas conforme as oscilações glaciais e interglaciais. Grandes estepes frias e tundras abrigavam megafauna, enquanto florestas se expandiam em fases mais úmidas e quentes.', 'Geleiras, estepes frias, florestas, rios, lagos e litorais variáveis compunham paisagens modificadas pelo clima. Geleiras continentais, estepes e corredores de migração condicionaram a dispersão de humanos e animais.', 'Homo sapiens, neandertais, mamutes, rinocerontes-lanosos, grandes felinos e numerosos outros organismos viveram nesse intervalo.', 'O Pleistoceno Superior é representado na escala ICS como uma subdivisão cujo nome formal de estágio ainda não foi ratificado. Seu término coincide com a transição para o Holoceno.'),
(110, 'greenlandiano', 'Greenlandiano', 'idade', 0.0117, 0.0082, 22, 'O Greenlandiano foi a primeira idade do Holoceno, entre aproximadamente 11.700 e 8.200 anos atrás. Começou após o final do evento frio Younger Dryas e marcou o estabelecimento de condições interglaciais.', 'As massas continentais já apresentavam a configuração moderna, enquanto a elevação pós-glacial do nível do mar transformava as costas. O derretimento das geleiras provocou aumento do nível dos mares e inundação de áreas costeiras.', 'As temperaturas aumentaram após a última grande fase fria e ocorreram alterações nos padrões regionais de chuvas.', 'O nível dos mares subiu rapidamente em diferentes regiões devido à perda de grandes massas de gelo.', 'Florestas, campos, savanas e outras formações vegetais atuais se redistribuíram conforme o clima e, depois, conforme a ação humana. Florestas avançaram sobre áreas anteriormente dominadas por tundras e estepes frias.', 'Florestas, pradarias, desertos, rios, lagos, zonas costeiras e ambientes cultivados compunham uma paisagem em transformação. Muitos litorais, rios e lagos passaram por rápidas transformações em consequência do degelo.', 'Mamíferos, aves e outras faunas modernas se reorganizaram; grupos humanos desenvolveram formas variadas de subsistência e, em algumas regiões, agricultura inicial.', 'Greenlandiano é o nome formal do Holoceno Inferior. Seu limite inicial é definido por registros em testemunhos de gelo da Groenlândia.'),
(111, 'northgrippiano', 'Northgrippiano', 'idade', 0.0082, 0.0042, 22, 'O Northgrippiano foi a segunda idade do Holoceno, entre aproximadamente 8.200 e 4.200 anos atrás. Abrange transformações climáticas regionais e a expansão de sociedades agrícolas em diferentes partes do mundo.', 'As massas continentais já apresentavam a configuração moderna, enquanto a elevação pós-glacial do nível do mar transformava as costas. O nível oceânico aproximava-se gradualmente de condições semelhantes às modernas em muitas regiões.', 'O início foi marcado pelo evento climático de 8,2 mil anos, um episódio relativamente breve de resfriamento no Hemisfério Norte.', 'Os oceanos e litorais continuaram se ajustando à elevação pós-glacial do nível do mar.', 'Florestas, campos, savanas e outras formações vegetais atuais se redistribuíram conforme o clima e, depois, conforme a ação humana. Florestas e outras comunidades vegetais se reorganizaram conforme o clima e o avanço das atividades humanas.', 'Florestas, pradarias, desertos, rios, lagos, zonas costeiras e ambientes cultivados compunham uma paisagem em transformação. A expansão da agricultura e dos assentamentos alterou algumas paisagens continentais.', 'A fauna moderna predominava, enquanto populações humanas passaram a transformar de forma mais intensa diversos habitats.', 'Northgrippiano é a idade formal equivalente ao Holoceno Médio. Seu início coincide com um evento de resfriamento documentado em registros de gelo.'),
(112, 'megalayano', 'Megalayano', 'idade', 0.0042, 0.0000, 22, 'O Megalayano é a terceira e atual idade do Holoceno, iniciada há aproximadamente 4.200 anos. Abrange o desenvolvimento de grandes sociedades históricas, mudanças regionais do clima e transformações humanas cada vez mais intensas na paisagem.', 'As massas continentais já apresentavam a configuração moderna, enquanto a elevação pós-glacial do nível do mar transformava as costas. Os continentes apresentam sua configuração moderna e os ambientes costeiros continuam sujeitos a transformações locais.', 'A base da idade está associada a um episódio de aridez em algumas regiões por volta de 4,2 mil anos atrás; nas épocas recentes, o aquecimento global de origem humana tornou-se muito importante.', 'O nível oceânico apresentou relativa estabilidade durante grande parte do intervalo, mas atualmente a elevação do mar é uma preocupação ambiental global.', 'Florestas, campos, savanas e outras formações vegetais atuais se redistribuíram conforme o clima e, depois, conforme a ação humana. Agricultura, desmatamento e urbanização modificaram extensas áreas de vegetação natural.', 'Florestas, pradarias, desertos, rios, lagos, zonas costeiras e ambientes cultivados compunham uma paisagem em transformação. Cidades, áreas agrícolas, florestas remanescentes e ecossistemas aquáticos coexistem com profundas alterações humanas.', 'A biodiversidade é composta principalmente por organismos modernos, mas numerosas espécies sofreram extinções ou mudanças de distribuição relacionadas às atividades humanas.', 'Megalayano é o nome formal do Holoceno Superior e representa a idade geológica atual. Seu nome deriva de Meghalaya, na Índia, onde um espeleotema forneceu registros utilizados na definição do limite.'),
(113, 'fortuniano', 'Fortuniano', 'idade', 538.8000, 529.0000, 40, 'Fortuniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 538.8 e 529 milhões de anos atrás. O Fortuniano iniciou o Cambriano e é reconhecido por mudanças na atividade dos organismos que viviam e escavavam o sedimento marinho. A diversificação dos primeiros animais ainda antecedia a expansão dos trilobitas.', 'Gondwana ocupava extensas latitudes austrais, enquanto Laurentia, Báltica e Sibéria constituíam massas continentais separadas, cercadas por plataformas marinhas. Litorais extensos ofereciam novos depósitos sedimentares para o registro de rastros fósseis.', 'Predominavam condições relativamente quentes, com mares rasos amplos e oscilações ambientais regionais. Condições oceânicas e disponibilidade de oxigênio variavam entre bacias.', 'As plataformas de águas rasas abrigavam tapetes microbianos e invertebrados em diversificação, num cenário de reorganização ecológica. Vestígios de escavação e pequenas conchas marcam parte do registro marinho inicial.', 'Não havia florestas nem plantas terrestres; cianobactérias e algas sustentavam a produção primária aquática. Comunidades microbianas revestiam sedimentos em vários habitats.', 'Fundos marinhos, depósitos costeiros e sedimentos rasos registravam atividades de animais escavadores e bentônicos. Trilhas e galerias fossilizadas testemunham animais interagindo com o fundo marinho.', 'A fauna incluía animais de corpo mole, esponjas e formas produtoras de pequenas estruturas mineralizadas, anteriores à expansão dos trilobitas. Organismos escavadores e pequenos invertebrados tornaram as relações com o sedimento mais complexas.', 'A base do Fortuniano e do Cambriano é definida pelo registro da icnoespécie Treptichnus pedum em um estratótipo de Newfoundland, no Canadá.'),
(114, 'estagio-2-cambriano', 'Estágio 2 do Cambriano', 'idade', 529.0000, 521.0000, 40, 'Estágio 2 do Cambriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 529 e 521 milhões de anos atrás. O Estágio 2 do Cambriano sucedeu o Fortuniano e acompanhou a diversificação de organismos marinhos que produziam pequenas partes duras. A escala internacional ainda o identifica por um nome provisório.', 'Gondwana ocupava extensas latitudes austrais, enquanto Laurentia, Báltica e Sibéria constituíam massas continentais separadas, cercadas por plataformas marinhas. Plataformas rasas de diferentes paleocontinentes abrigavam comunidades de invertebrados.', 'Predominavam condições relativamente quentes, com mares rasos amplos e oscilações ambientais regionais. As temperaturas e os mares variavam regionalmente, sem florestas terrestres capazes de alterar o clima local.', 'As plataformas de águas rasas abrigavam tapetes microbianos e invertebrados em diversificação, num cenário de reorganização ecológica. A expansão de esqueletos pequenos aumentou a visibilidade de organismos no registro fóssil.', 'Não havia florestas nem plantas terrestres; cianobactérias e algas sustentavam a produção primária aquática. Algas e tapetes microbianos sustentavam cadeias alimentares incipientes.', 'Fundos marinhos, depósitos costeiros e sedimentos rasos registravam atividades de animais escavadores e bentônicos. Ambientes de plataforma preservaram conchas e outros restos mineralizados.', 'A fauna incluía animais de corpo mole, esponjas e formas produtoras de pequenas estruturas mineralizadas, anteriores à expansão dos trilobitas. Esponjas e pequenos animais com partes mineralizadas participaram da diversificação inicial.', 'O nome Estágio 2 é provisório na tabela internacional: não deve ser confundido com um estágio formalmente batizado.'),
(115, 'estagio-3-cambriano', 'Estágio 3 do Cambriano', 'idade', 521.0000, 514.5000, 41, 'Estágio 3 do Cambriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 521 e 514.5 milhões de anos atrás. O Estágio 3 do Cambriano representou uma etapa intensa da diversificação animal, com o surgimento e expansão de trilobitas no registro fóssil. Depósitos como os de Chengjiang revelam a complexidade dos mares dessa época.', 'Gondwana permanecia extensa e Laurentia, Báltica e Sibéria seguiam separadas; mares tropicais recobriam várias margens continentais. Ambientes costeiros de diferentes continentes sustentavam faunas distintas.', 'O clima era geralmente quente, com nível do mar relativamente alto e variações locais na circulação aquática. Mares quentes favoreceram a ocupação de plataformas por novos organismos.', 'Os mares testemunharam o desenvolvimento de cadeias alimentares com predadores ativos, animais escavadores e comunidades de fundo cada vez mais complexas. Predadores e presas integravam cadeias alimentares cada vez mais elaboradas.', 'Não existiam plantas terrestres estabelecidas; algas e microrganismos fotossintéticos produziam a matéria orgânica que alimentava as redes marinhas. A produção primária permanecia ligada a organismos aquáticos.', 'Plataformas continentais, mares rasos e fundos sedimentares preservaram fósseis de organismos tanto mineralizados quanto delicados. Fundos de sedimentos finos favoreceram a conservação de animais de corpo mole.', 'Trilobitas e outros artrópodes ampliaram sua presença, juntamente com braquiópodes, esponjas e animais de corpo mole. Trilobitas, radiodontes e diversos artrópodes destacaram-se nos ecossistemas.', 'A biota de Chengjiang, na China, é uma das janelas mais conhecidas para observar organismos de corpo mole do Cambriano inicial.'),
(116, 'estagio-4-cambriano', 'Estágio 4 do Cambriano', 'idade', 514.5000, 506.5000, 41, 'Estágio 4 do Cambriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 514.5 e 506.5 milhões de anos atrás. O Estágio 4 do Cambriano continuou a diversificação de trilobitas, predadores e outros invertebrados marinhos. A organização ecológica dos fundos oceânicos se tornou mais complexa, com diferentes maneiras de alimentação e locomoção.', 'Gondwana permanecia extensa e Laurentia, Báltica e Sibéria seguiam separadas; mares tropicais recobriam várias margens continentais. Plataformas marinhas sobre margens continentais apresentavam amplas áreas habitáveis.', 'O clima era geralmente quente, com nível do mar relativamente alto e variações locais na circulação aquática. Oscilações no nível do mar modificavam a área disponível aos organismos bentônicos.', 'Os mares testemunharam o desenvolvimento de cadeias alimentares com predadores ativos, animais escavadores e comunidades de fundo cada vez mais complexas. Comunidades marinhas utilizavam diferentes profundidades e substratos.', 'Não existiam plantas terrestres estabelecidas; algas e microrganismos fotossintéticos produziam a matéria orgânica que alimentava as redes marinhas. Microrganismos e algas forneciam energia aos ecossistemas aquáticos.', 'Plataformas continentais, mares rasos e fundos sedimentares preservaram fósseis de organismos tanto mineralizados quanto delicados. Fundos rasos e depósitos lamosos concentravam muitos fósseis de invertebrados.', 'Trilobitas e outros artrópodes ampliaram sua presença, juntamente com braquiópodes, esponjas e animais de corpo mole. Trilobitas e outros artrópodes formavam uma parcela importante das faunas conhecidas.', 'Assim como o Estágio 3, o Estágio 4 ainda é apresentado pela ICS com uma designação provisória.'),
(117, 'wuliuano', 'Wuliuano', 'idade', 506.5000, 504.5000, 42, 'Wuliuano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 506.5 e 504.5 milhões de anos atrás. O Wuliuano iniciou a época Miaolingiana e marcou uma continuidade da diversificação dos animais marinhos. Trilobitas e outros artrópodes eram comuns em diferentes plataformas e bacias.', 'Gondwana, Laurentia, Báltica e Sibéria estavam distribuídas por extensas regiões oceânicas, com plataformas tropicais favoráveis à vida. Os mares de plataforma de Gondwana e de outros continentes favoreciam a distribuição de comunidades marinhas.', 'Condições predominantemente quentes e mares extensos coexistiam com episódios locais de mudança do nível do mar. A disponibilidade de habitats dependia das mudanças de nível marinho e sedimentação.', 'A diversidade de invertebrados bentônicos e predadores nectônicos aumentava, com trilobitas e outros artrópodes ocupando numerosos nichos. O registro de trilobitas possibilita reconhecer limites estratigráficos em rochas dessa idade.', 'A base produtora dos ecossistemas continuava aquática, sustentada por algas e microrganismos fotossintéticos; não havia florestas terrestres. Tapetes microbianos e algas continuavam atuando como produtores.', 'Fundos marinhos, plataformas carbonáticas e depósitos de preservação excepcional documentavam organismos delicados. Depósitos de águas rasas registravam sucessões de comunidades bentônicas.', 'Trilobitas, radiodontes, braquiópodes, esponjas, equinodermos primitivos e cordados antigos integravam comunidades marinhas variadas. Trilobitas, radiodontes, braquiópodes e outros invertebrados constituíam ecossistemas diversificados.', 'A base do Wuliuano é definida por um estratótipo na China e está associada ao primeiro aparecimento do trilobita Oryctocephalus indicus.'),
(118, 'drumiano', 'Drumiano', 'idade', 504.5000, 500.5000, 42, 'Drumiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 504.5 e 500.5 milhões de anos atrás. O Drumiano foi a segunda idade do Miaolingiano. Os ecossistemas marinhos continuavam organizados em comunidades com trilobitas, invertebrados filtradores e predadores.', 'Gondwana, Laurentia, Báltica e Sibéria estavam distribuídas por extensas regiões oceânicas, com plataformas tropicais favoráveis à vida. As plataformas de mares tropicais preservavam sucessões fossilíferas valiosas para correlação.', 'Condições predominantemente quentes e mares extensos coexistiam com episódios locais de mudança do nível do mar. Mudanças ambientais locais afetavam distribuição de organismos em mares rasos.', 'A diversidade de invertebrados bentônicos e predadores nectônicos aumentava, com trilobitas e outros artrópodes ocupando numerosos nichos. Os trilobitas são particularmente úteis para comparar rochas drumianas.', 'A base produtora dos ecossistemas continuava aquática, sustentada por algas e microrganismos fotossintéticos; não havia florestas terrestres. Algas e microrganismos marinhos continuavam sustentando as redes tróficas.', 'Fundos marinhos, plataformas carbonáticas e depósitos de preservação excepcional documentavam organismos delicados. Fundos marinhos com diferentes substratos favoreciam estratégias variadas de vida.', 'Trilobitas, radiodontes, braquiópodes, esponjas, equinodermos primitivos e cordados antigos integravam comunidades marinhas variadas. Trilobitas, braquiópodes e artrópodes predadores integravam comunidades costeiras e marinhas.', 'O nome Drumiano deriva da região de Drum Mountains, no estado de Utah, Estados Unidos.'),
(119, 'guzhangiano', 'Guzhangiano', 'idade', 500.5000, 497.0000, 42, 'Guzhangiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 500.5 e 497 milhões de anos atrás. O Guzhangiano encerrou o Miaolingiano e registrou transformações nas comunidades marinhas, especialmente nas associações de trilobitas. A diversificação e substituição de linhagens antecederam o Furongiano.', 'Gondwana, Laurentia, Báltica e Sibéria estavam distribuídas por extensas regiões oceânicas, com plataformas tropicais favoráveis à vida. O registro paleogeográfico incluía continentes ainda isolados por extensos oceanos.', 'Condições predominantemente quentes e mares extensos coexistiam com episódios locais de mudança do nível do mar. Variações marinhas regionais influenciavam a distribuição de fauna.', 'A diversidade de invertebrados bentônicos e predadores nectônicos aumentava, com trilobitas e outros artrópodes ocupando numerosos nichos. Plataformas sedimentares apresentavam trilobitas e outros organismos bentônicos.', 'A base produtora dos ecossistemas continuava aquática, sustentada por algas e microrganismos fotossintéticos; não havia florestas terrestres. A vegetação terrestre permanecia inexistente, e os produtores eram aquáticos.', 'Fundos marinhos, plataformas carbonáticas e depósitos de preservação excepcional documentavam organismos delicados. Rochas de plataformas marinhas preservaram importantes sucessões bioestratigráficas.', 'Trilobitas, radiodontes, braquiópodes, esponjas, equinodermos primitivos e cordados antigos integravam comunidades marinhas variadas. Trilobitas continuavam especialmente diversos, acompanhados por outros invertebrados.', 'O Guzhangiano recebeu seu nome de uma localidade na China e integra a parte final da época Miaolingiana.'),
(120, 'paibiano', 'Paibiano', 'idade', 497.0000, 494.2000, 43, 'Paibiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 497 e 494.2 milhões de anos atrás. O Paibiano iniciou o Furongiano. Os ecossistemas marinhos passaram por mudanças na composição dos trilobitas, que continuam sendo importantes fósseis de referência para esta idade.', 'Gondwana dominava o hemisfério sul, enquanto Laurentia, Báltica e Sibéria mantinham separação geográfica e extensa borda de mares rasos. Laurentia e Gondwana eram separadas por extensas massas oceânicas.', 'O clima mantinha caráter relativamente quente, embora oscilações do nível do mar influenciassem a distribuição da fauna. Oscilações de nível marinho influenciavam as plataformas continentais.', 'Mares de plataforma abrigavam trilobitas e outros invertebrados, com renovações faunísticas ao longo do final cambriano. Trilobitas servem como indicadores estratigráficos para reconhecer o início dessa idade.', 'Algas e microrganismos continuavam responsáveis pela produção primária; vegetação vascular terrestre ainda não existia. O papel de algas e microrganismos era central no abastecimento das cadeias tróficas.', 'Plataformas continentais, mares rasos e depósitos carbonáticos constituíam habitats predominantes. Ambientes carbonáticos e fundos sedimentares registravam organismos bentônicos.', 'Trilobitas, braquiópodes, moluscos e outros invertebrados diversificavam-se e sofriam mudanças nas associações de espécies. Trilobitas, braquiópodes e diversos invertebrados eram comuns nos mares.', 'O Paibiano tem sua base definida por um estratótipo na China, associado ao primeiro aparecimento do trilobita Glyptagnostus reticulatus.'),
(121, 'jiangshaniano', 'Jiangshaniano', 'idade', 494.2000, 491.0000, 43, 'Jiangshaniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 494.2 e 491 milhões de anos atrás. O Jiangshaniano foi a segunda idade do Furongiano e testemunhou mudanças evolutivas na fauna marinha. Trilobitas e outros invertebrados permaneciam característicos dos mares cambrianos.', 'Gondwana dominava o hemisfério sul, enquanto Laurentia, Báltica e Sibéria mantinham separação geográfica e extensa borda de mares rasos. Extensas plataformas costeiras existiam ao redor dos paleocontinentes separados.', 'O clima mantinha caráter relativamente quente, embora oscilações do nível do mar influenciassem a distribuição da fauna. Mudanças locais na circulação e profundidade dos mares afetavam os organismos.', 'Mares de plataforma abrigavam trilobitas e outros invertebrados, com renovações faunísticas ao longo do final cambriano. Depósitos marinhos sucessivos são úteis para estudar a evolução da fauna de trilobitas.', 'Algas e microrganismos continuavam responsáveis pela produção primária; vegetação vascular terrestre ainda não existia. A produção primária se mantinha predominantemente associada a algas e microrganismos.', 'Plataformas continentais, mares rasos e depósitos carbonáticos constituíam habitats predominantes. Mares rasos sedimentares preservavam os fósseis mais frequentes.', 'Trilobitas, braquiópodes, moluscos e outros invertebrados diversificavam-se e sofriam mudanças nas associações de espécies. Trilobitas, braquiópodes, moluscos e organismos de corpo mole ocupavam os habitats.', 'Seu nome se refere a Jiangshan, na China, região importante para a estratigrafia do final cambriano.'),
(122, 'estagio-10-cambriano', 'Estágio 10 do Cambriano', 'idade', 491.0000, 486.8500, 43, 'Estágio 10 do Cambriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 491 e 486.85 milhões de anos atrás. O Estágio 10 do Cambriano corresponde à etapa final do período. Organismos marinhos já compunham comunidades complexas que antecederam a grande biodiversificação do Ordoviciano.', 'Gondwana dominava o hemisfério sul, enquanto Laurentia, Báltica e Sibéria mantinham separação geográfica e extensa borda de mares rasos. Os continentes continuavam separados, com mares de plataforma amplos e diversificados.', 'O clima mantinha caráter relativamente quente, embora oscilações do nível do mar influenciassem a distribuição da fauna. Oscilações ambientais locais antecederam a transição entre Cambriano e Ordoviciano.', 'Mares de plataforma abrigavam trilobitas e outros invertebrados, com renovações faunísticas ao longo do final cambriano. As associações de trilobitas e outros invertebrados sofreram renovações faunísticas.', 'Algas e microrganismos continuavam responsáveis pela produção primária; vegetação vascular terrestre ainda não existia. Algas e microrganismos continuavam sendo os principais produtores primários.', 'Plataformas continentais, mares rasos e depósitos carbonáticos constituíam habitats predominantes. Plataformas sedimentares registraram a transição entre as faunas cambrianas e ordovicianas.', 'Trilobitas, braquiópodes, moluscos e outros invertebrados diversificavam-se e sofriam mudanças nas associações de espécies. Trilobitas, braquiópodes e moluscos coexistiam com outros invertebrados marinhos.', 'Estágio 10 é uma denominação provisória da ICS para a última idade do Cambriano; sua base ainda carece de nome formal internacional.'),
(123, 'tremadociano', 'Tremadociano', 'idade', 486.8500, 477.1000, 44, 'Tremadociano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 486.85 e 477.1 milhões de anos atrás. O Tremadociano inaugurou o Ordoviciano após o encerramento do Cambriano. Os ecossistemas oceânicos passaram por renovação e diversificação de trilobitas, graptólitos e outros invertebrados.', 'Gondwana dominava latitudes austrais, enquanto Laurentia, Báltica e Sibéria permaneciam separadas pelo oceano Iapetus e outras bacias. Laurentia e Báltica permaneciam distantes, com o Iapetus como importante barreira oceânica.', 'Condições relativamente quentes e transgressões marinhas favoreceram extensos mares epicontinentais. A expansão dos mares favoreceu habitats de plataforma.', 'Plataformas marinhas testemunharam a diversificação de braquiópodes, trilobitas, graptólitos e cefalópodes. Graptólitos e outros organismos planctônicos começaram a ganhar importância estratigráfica.', 'Não existiam florestas; a produção primária era sobretudo marinha e os primeiros indícios de plantas terrestres eram muito discretos. A vegetação terrestre ainda não constituía cobertura extensa.', 'Mares rasos, plataformas carbonáticas e fundos oceânicos criavam habitats para animais filtradores, escavadores e nadadores. Mares rasos e fundos sedimentares acolhiam animais de hábitos variados.', 'Graptólitos, trilobitas, braquiópodes e moluscos tornaram-se importantes, ao lado dos primeiros vertebrados sem mandíbulas. Trilobitas, braquiópodes, moluscos e primeiros vertebrados sem mandíbulas compunham a fauna.', 'O nome Tremadociano deriva de Tremadog, no País de Gales; sua base coincide com o início do período Ordoviciano.'),
(124, 'floiano', 'Floiano', 'idade', 477.1000, 471.3000, 44, 'Floiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 477.1 e 471.3 milhões de anos atrás. O Floiano concluiu o Ordoviciano Inferior e foi marcado pela expansão das comunidades marinhas. Graptólitos, braquiópodes e trilobitas contribuíram para ecossistemas cada vez mais diversificados.', 'Gondwana dominava latitudes austrais, enquanto Laurentia, Báltica e Sibéria permaneciam separadas pelo oceano Iapetus e outras bacias. Mares amplos cercavam Laurentia, Báltica, Sibéria e Gondwana.', 'Condições relativamente quentes e transgressões marinhas favoreceram extensos mares epicontinentais. As condições quentes favoreceram comunidades de plataformas continentais.', 'Plataformas marinhas testemunharam a diversificação de braquiópodes, trilobitas, graptólitos e cefalópodes. Graptólitos planctônicos são especialmente relevantes para a correlação de rochas floianas.', 'Não existiam florestas; a produção primária era sobretudo marinha e os primeiros indícios de plantas terrestres eram muito discretos. Os produtores primários permaneciam principalmente aquáticos.', 'Mares rasos, plataformas carbonáticas e fundos oceânicos criavam habitats para animais filtradores, escavadores e nadadores. Bacias marinhas e plataformas forneceram novos habitats.', 'Graptólitos, trilobitas, braquiópodes e moluscos tornaram-se importantes, ao lado dos primeiros vertebrados sem mandíbulas. Trilobitas, braquiópodes, graptólitos e cefalópodes eram componentes importantes.', 'O Floiano foi nomeado a partir de uma localidade na Suécia e utiliza graptólitos como fósseis relevantes à delimitação estratigráfica.'),
(125, 'dapingiano', 'Dapingiano', 'idade', 471.3000, 469.4000, 45, 'Dapingiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 471.3 e 469.4 milhões de anos atrás. O Dapingiano iniciou o Ordoviciano Médio, em uma fase de expansão das faunas marinhas. Comunidades bentônicas tornaram-se mais estruturadas, com diversificação de organismos filtradores e móveis.', 'Gondwana ainda dominava o sul, Laurentia ocupava latitudes tropicais e o Iapetus separava importantes massas continentais. Gondwana e Laurentia continuavam separados por vastas bacias oceânicas.', 'O clima geralmente quente e a presença de mares rasos favoreceram a biodiversificação marinha. Os mares relativamente quentes favoreciam a expansão dos invertebrados.', 'Recifes, plataformas e ambientes pelágicos apresentavam grande expansão de briozoários, braquiópodes, equinodermos e graptólitos. Plataformas rasas eram ricas em organismos que viviam sobre o fundo.', 'Algas marinhas eram essenciais à produção primária, enquanto possíveis plantas terrestres pequenas ocupavam habitats úmidos. Algas e microrganismos aquáticos formavam a base da produção primária.', 'Mares de plataforma, recifes e regiões costeiras proporcionavam ambientes ecológicos distintos. Mares de plataforma mantinham habitat para diferentes estratégias alimentares.', 'O Grande Evento de Biodiversificação Ordoviciana intensificou as relações entre braquiópodes, briozoários, trilobitas, equinodermos e cefalópodes. Braquiópodes, briozoários, trilobitas e equinodermos integravam as comunidades.', 'O nome Dapingiano deriva de Daping, na China, onde foi estabelecido seu estratótipo de referência.'),
(126, 'darriwiliano', 'Darriwiliano', 'idade', 469.4000, 458.2000, 45, 'Darriwiliano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 469.4 e 458.2 milhões de anos atrás. O Darriwiliano foi marcado por uma etapa importante do Grande Evento de Biodiversificação Ordoviciana. A variedade de invertebrados marinhos e as relações entre organismos aumentaram significativamente.', 'Gondwana ainda dominava o sul, Laurentia ocupava latitudes tropicais e o Iapetus separava importantes massas continentais. Plataformas tropicais de Laurentia e outras massas continentais abrigavam faunas regionais variadas.', 'O clima geralmente quente e a presença de mares rasos favoreceram a biodiversificação marinha. Mares amplos e condições relativamente quentes favoreceram recifes e comunidades filtradoras.', 'Recifes, plataformas e ambientes pelágicos apresentavam grande expansão de briozoários, braquiópodes, equinodermos e graptólitos. Braquiópodes, briozoários e equinodermos diversificaram-se nos mares rasos.', 'Algas marinhas eram essenciais à produção primária, enquanto possíveis plantas terrestres pequenas ocupavam habitats úmidos. As plantas terrestres ainda eram discretas e próximas de ambientes úmidos.', 'Mares de plataforma, recifes e regiões costeiras proporcionavam ambientes ecológicos distintos. Recifes e plataformas carbonáticas criaram novos nichos ecológicos.', 'O Grande Evento de Biodiversificação Ordoviciana intensificou as relações entre braquiópodes, briozoários, trilobitas, equinodermos e cefalópodes. Trilobitas, cefalópodes, braquiópodes, graptólitos e briozoários aumentaram sua diversidade.', 'O Darriwiliano é uma idade de destaque para compreender a Grande Biodiversificação Ordoviciana, que transformou os ecossistemas oceânicos.'),
(127, 'sandbiano', 'Sandbiano', 'idade', 458.2000, 452.8000, 46, 'Sandbiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 458.2 e 452.8 milhões de anos atrás. O Sandbiano iniciou o Ordoviciano Superior, quando os mares já sustentavam grande biodiversidade. Braquiópodes, equinodermos, trilobitas e cefalópodes ocupavam diversos nichos.', 'Gondwana avançava para altas latitudes austrais, com alterações na distribuição dos mares e das plataformas continentais. Gondwana continuava sua trajetória para latitudes mais austrais.', 'O intervalo começou relativamente quente, mas terminou com forte resfriamento, glaciação e importantes mudanças do nível do mar. Predominavam condições relativamente quentes antes do resfriamento do fim do Ordoviciano.', 'As comunidades marinhas eram muito diversificadas antes de crises ligadas à regressão marinha e às alterações de oxigenação. Mares rasos e recifes apresentavam comunidades complexas de organismos bentônicos.', 'A vegetação continental ainda era incipiente e de baixo porte; algas e outros produtores marinhos permaneciam fundamentais. Evidências de plantas terrestres continuavam limitadas a formas primitivas.', 'Recifes, mares rasos e plataformas continentais foram profundamente afetados pelas oscilações do nível oceânico. Plataformas marinhas mantinham ampla diversidade de habitats.', 'Braquiópodes, trilobitas, graptólitos, equinodermos e cefalópodes eram abundantes antes da extinção do final do período. Graptólitos, braquiópodes, trilobitas, corais e cefalópodes compunham faunas variadas.', 'O Sandbiano recebeu seu nome da localidade de Södra Sandby, na Suécia, associada à definição do limite estratigráfico.'),
(128, 'katiano', 'Katiano', 'idade', 452.8000, 445.2000, 46, 'Katiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 452.8 e 445.2 milhões de anos atrás. O Katiano foi uma fase de elevada diversidade marinha, com recifes, braquiópodes e trilobitas abundantes. Seu final antecedeu o resfriamento extremo e a crise biológica do Hirnantiano.', 'Gondwana avançava para altas latitudes austrais, com alterações na distribuição dos mares e das plataformas continentais. Gondwana ocupava latitudes austrais relevantes para a futura glaciação.', 'O intervalo começou relativamente quente, mas terminou com forte resfriamento, glaciação e importantes mudanças do nível do mar. Condições geralmente amenas ou quentes no início deram lugar a mudanças anteriores à crise terminal.', 'As comunidades marinhas eram muito diversificadas antes de crises ligadas à regressão marinha e às alterações de oxigenação. Recifes e plataformas carbonáticas sustentavam invertebrados variados.', 'A vegetação continental ainda era incipiente e de baixo porte; algas e outros produtores marinhos permaneciam fundamentais. A vida vegetal terrestre continuava restrita a formas simples e dispersas.', 'Recifes, mares rasos e plataformas continentais foram profundamente afetados pelas oscilações do nível oceânico. Recifes, mares rasos e fundos oceânicos apresentavam elevada complexidade.', 'Braquiópodes, trilobitas, graptólitos, equinodermos e cefalópodes eram abundantes antes da extinção do final do período. Braquiópodes, graptólitos, trilobitas, equinodermos e cefalópodes eram importantes.', 'O Katiano é conhecido pela grande diversidade dos mares ordovicianos pouco antes da extinção em massa do final do período.'),
(129, 'hirnantiano', 'Hirnantiano', 'idade', 445.2000, 443.1000, 46, 'Hirnantiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 445.2 e 443.1 milhões de anos atrás. O Hirnantiano encerrou o Ordoviciano e foi marcado por forte glaciação e uma das cinco maiores extinções em massa da história da Terra. O resfriamento e as oscilações do nível do mar desestabilizaram ecossistemas marinhos.', 'Gondwana avançava para altas latitudes austrais, com alterações na distribuição dos mares e das plataformas continentais. Grandes mantos de gelo desenvolveram-se sobre regiões de Gondwana.', 'O intervalo começou relativamente quente, mas terminou com forte resfriamento, glaciação e importantes mudanças do nível do mar. O resfriamento global levou à redução do nível do mar e posteriormente a novas alterações ambientais.', 'As comunidades marinhas eram muito diversificadas antes de crises ligadas à regressão marinha e às alterações de oxigenação. A regressão marinha e mudanças na oxigenação causaram perdas em comunidades de plataforma.', 'A vegetação continental ainda era incipiente e de baixo porte; algas e outros produtores marinhos permaneciam fundamentais. A cobertura vegetal terrestre ainda era muito limitada e não amenizou os impactos ambientais.', 'Recifes, mares rasos e plataformas continentais foram profundamente afetados pelas oscilações do nível oceânico. Mares rasos encolheram, reduzindo habitats de numerosos invertebrados.', 'Braquiópodes, trilobitas, graptólitos, equinodermos e cefalópodes eram abundantes antes da extinção do final do período. Muitos braquiópodes, trilobitas e graptólitos sofreram extinções, com reorganização das comunidades sobreviventes.', 'A extinção do final do Ordoviciano ocorreu em pulsos associados à glaciação hirnantiana e à reorganização posterior dos oceanos.'),
(130, 'rhuddaniano', 'Rhuddaniano', 'idade', 443.1000, 440.5000, 47, 'Rhuddaniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 443.1 e 440.5 milhões de anos atrás. O Rhuddaniano iniciou o Siluriano após a extinção do final do Ordoviciano. A recuperação da fauna marinha ocorreu enquanto as geleiras recuavam e os mares voltavam a ocupar plataformas continentais.', 'Gondwana permanecia austral; Laurentia e Báltica se aproximavam, reduzindo gradualmente o oceano Iapetus. Laurentia, Báltica e Gondwana ainda ocupavam regiões distintas.', 'O recuo da glaciação do final do Ordoviciano favoreceu aquecimento relativo e recuperação dos mares rasos. O recuo da glaciação favoreceu a retomada de condições mais quentes.', 'Comunidades de graptólitos, braquiópodes, trilobitas e organismos recifais se reorganizaram após a extinção. Graptólitos sobreviventes e comunidades bentônicas reconstruíram cadeias alimentares.', 'Formas vegetais simples e precursoras das plantas vasculares ocupavam ambientes úmidos; algas ainda eram produtoras centrais nos mares. A vegetação terrestre era simples e dispersa.', 'Mares de plataforma, recifes em recuperação e zonas costeiras eram habitats importantes. As plataformas rasas ampliaram progressivamente sua área.', 'Peixes sem mandíbulas, primeiros gnatostomados, invertebrados marinhos e os primeiros artrópodes terrestres integravam a biosfera. Graptólitos, braquiópodes, trilobitas e primeiros peixes diversificavam-se novamente.', 'O Rhuddaniano é a primeira idade do Siluriano e representa uma etapa inicial de recuperação após a extinção ordoviciana.'),
(131, 'aeroniano', 'Aeroniano', 'idade', 440.5000, 438.6000, 47, 'Aeroniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 440.5 e 438.6 milhões de anos atrás. O Aeroniano foi uma idade de recuperação e diversificação dos ecossistemas silurianos, particularmente nos mares rasos. Comunidades de braquiópodes, graptólitos e trilobitas continuaram a se reorganizar.', 'Gondwana permanecia austral; Laurentia e Báltica se aproximavam, reduzindo gradualmente o oceano Iapetus. O oceano Iapetus persistia entre massas continentais em aproximação.', 'O recuo da glaciação do final do Ordoviciano favoreceu aquecimento relativo e recuperação dos mares rasos. Condições progressivamente mais estáveis favoreceram faunas marinhas.', 'Comunidades de graptólitos, braquiópodes, trilobitas e organismos recifais se reorganizaram após a extinção. Graptólitos servem como indicadores úteis das sucessões dessa idade.', 'Formas vegetais simples e precursoras das plantas vasculares ocupavam ambientes úmidos; algas ainda eram produtoras centrais nos mares. A vegetação continental permanecia baixa e esparsa.', 'Mares de plataforma, recifes em recuperação e zonas costeiras eram habitats importantes. As plataformas e regiões costeiras propiciaram novos habitats.', 'Peixes sem mandíbulas, primeiros gnatostomados, invertebrados marinhos e os primeiros artrópodes terrestres integravam a biosfera. Trilobitas, braquiópodes, graptólitos e peixes primitivos integravam comunidades em recuperação.', 'O nome Aeroniano faz referência à região do vale do rio Aeron, no País de Gales.'),
(132, 'telychiano', 'Telychiano', 'idade', 438.6000, 432.9000, 47, 'Telychiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 438.6 e 432.9 milhões de anos atrás. O Telychiano encerrou a época Llandovery e apresentou comunidades marinhas diversificadas, com expansão de recifes e desenvolvimento dos vertebrados aquáticos.', 'Gondwana permanecia austral; Laurentia e Báltica se aproximavam, reduzindo gradualmente o oceano Iapetus. Laurentia e Báltica estavam progressivamente mais próximas.', 'O recuo da glaciação do final do Ordoviciano favoreceu aquecimento relativo e recuperação dos mares rasos. O ambiente relativamente quente favoreceu mares rasos extensos.', 'Comunidades de graptólitos, braquiópodes, trilobitas e organismos recifais se reorganizaram após a extinção. Recifes e faunas de graptólitos, braquiópodes e corais se expandiam.', 'Formas vegetais simples e precursoras das plantas vasculares ocupavam ambientes úmidos; algas ainda eram produtoras centrais nos mares. Plantas terrestres muito simples ocupavam pequenas áreas úmidas.', 'Mares de plataforma, recifes em recuperação e zonas costeiras eram habitats importantes. Plataformas e recifes ofereciam refúgios e alimento a invertebrados.', 'Peixes sem mandíbulas, primeiros gnatostomados, invertebrados marinhos e os primeiros artrópodes terrestres integravam a biosfera. Trilobitas, corais, braquiópodes e peixes sem mandíbulas conviviam com primeiros peixes mandibulados.', 'O Telychiano é a última idade do Llandovery, imediatamente anterior ao Wenlock.'),
(133, 'sheinwoodiano', 'Sheinwoodiano', 'idade', 432.9000, 430.6000, 48, 'Sheinwoodiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 432.9 e 430.6 milhões de anos atrás. O Sheinwoodiano iniciou o Wenlock e foi marcado por ecossistemas marinhos recifais importantes. Também se observam mudanças ambientais e na composição das comunidades marinhas.', 'A aproximação de Laurentia e Báltica contribuía para a formação de Laurússia, enquanto Gondwana ocupava grande parte do sul. A aproximação dos continentes do norte favorecia alterações no Iapetus.', 'Condições relativamente quentes e mares pouco profundos favoreceram extensa biodiversidade marinha. Oscilações climáticas e ambientais influenciaram os níveis do mar.', 'Recifes de corais e estromatoporoides abrigavam comunidades complexas de invertebrados e peixes. Corais e estromatoporoides sustentavam recifes, enquanto graptólitos ocupavam águas abertas.', 'Plantas vasculares primitivas de pequeno porte se expandiam por ambientes continentais úmidos; florestas altas ainda não existiam. As primeiras plantas vasculares pequenas se estabeleciam em habitats úmidos.', 'Recifes, plataformas marinhas, litorais e margens úmidas de rios ofereciam habitats aquáticos e terrestres. Recifes, plataformas carbonáticas e margens costeiras caracterizavam os ecossistemas.', 'Trilobitas, braquiópodes, crinoides, peixes primitivos e artrópodes terrestres representavam ecossistemas em evolução. Peixes primitivos, trilobitas e braquiópodes apresentavam novas associações ecológicas.', 'O Sheinwoodiano recebeu seu nome da região de Sheinwood, na Inglaterra, e corresponde ao início do Wenlock.');
INSERT INTO `geo_time` (`id`, `slug`, `name`, `type`, `begin_year`, `end_year`, `parent_id`, `summary`, `continental_configuration`, `climate`, `oceans`, `vegetation`, `environments`, `biodiversity`, `curiosities`) VALUES
(134, 'homeriano', 'Homeriano', 'idade', 430.6000, 426.7000, 48, 'Homeriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 430.6 e 426.7 milhões de anos atrás. O Homeriano concluiu o Wenlock. Os recifes marinhos continuavam oferecendo habitats complexos, enquanto plantas vasculares pequenas e artrópodes exploravam ambientes continentais úmidos.', 'A aproximação de Laurentia e Báltica contribuía para a formação de Laurússia, enquanto Gondwana ocupava grande parte do sul. Laurússia avançava em sua formação e margens continentais sofriam mudanças.', 'Condições relativamente quentes e mares pouco profundos favoreceram extensa biodiversidade marinha. Condições quentes coexistiam com episódios de perturbação ambiental marinha.', 'Recifes de corais e estromatoporoides abrigavam comunidades complexas de invertebrados e peixes. Braquiópodes, corais, graptólitos e peixes ocupavam mares de plataforma.', 'Plantas vasculares primitivas de pequeno porte se expandiam por ambientes continentais úmidos; florestas altas ainda não existiam. Plantas de pequeno porte semelhantes a Cooksonia eram parte da vegetação inicial.', 'Recifes, plataformas marinhas, litorais e margens úmidas de rios ofereciam habitats aquáticos e terrestres. Recifes e planícies litorâneas ofereciam ambientes contrastantes.', 'Trilobitas, braquiópodes, crinoides, peixes primitivos e artrópodes terrestres representavam ecossistemas em evolução. Diversos peixes, trilobitas, corais e outros invertebrados sustentavam ecossistemas silurianos.', 'O Homeriano possui registros importantes para o estudo de mudanças da fauna de graptólitos e de ecossistemas recifais.'),
(135, 'gorstiano', 'Gorstiano', 'idade', 426.7000, 425.0000, 49, 'Gorstiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 426.7 e 425 milhões de anos atrás. O Gorstiano iniciou a época Ludlow e apresentou peixes e invertebrados em diversificação. A ocupação da terra firme por pequenas plantas vasculares e artrópodes continuou avançando.', 'Laurússia estava em formação avançada a partir de Laurentia e Báltica, enquanto Gondwana permanecia uma massa austral extensa. Laurússia continuava sua consolidação tectônica.', 'Condições predominantemente quentes coexistiam com oscilações regionais do nível do mar. As condições geralmente quentes permitiam comunidades marinhas extensas.', 'Recifes e plataformas rasas mantinham faunas variadas, com braquiópodes, graptólitos e peixes de diferentes linhagens. Corais, crinoides, moluscos e graptólitos habitavam mares rasos.', 'Plantas vasculares pequenas ocupavam margens úmidas e começavam a modificar superfícies continentais. Pequenas plantas vasculares apareciam em ambientes úmidos próximos à costa.', 'Mares rasos, recifes e ambientes costeiros coexistiam com margens fluviais colonizadas por organismos terrestres. Recifes, fundos sedimentares e margens de rios eram habitats distintos.', 'Peixes com mandíbulas, trilobitas, braquiópodes, corais e artrópodes terrestres se diversificavam. Peixes com mandíbulas ganhavam diversidade, ao lado de trilobitas e braquiópodes.', 'O Gorstiano recebeu seu nome da região de Gorsty, no País de Gales, e corresponde à primeira idade do Ludlow.'),
(136, 'ludfordiano', 'Ludfordiano', 'idade', 425.0000, 422.7000, 49, 'Ludfordiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 425 e 422.7 milhões de anos atrás. O Ludfordiano encerrou a época Ludlow e registrou uma diversificação contínua de peixes, organismos recifais e pequenas plantas terrestres. Seus depósitos mostram mudanças ambientais em diferentes mares silurianos.', 'Laurússia estava em formação avançada a partir de Laurentia e Báltica, enquanto Gondwana permanecia uma massa austral extensa. Gondwana permaneceu austral, e Laurússia ocupava extensas áreas setentrionais.', 'Condições predominantemente quentes coexistiam com oscilações regionais do nível do mar. Mudanças regionais do nível dos mares afetaram comunidades marinhas.', 'Recifes e plataformas rasas mantinham faunas variadas, com braquiópodes, graptólitos e peixes de diferentes linhagens. Peixes primitivos e invertebrados caracterizavam plataformas e mares costeiros.', 'Plantas vasculares pequenas ocupavam margens úmidas e começavam a modificar superfícies continentais. Plantas vasculares pequenas ampliavam a ocupação de regiões úmidas.', 'Mares rasos, recifes e ambientes costeiros coexistiam com margens fluviais colonizadas por organismos terrestres. Litorais, recifes e rios sustentavam fauna aquática e alguns organismos terrestres.', 'Peixes com mandíbulas, trilobitas, braquiópodes, corais e artrópodes terrestres se diversificavam. Peixes de diferentes linhagens, graptólitos, braquiópodes e artrópodes coexistiam.', 'O Ludfordiano foi a última idade do Ludlow e antecede o Pridoli, época siluriana sem estágios formalmente definidos.'),
(137, 'lochkoviano', 'Lochkoviano', 'idade', 419.6200, 413.0200, 51, 'Lochkoviano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 419.62 e 413.02 milhões de anos atrás. O Lochkoviano iniciou o Devoniano, período reconhecido pela grande diversificação dos peixes. Plantas terrestres primitivas continuaram sua expansão em regiões úmidas e costeiras.', 'Euramérica se consolidava em latitudes próximas ao equador, enquanto Gondwana ocupava grande parte do hemisfério sul. Laurússia se consolidava enquanto Gondwana ocupava extensas latitudes austrais.', 'Muitas regiões possuíam clima quente; a distribuição da umidade influenciava as primeiras comunidades terrestres mais extensas. Regiões tropicais eram relativamente quentes, favoráveis a ambientes marinhos e fluviais.', 'Mares rasos e recifes abrigavam diversos peixes, braquiópodes, trilobitas e corais. Plataformas e recifes ofereciam habitats variados para peixes e invertebrados.', 'Plantas vasculares primitivas, incluindo licófitas e linhagens relacionadas às traqueófitas iniciais, se difundiam em ambientes úmidos. Plantas vasculares simples ainda não constituíam florestas altas.', 'Litorais, estuários, sistemas fluviais, lagos e mares de plataforma sustentavam organismos terrestres e aquáticos. Margens de lagos e rios passaram a oferecer superfícies mais estáveis para plantas.', 'Peixes sem mandíbulas, placodermos primitivos e peixes ósseos coexistiam com artrópodes terrestres e plantas pioneiras. Peixes placodermos primitivos, outros vertebrados aquáticos e artrópodes terrestres coexistiam.', 'O Lochkoviano recebe seu nome de uma região próxima a Praga, na República Tcheca, e marca o início do Devoniano.'),
(138, 'pragiano', 'Pragiano', 'idade', 413.0200, 410.6200, 51, 'Pragiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 413.02 e 410.62 milhões de anos atrás. O Pragiano corresponde à segunda idade do Devoniano Inferior e apresentou diversificação de peixes e plantas terrestres vasculares. A vida fora da água avançava gradualmente em regiões úmidas.', 'Euramérica se consolidava em latitudes próximas ao equador, enquanto Gondwana ocupava grande parte do hemisfério sul. Gondwana e Laurússia permaneciam como grandes massas continentais separadas.', 'Muitas regiões possuíam clima quente; a distribuição da umidade influenciava as primeiras comunidades terrestres mais extensas. Condições relativamente quentes favoreciam a vegetação junto aos sistemas fluviais.', 'Mares rasos e recifes abrigavam diversos peixes, braquiópodes, trilobitas e corais. Peixes e invertebrados ocupavam recifes e mares de plataforma.', 'Plantas vasculares primitivas, incluindo licófitas e linhagens relacionadas às traqueófitas iniciais, se difundiam em ambientes úmidos. Vegetação baixa de traqueófitas primitivas se tornava mais diversificada.', 'Litorais, estuários, sistemas fluviais, lagos e mares de plataforma sustentavam organismos terrestres e aquáticos. Rios, lagos e zonas costeiras eram locais importantes para a colonização terrestre.', 'Peixes sem mandíbulas, placodermos primitivos e peixes ósseos coexistiam com artrópodes terrestres e plantas pioneiras. Placodermos iniciais, peixes sem mandíbulas e outros grupos aquáticos coexistiam com artrópodes.', 'O Pragiano recebeu seu nome de Praga e integra a expansão da vida continental no Devoniano Inferior.'),
(139, 'emsiano', 'Emsiano', 'idade', 410.6200, 393.4700, 51, 'Emsiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 410.62 e 393.47 milhões de anos atrás. O Emsiano encerrou o Devoniano Inferior, quando os peixes apresentavam grande diversidade e as plantas vasculares continuavam evoluindo. Formas vegetais mais complexas passaram a ocupar áreas continentais maiores.', 'Euramérica se consolidava em latitudes próximas ao equador, enquanto Gondwana ocupava grande parte do hemisfério sul. Euramérica e Gondwana continuavam a influenciar os mares e as rotas biogeográficas.', 'Muitas regiões possuíam clima quente; a distribuição da umidade influenciava as primeiras comunidades terrestres mais extensas. A umidade local favorecia a expansão de comunidades vegetais próximas à água.', 'Mares rasos e recifes abrigavam diversos peixes, braquiópodes, trilobitas e corais. Recifes e mares rasos abrigavam peixes de diferentes linhagens, braquiópodes e trilobitas.', 'Plantas vasculares primitivas, incluindo licófitas e linhagens relacionadas às traqueófitas iniciais, se difundiam em ambientes úmidos. Traqueófitas com caules e sistemas de condução diversificavam-se progressivamente.', 'Litorais, estuários, sistemas fluviais, lagos e mares de plataforma sustentavam organismos terrestres e aquáticos. Planícies fluviais úmidas abrigavam comunidades vegetais pioneiras.', 'Peixes sem mandíbulas, placodermos primitivos e peixes ósseos coexistiam com artrópodes terrestres e plantas pioneiras. Peixes ósseos, placodermos e artrópodes terrestres se diversificavam.', 'O Emsiano é a última idade do Devoniano Inferior e antecede o surgimento de paisagens florestais cada vez mais complexas no Devoniano Médio.'),
(140, 'eifeliano', 'Eifeliano', 'idade', 393.4700, 387.9500, 52, 'Eifeliano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 393.47 e 387.95 milhões de anos atrás. O Eifeliano iniciou o Devoniano Médio e acompanhou a intensificação da evolução de peixes e plantas de maior porte. A estrutura das comunidades terrestres começou a se transformar de modo mais evidente.', 'Euramérica ocupava áreas tropicais e Gondwana permanecia austral, com importantes mares entre as grandes massas continentais. Plataformas marinhas em áreas tropicais favoreciam recifes extensos.', 'Condições quentes, com variações de umidade, favoreceram o desenvolvimento das primeiras paisagens arbóreas. Temperaturas relativamente elevadas ajudavam no desenvolvimento das primeiras formas arbóreas.', 'Recifes de corais e estromatoporoides, plataformas continentais e ambientes pelágicos sustentavam grande diversidade de peixes. Recifes de corais e estromatoporoides sustentavam biodiversidade marinha elevada.', 'Plantas vasculares de maior porte e formas arbóreas primitivas, como as relacionadas a Wattieza, começaram a formar ambientes florestais. Plantas vasculares aumentaram sua estatura e complexidade em muitos habitats.', 'Rios, lagos e planícies úmidas passaram a apresentar cobertura vegetal mais complexa, ao lado de extensos recifes marinhos. Planícies fluviais e áreas pantanosas apresentavam vegetação mais variada.', 'Placodermos, peixes ósseos e cartilaginosos, trilobitas, corais e artrópodes terrestres compunham ecossistemas diversificados. Placodermos, peixes ósseos, trilobitas e invertebrados recifais eram comuns.', 'O Eifeliano recebeu seu nome da região de Eifel, na Alemanha, e é a primeira idade do Devoniano Médio.'),
(141, 'givetiano', 'Givetiano', 'idade', 387.9500, 382.3100, 52, 'Givetiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 387.95 e 382.31 milhões de anos atrás. O Givetiano encerrou o Devoniano Médio e foi marcado por florestas primitivas e ecossistemas marinhos ricos em peixes. Formas arbóreas antigas e sistemas radiculares mais elaborados começaram a alterar o ambiente terrestre.', 'Euramérica ocupava áreas tropicais e Gondwana permanecia austral, com importantes mares entre as grandes massas continentais. A distribuição de mares entre Euramérica e Gondwana favorecia comunidades recifais extensas.', 'Condições quentes, com variações de umidade, favoreceram o desenvolvimento das primeiras paisagens arbóreas. Regiões equatoriais úmidas sustentavam desenvolvimento arbóreo crescente.', 'Recifes de corais e estromatoporoides, plataformas continentais e ambientes pelágicos sustentavam grande diversidade de peixes. Peixes placodermos e recifes com corais e estromatoporoides apresentavam grande diversidade.', 'Plantas vasculares de maior porte e formas arbóreas primitivas, como as relacionadas a Wattieza, começaram a formar ambientes florestais. Formas semelhantes a Wattieza e outras plantas primitivas integravam paisagens florestais iniciais.', 'Rios, lagos e planícies úmidas passaram a apresentar cobertura vegetal mais complexa, ao lado de extensos recifes marinhos. Solos e planícies fluviais tornavam-se mais complexos devido à vegetação.', 'Placodermos, peixes ósseos e cartilaginosos, trilobitas, corais e artrópodes terrestres compunham ecossistemas diversificados. Placodermos, outros peixes, trilobitas e artrópodes terrestres continuavam diversos.', 'O Givetiano registra uma etapa importante na expansão das primeiras florestas, que modificaram solos e o ciclo de nutrientes.'),
(142, 'frasniano', 'Frasniano', 'idade', 382.3100, 372.1500, 53, 'Frasniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 382.31 e 372.15 milhões de anos atrás. O Frasniano iniciou o Devoniano Superior e viu grandes peixes predadores e extensas comunidades recifais. Seu final foi atingido pela crise de extinção conhecida como eventos Kellwasser.', 'Gondwana e Euramérica continuavam movimentos relativos que preparavam processos futuros de união continental. Regiões equatoriais de Euramérica concentravam plataformas e sistemas sedimentares.', 'Oscilações climáticas e mudanças no ciclo do carbono acompanharam a expansão das florestas e episódios de crise ambiental. Alterações climáticas e oceânicas contribuíram para instabilidade perto do fim da idade.', 'Episódios de anoxia e perturbações ecológicas afetaram recifes e vários grupos de invertebrados marinhos. Recifes sofreram perdas importantes durante episódios de baixa oxigenação marinha.', 'Florestas de Archaeopteris, licófitas e outros grupos vasculares transformavam solos e paisagens continentais. Florestas de plantas vasculares de maior porte se expandiam.', 'Rios, várzeas, lagos, mares rasos e recifes forneciam habitats para peixes e tetrápodes iniciais. Ambientes marinhos recifais e planícies fluviais eram cenários de mudanças ecológicas.', 'Placodermos, peixes de nadadeiras lobadas e tetrápodes antigos coexistiam com artrópodes terrestres e comunidades marinhas ameaçadas por crises. Placodermos como Dunkleosteus coexistiam com outros peixes e invertebrados; diferentes grupos sofreram perdas no final.', 'Os eventos Kellwasser, próximos ao limite Frasniano-Famenniano, afetaram fortemente os recifes do Devoniano.'),
(143, 'famenniano', 'Famenniano', 'idade', 372.1500, 358.8600, 53, 'Famenniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 372.15 e 358.86 milhões de anos atrás. O Famenniano encerrou o Devoniano e ocorreu após uma grande crise nos ecossistemas marinhos. Na terra firme, florestas e vertebrados com membros continuaram sua evolução, enquanto o período terminou com o evento de extinção Hangenberg.', 'Gondwana e Euramérica continuavam movimentos relativos que preparavam processos futuros de união continental. A movimentação continental continuava preparando colisões que mais tarde influenciariam Pangeia.', 'Oscilações climáticas e mudanças no ciclo do carbono acompanharam a expansão das florestas e episódios de crise ambiental. Ocorreram mudanças climáticas e episódios de instabilidade ambiental no final do Devoniano.', 'Episódios de anoxia e perturbações ecológicas afetaram recifes e vários grupos de invertebrados marinhos. Grupos marinhos sofreram novas perdas perto do fim da idade.', 'Florestas de Archaeopteris, licófitas e outros grupos vasculares transformavam solos e paisagens continentais. Florestas de Archaeopteris e outras plantas vasculares influenciavam os ecossistemas continentais.', 'Rios, várzeas, lagos, mares rasos e recifes forneciam habitats para peixes e tetrápodes iniciais. Rios e áreas alagadas abrigavam peixes de nadadeiras lobadas e tetrápodes antigos.', 'Placodermos, peixes de nadadeiras lobadas e tetrápodes antigos coexistiam com artrópodes terrestres e comunidades marinhas ameaçadas por crises. Tetrápodes como Acanthostega e Ichthyostega viveram durante o Devoniano Superior, junto a numerosos peixes.', 'A crise de Hangenberg, próxima ao limite Devoniano-Carbonífero, afetou importantes linhagens aquáticas e terrestres.'),
(144, 'tournaisiano', 'Tournaisiano', 'idade', 358.8600, 346.7000, 54, 'Tournaisiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 358.86 e 346.7 milhões de anos atrás. O Tournaisiano iniciou o Carbonífero após as perturbações do final do Devoniano. Ecossistemas marinhos se reorganizaram, e as plantas terrestres continuaram ocupando áreas amplas.', 'Gondwana permanecia austral, enquanto Euramérica ocupava latitudes tropicais; colisões futuras contribuiriam para a montagem de Pangeia. Gondwana ainda permanecia ao sul, com Euramérica em latitudes tropicais.', 'Regiões equatoriais eram frequentemente quentes e úmidas, enquanto partes de Gondwana enfrentavam condições glaciais. Condições tropicais úmidas coexistiam com climas mais frios em partes austrais.', 'Mares rasos carbonáticos sustentavam crinoides, corais, braquiópodes, moluscos e peixes. Mares rasos apresentavam braquiópodes, crinoides e outros organismos em recuperação.', 'Licófitas, esfenófitas, samambaias e plantas com sementes compunham comunidades vegetais crescentes em ambientes úmidos. Licófitas, samambaias e outras plantas vasculares ocupavam ambientes alagados.', 'Plataformas marinhas, recifes, rios, deltas e planícies alagadas caracterizavam diferentes regiões. Deltas, plataformas carbonáticas e rios sustentavam biodiversidade diversificada.', 'Crinoides e outros invertebrados marinhos eram abundantes; nos continentes viviam anfíbios, artrópodes e linhagens iniciais de amniotas. Peixes, crinoides, braquiópodes, anfíbios primitivos e artrópodes estavam presentes.', 'O Tournaisiano é a primeira idade do Carbonífero e faz parte do Mississippiano.'),
(145, 'viseano', 'Viseano', 'idade', 346.7000, 330.3000, 54, 'Viseano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 346.7 e 330.3 milhões de anos atrás. O Viseano foi uma fase de grande desenvolvimento dos mares rasos carbonáticos e da vida terrestre. Crinoides e outros invertebrados marinhos eram abundantes, enquanto os vertebrados terrestres ampliavam sua diversidade.', 'Gondwana permanecia austral, enquanto Euramérica ocupava latitudes tropicais; colisões futuras contribuiriam para a montagem de Pangeia. Gondwana e Euramérica mantinham movimentos tectônicos relacionados à formação futura de Pangeia.', 'Regiões equatoriais eram frequentemente quentes e úmidas, enquanto partes de Gondwana enfrentavam condições glaciais. Regiões equatoriais quentes e úmidas contrastavam com zonas glaciais austrais.', 'Mares rasos carbonáticos sustentavam crinoides, corais, braquiópodes, moluscos e peixes. Depósitos de calcários testemunham recifes e comunidades ricas em crinoides.', 'Licófitas, esfenófitas, samambaias e plantas com sementes compunham comunidades vegetais crescentes em ambientes úmidos. Florestas de plantas vasculares se desenvolviam em regiões alagadas.', 'Plataformas marinhas, recifes, rios, deltas e planícies alagadas caracterizavam diferentes regiões. Plataformas marinhas e planícies pantanosas eram comuns em diferentes regiões.', 'Crinoides e outros invertebrados marinhos eram abundantes; nos continentes viviam anfíbios, artrópodes e linhagens iniciais de amniotas. Crinoides, corais, peixes, anfíbios e artrópodes ampliavam a complexidade ecológica.', 'O nome Viseano tem origem em Visé, na Bélgica, e seus calcários são importantes para a paleontologia do Carbonífero.'),
(146, 'serpukhoviano', 'Serpukhoviano', 'idade', 330.3000, 323.4000, 54, 'Serpukhoviano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 330.3 e 323.4 milhões de anos atrás. O Serpukhoviano foi a última idade do Mississippiano, antecedendo o Pensilvaniano. Ambientes úmidos sustentavam comunidades vegetais densas e os animais terrestres continuaram a se diversificar.', 'Gondwana permanecia austral, enquanto Euramérica ocupava latitudes tropicais; colisões futuras contribuiriam para a montagem de Pangeia. As massas continentais avançavam gradualmente em direção à união de Pangeia.', 'Regiões equatoriais eram frequentemente quentes e úmidas, enquanto partes de Gondwana enfrentavam condições glaciais. Oscilações climáticas relacionadas às glaciações austrais alteravam o nível marinho.', 'Mares rasos carbonáticos sustentavam crinoides, corais, braquiópodes, moluscos e peixes. Mares rasos abrigavam braquiópodes, peixes, crinoides e outros invertebrados.', 'Licófitas, esfenófitas, samambaias e plantas com sementes compunham comunidades vegetais crescentes em ambientes úmidos. Plantas vasculares formavam pântanos e florestas em latitudes tropicais.', 'Plataformas marinhas, recifes, rios, deltas e planícies alagadas caracterizavam diferentes regiões. Planícies deltaicas e pântanos eram ambientes de deposição de matéria orgânica.', 'Crinoides e outros invertebrados marinhos eram abundantes; nos continentes viviam anfíbios, artrópodes e linhagens iniciais de amniotas. Anfíbios, artrópodes e primeiros amniotas integravam a diversificação continental.', 'O Serpukhoviano recebe seu nome de Serpukhov, na Rússia, e encerra o Mississippiano na subdivisão internacional.'),
(147, 'bashkiriano', 'Bashkiriano', 'idade', 323.4000, 315.2000, 55, 'Bashkiriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 323.4 e 315.2 milhões de anos atrás. O Bashkiriano iniciou o Pensilvaniano e foi marcado pela expansão de extensas florestas pantanosas em regiões tropicais. Comunidades de anfíbios, amniotas e artrópodes ocupavam os continentes.', 'A aproximação de Gondwana e Euramérica contribuiu para a formação progressiva de Pangeia, enquanto extensas regiões equatoriais eram alagadiças. A aproximação de Gondwana e Euramérica intensificava processos de formação montanhosa.', 'Regiões tropicais úmidas coexistiam com glaciações austrais e oscilações do nível do mar; mudanças climáticas alteraram as florestas. Climas quentes e úmidos equatoriais coexistiam com glaciações no hemisfério sul.', 'Mares rasos transgrediam e regrediam sobre continentes, sustentando foraminíferos, braquiópodes, crinoides e peixes. Oscilações do nível marinho produziram ciclos de depósitos costeiros e continentais.', 'Florestas carboníferas reuniam licófitas arborescentes, cavalinhas, samambaias e plantas com sementes. Licófitas arborescentes, samambaias e cavalinhas dominavam muitas florestas.', 'Pântanos, planícies deltaicas, rios e florestas equatoriais acumulavam matéria orgânica que originaria carvão. Pântanos, lagos e deltas acumularam sedimentos e matéria vegetal.', 'Anfíbios, primeiros amniotas, artrópodes de grande porte e diferentes invertebrados marinhos se diversificavam. Anfíbios, amniotas primitivos e diversos artrópodes encontravam habitats em florestas úmidas.', 'O Bashkiriano inicia a subdivisão Pensilvaniano do Carbonífero e recebe seu nome da região de Bashkortostão, na Rússia.'),
(148, 'moscoviano', 'Moscoviano', 'idade', 315.2000, 307.0000, 55, 'Moscoviano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 315.2 e 307 milhões de anos atrás. O Moscoviano apresentou extensas florestas equatoriais, formação de depósitos de carvão e diversificação dos primeiros amniotas. Mudanças climáticas graduais também afetaram a distribuição desses ecossistemas.', 'A aproximação de Gondwana e Euramérica contribuiu para a formação progressiva de Pangeia, enquanto extensas regiões equatoriais eram alagadiças. As colisões continentais contribuíam para a montagem de Pangeia.', 'Regiões tropicais úmidas coexistiam com glaciações austrais e oscilações do nível do mar; mudanças climáticas alteraram as florestas. A alternância entre períodos mais úmidos e secos influenciava a extensão dos pântanos.', 'Mares rasos transgrediam e regrediam sobre continentes, sustentando foraminíferos, braquiópodes, crinoides e peixes. Regressões e transgressões marinhas produziram depósitos alternados.', 'Florestas carboníferas reuniam licófitas arborescentes, cavalinhas, samambaias e plantas com sementes. Licófitas gigantes, cavalinhas e samambaias formavam extensas florestas.', 'Pântanos, planícies deltaicas, rios e florestas equatoriais acumulavam matéria orgânica que originaria carvão. Planícies pantanosas, deltas e rios concentravam matéria orgânica.', 'Anfíbios, primeiros amniotas, artrópodes de grande porte e diferentes invertebrados marinhos se diversificavam. Anfíbios, amniotas e artrópodes de grande porte eram importantes componentes terrestres.', 'O Moscoviano recebe seu nome da região de Moscou, na Rússia, e está ligado à formação de importantes depósitos de carvão.'),
(149, 'kasimoviano', 'Kasimoviano', 'idade', 307.0000, 303.7000, 55, 'Kasimoviano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 307 e 303.7 milhões de anos atrás. O Kasimoviano ocorreu durante uma fase de transformações das florestas tropicais carboníferas. Oscilações climáticas e alterações da umidade afetavam a distribuição dos ambientes pantanosos.', 'A aproximação de Gondwana e Euramérica contribuiu para a formação progressiva de Pangeia, enquanto extensas regiões equatoriais eram alagadiças. A Pangeia se consolidava progressivamente, alterando a circulação de umidade pelo interior continental.', 'Regiões tropicais úmidas coexistiam com glaciações austrais e oscilações do nível do mar; mudanças climáticas alteraram as florestas. Episódios de secura em algumas regiões contribuíram para mudanças nos ecossistemas florestais.', 'Mares rasos transgrediam e regrediam sobre continentes, sustentando foraminíferos, braquiópodes, crinoides e peixes. O nível do mar continuava oscilando em conexão com glaciações austrais.', 'Florestas carboníferas reuniam licófitas arborescentes, cavalinhas, samambaias e plantas com sementes. Comunidades dominadas por licófitas e samambaias passaram por transformações regionais.', 'Pântanos, planícies deltaicas, rios e florestas equatoriais acumulavam matéria orgânica que originaria carvão. Alguns pântanos recuaram, permitindo a expansão de habitats mais secos.', 'Anfíbios, primeiros amniotas, artrópodes de grande porte e diferentes invertebrados marinhos se diversificavam. Amniotas e artrópodes terrestres ocuparam novos ambientes, ao lado de anfíbios.', 'O colapso de florestas tropicais do Carbonífero foi um processo complexo próximo dessa parte do Pensilvaniano, associado a mudanças climáticas.'),
(150, 'gzheliano', 'Gzheliano', 'idade', 303.7000, 298.9000, 55, 'Gzheliano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 303.7 e 298.9 milhões de anos atrás. O Gzheliano foi a última idade do Carbonífero e antecedeu o Permiano. A formação de Pangeia e condições mais secas em várias regiões transformaram os ecossistemas terrestres.', 'A aproximação de Gondwana e Euramérica contribuiu para a formação progressiva de Pangeia, enquanto extensas regiões equatoriais eram alagadiças. Pangeia aproximava-se de sua grande configuração continental, com extensas áreas interiores.', 'Regiões tropicais úmidas coexistiam com glaciações austrais e oscilações do nível do mar; mudanças climáticas alteraram as florestas. Condições sazonais e mais secas se tornavam importantes em determinadas regiões.', 'Mares rasos transgrediam e regrediam sobre continentes, sustentando foraminíferos, braquiópodes, crinoides e peixes. Mares rasos continuavam sustentando peixes, moluscos e invertebrados.', 'Florestas carboníferas reuniam licófitas arborescentes, cavalinhas, samambaias e plantas com sementes. Coníferas e outras plantas com sementes ganharam espaço onde florestas pantanosas recuavam.', 'Pântanos, planícies deltaicas, rios e florestas equatoriais acumulavam matéria orgânica que originaria carvão. Florestas sazonais, pântanos remanescentes e planícies áridas coexistiam.', 'Anfíbios, primeiros amniotas, artrópodes de grande porte e diferentes invertebrados marinhos se diversificavam. Amniotas, anfíbios e artrópodes terrestres continuavam a se diversificar.', 'O Gzheliano encerra o Pensilvaniano e o Carbonífero, antecedendo a expansão dos ambientes áridos do Permiano.'),
(151, 'asseliano', 'Asseliano', 'idade', 298.9000, 293.5200, 19, 'Asseliano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 298.9 e 293.52 milhões de anos atrás. O Asseliano iniciou o Permiano em um cenário de formação de Pangeia e transformação dos ecossistemas continentais. Sinapsídeos e amniotas diversificavam-se em ambientes de umidade variável.', 'A Pangeia ocupava extensa parte do planeta e era cercada pelo Panthalassa; o domínio de Tétis formava mares tropicais. O supercontinente reunia grandes áreas de interior distante dos mares.', 'A aridez continental aumentava em várias regiões, embora áreas úmidas e vestígios de glaciações ainda persistissem. A transição do Carbonífero preservava contrastes entre regiões úmidas e ambientes mais secos.', 'Mares tropicais abrigavam braquiópodes, ammonoides, peixes, equinodermos e comunidades recifais. Mares tropicais apresentavam braquiópodes, moluscos e organismos recifais.', 'Coníferas e outras gimnospermas expandiram-se, enquanto samambaias e plantas úmidas permaneceram junto a corpos de água. Florestas com plantas de sementes ganhavam importância em algumas áreas.', 'Florestas sazonais, deltas, desertos, rios e lagos formavam mosaicos ambientais na Pangeia. Planícies úmidas e áreas secas existiam lado a lado.', 'Sinapsídeos de diferentes linhagens, répteis, anfíbios, insetos e organismos marinhos compunham ecossistemas terrestres e aquáticos. Sinapsídeos basais, anfíbios e répteis ocupavam diferentes nichos terrestres.', 'O Asseliano representa a primeira idade do Permiano, cujo início é reconhecido por critérios estratigráficos internacionais.'),
(152, 'sakmariano', 'Sakmariano', 'idade', 293.5200, 290.1000, 19, 'Sakmariano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 293.52 e 290.1 milhões de anos atrás. O Sakmariano acompanhou a diversificação dos vertebrados terrestres no Permiano inicial. As paisagens de Pangeia apresentavam condições climáticas contrastantes e novos ambientes sazonais.', 'A Pangeia ocupava extensa parte do planeta e era cercada pelo Panthalassa; o domínio de Tétis formava mares tropicais. Os interiores de Pangeia começavam a formar extensas áreas secas.', 'A aridez continental aumentava em várias regiões, embora áreas úmidas e vestígios de glaciações ainda persistissem. A aridez avançava em algumas regiões, embora habitats úmidos persistissem.', 'Mares tropicais abrigavam braquiópodes, ammonoides, peixes, equinodermos e comunidades recifais. Mares rasos mantinham braquiópodes, amonoides e outros invertebrados.', 'Coníferas e outras gimnospermas expandiram-se, enquanto samambaias e plantas úmidas permaneceram junto a corpos de água. Coníferas e outras gimnospermas expandiam-se nos ambientes sazonais.', 'Florestas sazonais, deltas, desertos, rios e lagos formavam mosaicos ambientais na Pangeia. Rios, lagos, planícies e áreas semiáridas formavam mosaicos ambientais.', 'Sinapsídeos de diferentes linhagens, répteis, anfíbios, insetos e organismos marinhos compunham ecossistemas terrestres e aquáticos. Sinapsídeos, anfíbios e diferentes répteis participavam das cadeias terrestres.', 'O Sakmariano é uma idade do Cisuraliano e possui nome derivado do rio Sakmara, na Rússia.'),
(153, 'artinskiano', 'Artinskiano', 'idade', 290.1000, 283.3000, 19, 'Artinskiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 290.1 e 283.3 milhões de anos atrás. O Artinskiano foi uma fase de diversificação dos sinapsídeos e das comunidades terrestres permianas. A Pangeia apresentava áreas áridas cada vez mais amplas em suas regiões interiores.', 'A Pangeia ocupava extensa parte do planeta e era cercada pelo Panthalassa; o domínio de Tétis formava mares tropicais. Os continentes permaneciam reunidos numa extensa massa continental.', 'A aridez continental aumentava em várias regiões, embora áreas úmidas e vestígios de glaciações ainda persistissem. As diferenças sazonais de temperatura e umidade influenciavam a distribuição dos organismos.', 'Mares tropicais abrigavam braquiópodes, ammonoides, peixes, equinodermos e comunidades recifais. Mares tropicais sustentavam peixes, amonoides e invertebrados de concha.', 'Coníferas e outras gimnospermas expandiram-se, enquanto samambaias e plantas úmidas permaneceram junto a corpos de água. Gimnospermas adaptadas à secura ganhavam importância nas paisagens.', 'Florestas sazonais, deltas, desertos, rios e lagos formavam mosaicos ambientais na Pangeia. Planícies sazonais e sistemas fluviais eram habitats terrestres comuns.', 'Sinapsídeos de diferentes linhagens, répteis, anfíbios, insetos e organismos marinhos compunham ecossistemas terrestres e aquáticos. Sinapsídeos como formas do grupo dos esfenacodontídeos ganharam destaque em certos ecossistemas.', 'O Artinskiano recebeu seu nome da região de Arti, nos montes Urais, Rússia.'),
(154, 'kunguriano', 'Kunguriano', 'idade', 283.3000, 274.4000, 19, 'Kunguriano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 283.3 e 274.4 milhões de anos atrás. O Kunguriano encerrou o Cisuraliano e foi marcado por ecossistemas terrestres com sinapsídeos, répteis e anfíbios. Regiões interiores de Pangeia tornaram-se particularmente secas.', 'A Pangeia ocupava extensa parte do planeta e era cercada pelo Panthalassa; o domínio de Tétis formava mares tropicais. A Pangeia apresentava grande extensão de regiões continentais afastadas do oceano.', 'A aridez continental aumentava em várias regiões, embora áreas úmidas e vestígios de glaciações ainda persistissem. A aridez em muitas regiões favoreceu animais e plantas adaptados a regimes sazonais.', 'Mares tropicais abrigavam braquiópodes, ammonoides, peixes, equinodermos e comunidades recifais. Mares rasos e bacias costeiras continuavam oferecendo habitats variados.', 'Coníferas e outras gimnospermas expandiram-se, enquanto samambaias e plantas úmidas permaneceram junto a corpos de água. Coníferas e outras plantas com sementes compunham a flora de ambientes mais secos.', 'Florestas sazonais, deltas, desertos, rios e lagos formavam mosaicos ambientais na Pangeia. Desertos, sistemas fluviais sazonais e planícies interiores tornavam-se característicos.', 'Sinapsídeos de diferentes linhagens, répteis, anfíbios, insetos e organismos marinhos compunham ecossistemas terrestres e aquáticos. Diferentes linhagens de sinapsídeos ocuparam papéis de grandes herbívoros e predadores.', 'O Kunguriano é a última idade do Cisuraliano e possui nome associado à região de Kungur, na Rússia.'),
(155, 'roadiano', 'Roadiano', 'idade', 274.4000, 266.9000, 20, 'Roadiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 274.4 e 266.9 milhões de anos atrás. O Roadiano iniciou o Guadalupiano e acompanhou mudanças nos ecossistemas terrestres dominados por diferentes sinapsídeos. Os ambientes permianos apresentavam contrastes entre desertos e regiões mais úmidas.', 'Pangeia reunia quase todas as terras emersas; o Panthalassa e mares associados a Tétis dominavam os ambientes oceânicos. Pangeia permanecia consolidada, com mares nas margens continentais.', 'O interior continental era frequentemente árido, enquanto mudanças climáticas regionais afetavam as comunidades biológicas. Regimes secos e sazonais continuavam frequentes.', 'Amonóides, braquiópodes, peixes e invertebrados ocupavam os mares, que passaram por perturbações ambientais no fim do intervalo. Mares de plataforma mantinham peixes, braquiópodes e amonoides.', 'Coníferas, pteridospermas e outras gimnospermas ocupavam regiões secas, ao lado de vegetação adaptada a áreas úmidas. Gimnospermas e plantas de regiões úmidas coexistiam conforme o ambiente.', 'Desertos, planícies sazonais, regiões costeiras e bacias de água doce caracterizavam diferentes áreas do supercontinente. Desertos e planícies fluviais ofereciam habitats distintos.', 'Terápsidos, outros sinapsídeos, anfíbios e répteis diversificavam-se; os oceanos abrigavam numerosas comunidades de invertebrados. Sinapsídeos e répteis terrestres se diversificavam, juntamente com fauna aquática.', 'O Roadiano recebeu seu nome da região de Road Canyon, no Texas, Estados Unidos, onde existem rochas importantes para sua definição.'),
(156, 'wordiano', 'Wordiano', 'idade', 266.9000, 264.2800, 20, 'Wordiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 266.9 e 264.28 milhões de anos atrás. O Wordiano foi a segunda idade do Guadalupiano, com comunidades diversificadas de vertebrados terrestres e organismos marinhos. Transformações evolutivas contribuíram para a crescente importância dos terápsidos.', 'Pangeia reunia quase todas as terras emersas; o Panthalassa e mares associados a Tétis dominavam os ambientes oceânicos. Pangeia continuava ocupando grande parte das terras emersas.', 'O interior continental era frequentemente árido, enquanto mudanças climáticas regionais afetavam as comunidades biológicas. O interior continental apresentava amplas áreas secas e sazonais.', 'Amonóides, braquiópodes, peixes e invertebrados ocupavam os mares, que passaram por perturbações ambientais no fim do intervalo. Braquiópodes, amonoides e outros invertebrados ocupavam os mares tropicais.', 'Coníferas, pteridospermas e outras gimnospermas ocupavam regiões secas, ao lado de vegetação adaptada a áreas úmidas. Coníferas e outras gimnospermas predominavam em áreas mais secas.', 'Desertos, planícies sazonais, regiões costeiras e bacias de água doce caracterizavam diferentes áreas do supercontinente. Planícies áridas, rios e mares costeiros formavam diferentes ecossistemas.', 'Terápsidos, outros sinapsídeos, anfíbios e répteis diversificavam-se; os oceanos abrigavam numerosas comunidades de invertebrados. Terápsidos e outros sinapsídeos passaram por mudanças de composição faunística.', 'O Wordiano recebeu seu nome de Word Mountain, no Texas, e é a idade intermediária do Guadalupiano.'),
(157, 'capitaniano', 'Capitaniano', 'idade', 264.2800, 259.8570, 20, 'Capitaniano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 264.28 e 259.857 milhões de anos atrás. O Capitaniano encerrou o Guadalupiano e foi marcado por transformações ambientais importantes. Uma crise ecológica no fim da idade afetou comunidades marinhas e terrestres.', 'Pangeia reunia quase todas as terras emersas; o Panthalassa e mares associados a Tétis dominavam os ambientes oceânicos. Pangeia continuava reunida e os mares de Tétis apresentavam importantes depósitos marinhos.', 'O interior continental era frequentemente árido, enquanto mudanças climáticas regionais afetavam as comunidades biológicas. Mudanças climáticas e episódios de aquecimento contribuíram para perturbações ambientais.', 'Amonóides, braquiópodes, peixes e invertebrados ocupavam os mares, que passaram por perturbações ambientais no fim do intervalo. Reduções de oxigênio e outras alterações oceânicas afetaram organismos marinhos.', 'Coníferas, pteridospermas e outras gimnospermas ocupavam regiões secas, ao lado de vegetação adaptada a áreas úmidas. A vegetação continental incluía gimnospermas adaptadas a ambientes sazonais.', 'Desertos, planícies sazonais, regiões costeiras e bacias de água doce caracterizavam diferentes áreas do supercontinente. Plataformas marinhas e planícies continentais sofreram mudanças ecológicas.', 'Terápsidos, outros sinapsídeos, anfíbios e répteis diversificavam-se; os oceanos abrigavam numerosas comunidades de invertebrados. Terápsidos, outros sinapsídeos e diversos invertebrados foram afetados por crises ambientais.', 'A chamada crise do final do Capitaniano é discutida como um evento importante de perda de biodiversidade anterior à extinção do fim do Permiano.'),
(158, 'wuchiapingiano', 'Wuchiapingiano', 'idade', 259.8570, 254.1400, 21, 'Wuchiapingiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 259.857 e 254.14 milhões de anos atrás. O Wuchiapingiano iniciou a última época do Permiano, o Lopingiano. Os ecossistemas terrestres eram ocupados por diversos terápsidos, enquanto os mares abrigavam comunidades ricas em invertebrados.', 'A Pangeia permanecia reunida e cercada pelo Panthalassa, com o mar de Tétis influenciando importantes regiões tropicais. A Pangeia permanecia reunida, cercada pelo Panthalassa e influenciada pelo mar de Tétis.', 'Muitas regiões eram quentes e áridas; intensas perturbações climáticas surgiram perto do fim do Permiano. Condições quentes e sazonais predominavam em grandes partes do continente.', 'Braquiópodes, amonoides, peixes e outros organismos viviam nos mares, antes da crise de oxigenação e acidificação do final do período. Amonites, braquiópodes e peixes compunham comunidades marinhas variadas.', 'Coníferas e outras gimnospermas, além de samambaias, ocupavam ambientes variados e foram afetadas pelas mudanças ambientais terminais. Gimnospermas dominavam muitas paisagens, com vegetação úmida junto a rios.', 'Desertos, planícies fluviais, florestas sazonais e plataformas marinhas compunham a paisagem de Pangeia. Planícies fluviais, desertos e ambientes costeiros sustentavam ecossistemas diversos.', 'Terápsidos, anfíbios, répteis e diversos invertebrados marinhos coexistiam, até as grandes perdas da extinção Permiano-Triássico. Terápsidos herbívoros e predadores ocupavam nichos importantes.', 'A ICS atualizou em junho de 2026 o início do Wuchiapingiano para aproximadamente 259,857 milhões de anos.'),
(159, 'changhsingiano', 'Changhsingiano', 'idade', 254.1400, 251.9020, 21, 'Changhsingiano corresponde a uma idade geológica do Paleozoico, entre aproximadamente 254.14 e 251.902 milhões de anos atrás. O Changhsingiano foi a última idade do Permiano e terminou com a maior extinção em massa conhecida da história da Terra. Intenso vulcanismo e alterações climáticas e oceânicas causaram perdas enormes na biodiversidade.', 'A Pangeia permanecia reunida e cercada pelo Panthalassa, com o mar de Tétis influenciando importantes regiões tropicais. Pangeia reunia grandes áreas continentais e o Panthalassa cobria grande parte dos oceanos.', 'Muitas regiões eram quentes e áridas; intensas perturbações climáticas surgiram perto do fim do Permiano. A crise terminal envolveu forte aquecimento e mudanças nos ciclos químicos globais.', 'Braquiópodes, amonoides, peixes e outros organismos viviam nos mares, antes da crise de oxigenação e acidificação do final do período. Aquecimento, acidificação e anoxia contribuíram para perdas de organismos marinhos.', 'Coníferas e outras gimnospermas, além de samambaias, ocupavam ambientes variados e foram afetadas pelas mudanças ambientais terminais. As comunidades de gimnospermas e outras plantas foram profundamente afetadas.', 'Desertos, planícies fluviais, florestas sazonais e plataformas marinhas compunham a paisagem de Pangeia. Mares, rios, planícies e florestas sazonais sofreram perturbações ambientais severas.', 'Terápsidos, anfíbios, répteis e diversos invertebrados marinhos coexistiam, até as grandes perdas da extinção Permiano-Triássico. Terápsidos, anfíbios, invertebrados marinhos e numerosos outros grupos enfrentaram extinções extensas.', 'A extinção Permiano-Triássico, associada entre outros fatores ao vulcanismo dos Trapps Siberianos, encerrou o Changhsingiano há cerca de 251,9 milhões de anos.');
